/// Largest file `read_file` returns, in bytes.
pub const MAX_READ_BYTES: u64 = 1024 * 1024;

/// The IDE's MCP server for one workspace.
#[derive(Clone)]
pub struct IdeServer {
    workspace: Arc<Workspace>,
    /// What agents may do beyond reading (SPEC-0053).
    permissions: Arc<idecraft_core::AgentPermissions>,
    /// Tests of the tools behind the database permissions: what the project file asks for counts
    /// as granted by the user, for database files inside the workspace (`SPEC-0012` v3). Never
    /// set outside tests.
    grant_requested_connections: bool,
    /// Where project trust is read from (SPEC-0278); `None`: this process's settings.
    trust: Option<idecraft_core::trust::TrustSettings>,
    /// Open debug sessions by id (SPEC-0054).
    debug_sessions: Arc<std::sync::Mutex<DebugSessions>>,
    /// Refactorings applied through this server, newest last (SPEC-0193 behaviour 7).
    undo_groups: Arc<std::sync::Mutex<idecraft_languages::undo_group::UndoGroups>>,
    /// The name the newest applied extraction introduced into a file where it was nowhere
    /// before; renaming it covers every occurrence (SPEC-0095 v4 behaviour 10, D55).
    introduced_name: Arc<std::sync::Mutex<Option<(std::path::PathBuf, String)>>>,
    /// Snapshot of the previous `file_changes` call.
    last_snapshot: Arc<std::sync::Mutex<Option<idecraft_core::Snapshot>>>,
    /// The workspace's local history, kept between calls and refreshed with what others appended
    /// (SPEC-0044 v2 behaviour 8).
    history: Arc<std::sync::Mutex<Option<idecraft_core::LocalHistory>>>,
    /// Backends started on SSH hosts, by `host|folder` (SPEC-0158).
    backends: Arc<std::sync::Mutex<std::collections::HashMap<String, idecraft_remote::Backend>>>,
    /// Remote projects opened by agents (SPEC-0317), by `host|folder`.
    remote_projects:
        Arc<std::sync::Mutex<std::collections::HashMap<String, idecraft_remote::RemoteProject>>>,
    /// Where the chosen theme is saved (SPEC-0060 v5); the user's settings folder by default.
    theme_file: Option<std::path::PathBuf>,
    /// The user's list of recent projects (SPEC-0094); the user's settings folder by default.
    recent_projects_file: Option<std::path::PathBuf>,
    /// The IDECraft log folder (SPEC-0270); the user's by default.
    log_dir: Option<std::path::PathBuf>,
    ide_settings_file: Option<std::path::PathBuf>,
    /// The connectors folder (SPEC-0300); the user's unless tests set one.
    connectors_dir: Option<std::path::PathBuf>,
    /// The folder plugins are loaded from (SPEC-0104).
    plugins_dir: Option<PathBuf>,
    /// The user's "always allow" file for commands suggested by plugins (SPEC-0276 behaviour 7).
    plugin_run_file: Option<PathBuf>,
    /// The user's keymap file (SPEC-0105); the user's settings folder by default.
    keymap_file: Option<std::path::PathBuf>,
    /// The user's named tool window layouts (SPEC-0333 behaviour 15); the user's settings folder
    /// by default.
    window_layouts_file: Option<std::path::PathBuf>,
    /// Docker daemon and `kubectl` to use instead of the ones found on the machine (tests).
    docker_host: Option<idecraft_containers::DockerHost>,
    kubectl: Option<idecraft_containers::Kubectl>,
    compose_cli: Option<idecraft_containers::compose::ComposeCli>,
    /// Extra `ssh` arguments for every host (tests: a private config and key).
    ssh_extra: Vec<String>,
    /// Package index and the file caching its names (tests: a local fake; SPEC-0171).
    package_index: Option<(String, std::path::PathBuf)>,
    /// Where the last test runs of each configuration are kept (`SPEC-0088` v3 behaviour 9);
    /// `None` keeps none.
    test_history: Option<std::path::PathBuf>,
    /// Folders searched for `uv` and `poetry` instead of `PATH` (tests; SPEC-0171 v2).
    python_tool_path: Option<std::ffi::OsString>,
    /// Files open in the window with their unsaved text (SPEC-0220); empty without a window.
    documents: idecraft_editor::documents::DocumentRegistry,
    /// The running window, which asks the user and quits (SPEC-0053 v4, SPEC-0261 v2); `None` over
    /// stdio.
    window: Option<Arc<dyn window::Window>>,
    /// The answers of this MCP session (SPEC-0053 v4 behaviours 8 and 9).
    session: Arc<std::sync::Mutex<SessionAnswers>>,
    /// How to cancel the `run_sql` call running on a connection, by connection name
    /// (`SPEC-0093` v3 behaviour 12).
    running_sql:
        Arc<std::sync::Mutex<std::collections::HashMap<String, idecraft_database::CancelHandle>>>,
    tool_router: ToolRouter<Self>,
}

/// Rights the user allowed "always" or denied during one MCP session, keyed by right (`write`) or by
/// connection and permission (`db:<connection>:modify-data`).
#[derive(Debug, Default)]
struct SessionAnswers {
    allowed: std::collections::BTreeSet<String>,
    denied: std::collections::BTreeSet<String>,
    /// The emergency stops seen when `ui` was last checked (`SPEC-0319` behaviour 37).
    ui_stop_generation: u64,
}

/// The client and action of the tool call being served, for the question in the window.
#[derive(Debug, Clone)]
struct CallInfo {
    client: String,
    action: String,
    /// The rights checked during the call, each with whether it was given (`SPEC-0053` v7
    /// behaviour 11).
    rights: std::sync::Arc<std::sync::Mutex<Vec<(&'static str, bool)>>>,
    /// The database permissions decided during the call, one entry per decision (`SPEC-0012`
    /// v3 behaviour 16); they go into the call's one line of the agent log.
    database: std::sync::Arc<std::sync::Mutex<Vec<serde_json::Value>>>,
}

tokio::task_local! {
    static CALL: CallInfo;
}

/// What became of asking the user.
enum Asked {
    Once,
    Always,
    Denied,
    /// Nobody was asked or nobody answered; the text says which (it replaces "nobody was asked" in
    /// the refusal; empty keeps it).
    Unanswered(&'static str),
}

