/// What `generate_code` makes.
#[derive(Debug, Clone, Copy, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum GenerateKindArg {
    /// A constructor taking the fields.
    Constructor,
    /// Getters.
    Getters,
    /// Setters for non-final fields.
    Setters,
    /// Getters and setters.
    GettersAndSetters,
    /// `equals` and `hashCode`.
    EqualsHashCode,
    /// `toString`.
    ToString,
}

impl From<GenerateKindArg> for idecraft_languages::jvm::GenerateKind {
    fn from(k: GenerateKindArg) -> Self {
        match k {
            GenerateKindArg::Constructor => Self::Constructor,
            GenerateKindArg::Getters => Self::Getters,
            GenerateKindArg::Setters => Self::Setters,
            GenerateKindArg::GettersAndSetters => Self::GettersAndSetters,
            GenerateKindArg::EqualsHashCode => Self::EqualsHashCode,
            GenerateKindArg::ToString => Self::ToString,
        }
    }
}

