type RemoteDebugStarted = (
    idecraft_debugger::DebugSession,
    std::collections::BTreeMap<std::path::PathBuf, Vec<idecraft_debugger::Breakpoint>>,
    idecraft_debugger::StopState,
);

/// The breakpoints of a remote debug tool: relative paths are the project's.
fn remote_breakpoints(
    list: &Option<Vec<RemoteBreakpointArg>>,
    root: &str,
) -> std::collections::BTreeMap<std::path::PathBuf, Vec<idecraft_debugger::SourceBreakpoint>> {
    let mut map: std::collections::BTreeMap<_, Vec<_>> = Default::default();
    for b in list.iter().flatten() {
        let path = if b.path.starts_with('/') {
            std::path::PathBuf::from(&b.path)
        } else {
            std::path::Path::new(root).join(&b.path)
        };
        map.entry(path)
            .or_default()
            .push(idecraft_debugger::SourceBreakpoint {
                line: b.line,
                ..Default::default()
            });
    }
    map
}

/// The launch request for a host plan (SPEC-0322; the same shapes as the window's).
fn remote_launch_arguments(
    kind: idecraft_debugger::Kind,
    plan: &serde_json::Value,
) -> serde_json::Value {
    use idecraft_debugger::Kind;
    let (program, args, cwd, env) = (&plan["program"], &plan["args"], &plan["cwd"], &plan["env"]);
    match kind {
        Kind::Python => {
            let mut a = serde_json::json!({
                "type": "python", "request": "launch", "program": program, "args": args,
                "cwd": cwd, "env": env, "console": "internalConsole", "justMyCode": true,
                "stopOnEntry": false,
            });
            if !plan["interpreter"].is_null() {
                a["python"] = plan["interpreter"].clone();
            }
            a
        }
        Kind::Java => serde_json::json!({
            "type": "java", "request": "launch", "mainClass": program, "args": "",
            "cwd": cwd, "env": env, "console": "internalConsole", "stopOnEntry": false,
        }),
        Kind::Kotlin => serde_json::json!({ "projectRoot": cwd, "mainClass": program, "cwd": cwd }),
        // The words after `go`, checked before the start (SPEC-0039 v7 behaviour 11).
        Kind::Go => {
            let words: Vec<String> = serde_json::from_value(args.clone()).unwrap_or_default();
            let env: std::collections::BTreeMap<String, String> =
                serde_json::from_value(env.clone()).unwrap_or_default();
            let cwd = std::path::PathBuf::from(cwd.as_str().unwrap_or_default());
            idecraft_debugger::go_launch(&words, &cwd, &env).unwrap_or_default()
        }
        Kind::Node | Kind::PackageScript => {
            let args: Vec<String> = serde_json::from_value(args.clone()).unwrap_or_default();
            let env: std::collections::BTreeMap<String, String> =
                serde_json::from_value(env.clone()).unwrap_or_default();
            let path = std::path::PathBuf::from(program.as_str().unwrap_or_default());
            let cwd = std::path::PathBuf::from(cwd.as_str().unwrap_or_default());
            idecraft_debugger::node_launch(
                &path,
                (kind == Kind::PackageScript).then_some(path.as_path()),
                &args,
                &cwd,
                &env,
            )
        }
        Kind::Native | Kind::Browser => {
            let env: Vec<String> = env
                .as_object()
                .map(|o| {
                    o.iter()
                        .map(|(k, v)| format!("{k}={}", v.as_str().unwrap_or_default()))
                        .collect()
                })
                .unwrap_or_default();
            serde_json::json!({
                "program": program, "args": args, "cwd": cwd, "env": env, "stopOnEntry": false,
            })
        }
    }
}

