/// The paths of a status that changelists hold: every change but an untracked file
/// (`SPEC-0335` behaviour 2).
fn changelist_paths(status: &[idecraft_vcs::FileStatus]) -> Vec<String> {
    status
        .iter()
        .filter(|s| !(s.staged.is_none() && s.unstaged == Some(idecraft_vcs::ChangeKind::Added)))
        .map(|s| s.path.clone())
        .collect()
}

/// The renames of a status as the changelists take them: old path, new path.
fn changelist_renames(renames: &[idecraft_vcs::Rename]) -> Vec<(String, String)> {
    renames
        .iter()
        .map(|r| (r.from.clone(), r.to.clone()))
        .collect()
}

