/// A bookmark as the bookmark tools return it.
fn bookmark_json(listed: &idecraft_core::bookmarks::Listed) -> serde_json::Value {
    let b = &listed.bookmark;
    let mut v = serde_json::json!({
        "path": b.file,
        "line": b.line + 1,
        "mnemonic": b.mnemonic.map(String::from),
        "description": b.description,
        "text": listed.text,
    });
    if listed.missing {
        v["missing"] = serde_json::json!(true);
    }
    v
}

/// The mnemonic a bookmark tool was given: one of the 36 characters.
fn bookmark_mnemonic(text: &str) -> Result<char, McpError> {
    let mut chars = text.trim().chars();
    chars
        .next()
        .filter(|_| chars.next().is_none())
        .and_then(idecraft_core::bookmarks::mnemonic)
        .ok_or_else(|| {
            McpError::invalid_params(format!("mnemonic `{text}`: one of 1-9, 0, A-Z"), None)
        })
}

