/// Arguments of `edit_table_data`.
#[derive(Debug, Deserialize, schemars::JsonSchema)]
pub struct EditTableDataArgs {
    /// Connection name from `list_connections`.
    pub connection: String,
    /// Table name.
    pub table: String,
    /// Changes in order.
    pub changes: Vec<ChangeArg>,
    /// Apply the changes in one transaction (default: only return the SQL).
    pub apply: Option<bool>,
}

/// One change of `edit_table_data`. Values are strings, numbers, booleans or null.
#[derive(Debug, Deserialize, schemars::JsonSchema)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum ChangeArg {
    /// Change cells of one row.
    Update {
        /// The row as loaded: key columns and the old values of the changed columns.
        row: BTreeMap<String, serde_json::Value>,
        /// New values by column.
        set: BTreeMap<String, serde_json::Value>,
    },
    /// Add a row; columns left out get their defaults.
    Insert {
        /// Values by column.
        values: BTreeMap<String, serde_json::Value>,
    },
    /// Delete one row.
    Delete {
        /// The row as loaded: key columns and any values to check before deleting.
        row: BTreeMap<String, serde_json::Value>,
    },
}

