/// Arguments of `compare_schemas`.
#[derive(Debug, Deserialize, schemars::JsonSchema)]
pub struct CompareSchemasArgs {
    /// Connection whose schema is the desired state.
    pub source: String,
    /// Connection whose schema is to be changed; may be `source` with another `target_schema`.
    pub target: String,
    /// Schema of `source` to compare (default: its current schema). PostgreSQL, DuckDB, MySQL and
    /// MariaDB only.
    pub source_schema: Option<String>,
    /// Schema of `target` to change (default: its current schema); `script` then starts by making it
    /// current. PostgreSQL, DuckDB, MySQL and MariaDB only.
    pub target_schema: Option<String>,
    /// Put destructive statements (dropping tables, columns or views, converting types) into
    /// `script` too (default false: they are listed but left out).
    pub include_destructive: Option<bool>,
    /// One table or view of the source to compare alone (SPEC-0110 v12 behaviour 18); give
    /// `target_object` with it.
    pub source_object: Option<String>,
    /// The table or view of the target it is compared with; the statements change it in place.
    pub target_object: Option<String>,
}

/// Arguments of `rename_sql_object`.
#[derive(Debug, Deserialize, schemars::JsonSchema)]
pub struct RenameSqlObjectArgs {
    /// Connection name from `list_connections`.
    pub connection: String,
    /// Table or view to rename, or whose column to rename (not needed for `index` or `routine`).
    #[serde(default)]
    pub table: String,
    /// Column to rename (default: rename the table).
    pub column: Option<String>,
    /// Index to rename instead (SPEC-0164).
    pub index: Option<String>,
    /// Function or procedure to rename instead (SPEC-0164).
    pub routine: Option<String>,
    /// Sequence to rename instead (SPEC-0164 v3).
    pub sequence: Option<String>,
    /// Named constraint of `table` to rename instead (SPEC-0164 v3).
    pub constraint: Option<String>,
    /// New name.
    pub new_name: String,
    /// SQL text to rewrite (default: all `.sql` files of the workspace).
    pub sql: Option<String>,
    /// Run the ALTER TABLE statement and then write the workspace's `.sql` files (default false;
    /// needs the `modify-schema` permission; not with `sql`).
    pub apply: Option<bool>,
    /// With `apply`: also change files of another dialect (default false; SPEC-0019 v2).
    pub include_other_dialects: Option<bool>,
    /// With `apply`: also rename the offered constraints and indexes whose names embed the old
    /// name (default true; SPEC-0019 v2).
    pub rename_derived: Option<bool>,
    /// With `apply`: indexes into `outside_project` of the preview to change too: `.sql` files
    /// that are not the project's own sources (a virtual environment, build output, excluded or
    /// ignored files). None by default; a file of another dialect also needs
    /// `include_other_dialects` (SPEC-0019 v4 behaviour 12).
    pub include_outside: Option<Vec<usize>>,
}

