/// The scope of `search_in_files` and `replace_in_files_preview` (SPEC-0029 v2 behaviour 8).
fn find_scope(
    mask: Option<&str>,
    directory: Option<&str>,
    include_non_project: Option<bool>,
) -> idecraft_core::SearchScope {
    let directory = directory.map(str::trim).filter(|d| !d.is_empty());
    idecraft_core::SearchScope {
        mask: mask.map(str::to_owned),
        place: match directory {
            Some(dir) => idecraft_core::SearchPlace::Directory(dir.into()),
            None => idecraft_core::SearchPlace::Project,
        },
        include_non_project: include_non_project.unwrap_or(false),
    }
}

/// Most paths named in `not_searched`.
const NOT_SEARCHED_PATHS: usize = 20;

/// What a search left out because it is not the project's own (SPEC-0029 v2 behaviour 10):
/// counts, the first paths with the reason, and one line that says how to search them.
fn not_searched_json(found: &idecraft_core::WorkspaceSearch) -> serde_json::Value {
    let (folders, files) = found.not_searched_counts();
    let paths: Vec<serde_json::Value> = found
        .not_searched
        .iter()
        .take(NOT_SEARCHED_PATHS)
        .map(|o| {
            serde_json::json!({
                "path": o.path.to_string_lossy(), "folder": o.folder, "reason": o.why.reason(),
            })
        })
        .collect();
    let mut out = serde_json::json!({"folders": folders, "files": files, "paths": paths});
    if let Some(line) = found.not_searched_line() {
        out["note"] = serde_json::json!(format!(
            "{line}. Pass `include_non_project: true` to search them, or name one as `directory`."
        ));
    }
    out
}

