/// `cpu` or `memory`.
fn profile_kind(kind: Option<&str>) -> Result<idecraft_profiler::Kind, McpError> {
    match kind.unwrap_or("cpu") {
        "cpu" => Ok(idecraft_profiler::Kind::Cpu),
        "memory" => Ok(idecraft_profiler::Kind::Memory),
        other => Err(McpError::invalid_params(
            format!("kind must be cpu or memory, not {other}"),
            None,
        )),
    }
}

