/// Largest stdout/stderr/body text an agent tool returns, in bytes.
const MAX_AGENT_OUTPUT: usize = 256 * 1024;

/// Cuts `text` to [`MAX_AGENT_OUTPUT`] at a character boundary; returns whether it was cut.
fn cap(text: &mut String) -> bool {
    if text.len() <= MAX_AGENT_OUTPUT {
        return false;
    }
    let mut end = MAX_AGENT_OUTPUT;
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    text.truncate(end);
    true
}

fn unix_time() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn outcome_json(mut o: idecraft_core::RunOutcome) -> serde_json::Value {
    let stdout_cut = cap(&mut o.stdout);
    let stderr_cut = cap(&mut o.stderr);
    let success = o.success();
    let mut v = serde_json::to_value(&o).unwrap_or_default();
    v["success"] = success.into();
    v["stdout_truncated"] = stdout_cut.into();
    v["stderr_truncated"] = stderr_cut.into();
    v
}

/// `rules` with the breakpoint it depends on relative to the workspace `root`, as agents write it
/// (`SPEC-0127` v3).
fn relative_rules(
    root: &std::path::Path,
    mut rules: idecraft_debugger::BreakpointRules,
) -> idecraft_debugger::BreakpointRules {
    if let Some((path, line)) = rules
        .depends_on
        .as_deref()
        .and_then(idecraft_debugger::breakpoint_place)
    {
        let rel = path.strip_prefix(root).map(PathBuf::from).unwrap_or(path);
        rules.depends_on = Some(format!("{}:{line}", rel.display()));
    }
    rules
}

/// Open debug sessions with the thread that stopped last.
#[derive(Default)]
struct DebugSessions {
    next: u64,
    open: std::collections::HashMap<u64, (idecraft_debugger::DebugSession, Option<i64>)>,
}

/// At most this many debug sessions are open at once.
const MAX_DEBUG_SESSIONS: usize = 4;
/// Frames returned per stop.
const DEBUG_FRAMES: usize = 20;

/// Waits for `session` to stop or end, remembers the stopped thread and describes the state with
/// the output so far (as `debug_resume` answers).
fn debug_state(
    session: &mut idecraft_debugger::DebugSession,
    thread: &mut Option<i64>,
    wait: std::time::Duration,
) -> Result<serde_json::Value, String> {
    let mut state = session
        .wait_state(wait, DEBUG_FRAMES)
        .map_err(|e| e.to_string())?;
    name_exception(session, &mut state);
    *thread = match &state {
        idecraft_debugger::StopState::Stopped { thread_id, .. } => Some(*thread_id),
        _ => None,
    };
    Ok(serde_json::json!({
        "state": state,
        "output": session.output(),
        "console": session.console(),
    }))
}

