/// The line breakpoint a debugging tool was given; text that is empty counts as not given.
fn source_breakpoint(
    line: u64,
    condition: Option<String>,
    hit_condition: Option<String>,
    log_message: Option<String>,
) -> idecraft_debugger::SourceBreakpoint {
    let text = |s: Option<String>| s.filter(|s| !s.trim().is_empty());
    idecraft_debugger::SourceBreakpoint {
        line,
        condition: text(condition),
        hit_condition: text(hit_condition),
        log_message: text(log_message),
        ..Default::default()
    }
}

/// The exception and function breakpoints a debugging tool was given (`SPEC-0146` behaviour 6),
/// on top of `base` (the workspace's saved ones, or none): what is not given stays as in `base`.
fn special_breakpoints(
    mut base: idecraft_debugger::SpecialBreakpoints,
    exception_breakpoints: Option<&str>,
    exception_types: Option<&str>,
    function_breakpoints: Option<&[String]>,
) -> Result<idecraft_debugger::SpecialBreakpoints, McpError> {
    match exception_breakpoints {
        None | Some("") => {}
        Some("none") => (base.caught, base.uncaught) = (false, false),
        Some("caught") => (base.caught, base.uncaught) = (true, false),
        Some("uncaught") => (base.caught, base.uncaught) = (false, true),
        Some("both") => (base.caught, base.uncaught) = (true, true),
        Some(other) => {
            return Err(McpError::invalid_params(
                format!("exception_breakpoints `{other}`: caught, uncaught, both or none"),
                None,
            ));
        }
    }
    if let Some(types) = exception_types {
        base.exception_condition = types.trim().to_owned();
    }
    if let Some(functions) = function_breakpoints {
        base.functions = functions
            .iter()
            .filter(|n| !n.trim().is_empty())
            .map(|name| idecraft_debugger::FunctionBreakpoint {
                name: name.trim().to_owned(),
                ..idecraft_debugger::FunctionBreakpoint::default()
            })
            .collect();
    }
    Ok(base)
}

/// Names the exception of a stop on one (`SPEC-0146` behaviour 5): `exception: <type or
/// description>` where the adapter can tell.
fn name_exception(
    session: &mut idecraft_debugger::DebugSession,
    state: &mut idecraft_debugger::StopState,
) {
    if let idecraft_debugger::StopState::Stopped {
        reason, thread_id, ..
    } = state
        && reason == "exception"
        && let Some(info) = session.exception_info(*thread_id)
    {
        *reason = format!("exception: {info}");
    }
}

