/// Whether `program` is debugged as Go (SPEC-0039 v7 behaviour 11): a `.go` file, or a folder
/// with a `go.mod` or Go files.
fn is_go_program(program: &std::path::Path) -> bool {
    if program.extension().is_some_and(|e| e == "go") {
        return true;
    }
    program.join("go.mod").is_file()
        || std::fs::read_dir(program).is_ok_and(|entries| {
            entries
                .flatten()
                .any(|e| e.path().extension().is_some_and(|x| x == "go"))
        })
}

/// The words after `go` that `debug_start` stands for: `run <file or folder> <args>`, or for
/// `go_test` and a `_test.go` file `test -v [-run ^Name$] <folder> [-args <args>]`.
fn go_words(program: &std::path::Path, test: Option<&str>, args: &[String]) -> Vec<String> {
    let file = program.extension().is_some_and(|e| e == "go");
    let test_file = file
        && program
            .file_stem()
            .is_some_and(|s| s.to_string_lossy().ends_with("_test"));
    if test.is_none() && !test_file {
        let mut words = vec!["run".to_owned(), program.display().to_string()];
        words.extend(args.iter().cloned());
        return words;
    }
    let folder = if file {
        program.parent().unwrap_or(program)
    } else {
        program
    };
    let mut words = vec!["test".to_owned(), "-v".to_owned()];
    if let Some(name) = test.map(str::trim).filter(|n| !n.is_empty()) {
        // A plain name is that test alone; anything else is go's own pattern.
        let plain = name.chars().all(|c| c.is_alphanumeric() || c == '_');
        words.push("-run".into());
        words.push(if plain {
            format!("^{name}$")
        } else {
            name.to_owned()
        });
    }
    words.push(folder.display().to_string());
    if !args.is_empty() {
        words.push("-args".into());
        words.extend(args.iter().cloned());
    }
    words
}

