/// Time a language server gets per code-insight query.
/// The identifier around a char column of a line (`find_usages`).
fn word_at(line: &str, column: usize) -> String {
    let chars: Vec<char> = line.chars().collect();
    let is = |c: char| c.is_alphanumeric() || c == '_';
    let (mut a, mut b) = (column.min(chars.len()), column.min(chars.len()));
    while a > 0 && is(chars[a - 1]) {
        a -= 1;
    }
    while b < chars.len() && is(chars[b]) {
        b += 1;
    }
    chars[a..b].iter().collect()
}

const INSIGHT_WAIT: std::time::Duration = std::time::Duration::from_secs(60);

/// Largest export `export_data` returns, in bytes.
pub const MAX_EXPORT_BYTES: usize = 5 * 1024 * 1024;

