    #[tool(
        description = "Extract Interface for the class at (or around) a position of a TypeScript file (SPEC-0320): creates the interface before the type with the signatures of `members` and adds it to `implements` (or `extends` of an interface). dry_run defaults to true and returns the edits per file; dry_run=false writes them. Refuses with the reasons when it cannot."
    )]
    async fn extract_interface(
        &self,
        Parameters(args): Parameters<ExtractClassArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (root, file) = self.source(&args.path)?;
        // Against the shown texts of the file and the other unsaved files (SPEC-0220 v4
        // behaviour 13).
        let seen = self.shown_texts(&file);
        let text = Self::text_in(&seen, &file);
        let files = Self::planned(
            &seen,
            idecraft_languages::ts_refactor::extract_interface_in(
                &root,
                &file,
                text.as_deref(),
                args.line,
                args.character,
                &args.name,
                &args.members,
                INSIGHT_WAIT,
            ),
        )
        .await
        .map_err(|e| McpError::invalid_params(e, None))?;
        self.finish_class_refactoring(&root, "Extract Interface", files, args.dry_run, &seen)
            .await
    }

    #[tool(
        description = "Extract Superclass for the class at (or around) a position of a JavaScript or TypeScript file (SPEC-0320): creates `class name` before it with the chosen `members`, moves them there and makes the class extend it. dry_run defaults to true and returns the edits per file; dry_run=false writes them. Refuses with the reasons when it cannot."
    )]
    async fn extract_superclass(
        &self,
        Parameters(args): Parameters<ExtractClassArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (root, file) = self.source(&args.path)?;
        // The shown text (SPEC-0220 v3 behaviour 13).
        let text = self.read_document(&file)?;
        let files = idecraft_languages::ts_refactor::extract_superclass(
            &file,
            &text,
            args.line,
            args.character,
            &args.name,
            &args.members,
        )
        .map_err(|e| McpError::invalid_params(e, None))?;
        let seen = [(file.clone(), text)];
        self.finish_class_refactoring(&root, "Extract Superclass", files, args.dry_run, &seen)
            .await
    }

    #[tool(
        description = "Pull Members Up for the class at (or around) a position of a JavaScript or TypeScript file (SPEC-0320): moves `members` to the end of the direct supertype named `target` (may be left out when there is only one), or adds their signature when it is an interface or `abstract` is true (an abstract class). dry_run defaults to true and returns the edits per file; dry_run=false writes them. Refuses with the reasons when it cannot."
    )]
