    #[tool(
        description = "Override/Implement Methods for the Java class at a position (SPEC-0122 v3, through jdtls) or the Kotlin class, interface or object at a position (v6, from the project's syntax trees; functions and properties of project supertypes and of kotlin.Any): without `add` lists the methods the class can override with name, parameters, declaring class, `unimplemented` (abstract, still to implement) and, for Java, `return_type` where the declaring type's source is in the project (SPEC-0122 v7). With `add` (names as listed, `name` or `name(Type, ...)`) adds them with @Override and a default body (Kotlin: `override`, with `TODO()` for an abstract member, else a call of the supertype's); dry_run defaults to true and returns the edits and the new text, dry_run=false writes the file (needs the write right) and refuses if it changed meanwhile."
    )]
    async fn override_methods(
        &self,
        Parameters(args): Parameters<OverrideMethodsArgs>,
    ) -> Result<CallToolResult, McpError> {
        if !args.path.ends_with(".java") && !args.path.ends_with(".kt") {
            return Err(McpError::invalid_params("not a .java or .kt file", None));
        }
        let (root, file) = self.source(&args.path)?;
        // Against the shown text (SPEC-0220 v3 behaviour 13).
        let shown = self.editor_text(&file);
        let (ty, methods) = idecraft_languages::java_structure::overridable_methods_in(
            &root,
            &file,
            shown.as_deref(),
            args.line,
            args.character,
            INSIGHT_WAIT,
        )
        .await
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let wanted = args.add.unwrap_or_default();
        if wanted.is_empty() {
            return json_result(serde_json::json!({ "type": ty, "methods": methods }));
        }
        let chosen: Vec<_> = methods
            .iter()
            .filter(|m| wanted.iter().any(|w| *w == m.name || *w == m.label()))
            .cloned()
            .collect();
        if chosen.is_empty() {
            return Err(McpError::invalid_params(
                format!("none of {wanted:?} can be overridden here"),
                None,
            ));
        }
        let text = self.read_document(&file)?;
        let files = idecraft_languages::java_structure::add_overridable_methods_in(
            &root,
            &file,
            Some(&text),
            args.line,
            args.character,
            &chosen,
            INSIGHT_WAIT,
        )
        .await
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let edits: Vec<_> = files
            .iter()
            .filter(|f| f.path.canonicalize().ok() == file.canonicalize().ok())
            .flat_map(|f| f.edits.clone())
            .collect();
        let new_text = idecraft_languages::rename::apply_edits(&text, &edits)
            .map_err(|e| McpError::internal_error(e, None))?;
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({ "applied": applied, "added": chosen, "text": new_text }))
    }

    #[tool(
        description = "Delegate Methods for the Java class at a position (SPEC-0122 v4, through jdtls): without `add` lists its fields with the methods each can forward to (those every object has left out). With `field` and `add` (names as listed) adds forwarding methods; dry_run defaults to true and returns the new text, dry_run=false writes the file (needs the write right) and refuses if it changed meanwhile."
    )]
    async fn delegate_methods(
        &self,
        Parameters(args): Parameters<DelegateMethodsArgs>,
    ) -> Result<CallToolResult, McpError> {
        if !args.path.ends_with(".java") {
            return Err(McpError::invalid_params("not a .java file", None));
        }
        let (root, file) = self.source(&args.path)?;
        // Against the shown text (SPEC-0220 v3 behaviour 13).
        let shown = self.editor_text(&file);
        let fields = idecraft_languages::java_generate::delegate_fields_in(
            &root,
            &file,
            shown.as_deref(),
            args.line,
            args.character,
            INSIGHT_WAIT,
        )
        .await
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let wanted = args.add.unwrap_or_default();
        if wanted.is_empty() {
            return json_result(serde_json::json!({ "fields": fields }));
        }
        let field = args
            .field
            .as_deref()
            .and_then(|n| fields.iter().find(|f| f.name == n))
            .ok_or_else(|| McpError::invalid_params("name a listed field in `field`", None))?;
        let chosen: Vec<_> = field
            .methods
            .iter()
            .filter(|m| wanted.iter().any(|w| *w == m.name || *w == m.label()))
            .map(|m| (field.clone(), m.clone()))
            .collect();
        if chosen.is_empty() {
            return Err(McpError::invalid_params(
                format!("none of {wanted:?} can be delegated to `{}`", field.name),
                None,
            ));
        }
        let text = self.read_document(&file)?;
        let files = idecraft_languages::java_generate::add_delegate_methods_in(
            &root,
            &file,
            Some(&text),
            args.line,
            args.character,
            &chosen,
            INSIGHT_WAIT,
        )
        .await
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let edits: Vec<_> = files
            .iter()
            .filter(|f| f.path.canonicalize().ok() == file.canonicalize().ok())
            .flat_map(|f| f.edits.clone())
            .collect();
        let new_text = idecraft_languages::rename::apply_edits(&text, &edits)
            .map_err(|e| McpError::internal_error(e, None))?;
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({ "applied": applied, "text": new_text }))
    }

    #[tool(
        description = "The import hint for a Java file (SPEC-0122 v4, through jdtls): the unresolved class names the server reports, each with its 0-based position and the fully qualified classes that would import it. Apply one with apply_code_action and the title `Import 'Name' (package)`. Reads only."
    )]
    async fn import_hint(
        &self,
        Parameters(args): Parameters<ImportHintArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::java_generate::{import_candidates_at, unresolved_name};
        if !args.path.ends_with(".java") {
            return Err(McpError::invalid_params("not a .java file", None));
        }
        let (root, file) = self.source(&args.path)?;
        let diagnostics = idecraft_languages::lsp::file_diagnostics(&root, &file, INSIGHT_WAIT)
            .await
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let mut hints = Vec::new();
        for d in &diagnostics {
            let Some(name) = unresolved_name(&d.message) else {
                continue;
            };
            let candidates = import_candidates_at(
                &root,
                &file,
                None,
                d.start_line,
                d.start_character,
                name,
                INSIGHT_WAIT,
            )
            .await
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
            hints.push(serde_json::json!({
                "name": name,
                "line": d.start_line,
                "character": d.start_character,
                "candidates": candidates,
            }));
        }
        json_result(serde_json::json!({ "hints": hints }))
    }

    #[tool(
        description = "Surround With for Java (SPEC-0122 v3): wraps whole statement lines start_line..end_line (1-based, inclusive) of a workspace .java file in `kind` (if, if_else, while, do_while, for, try_catch, try_finally, try_catch_finally, synchronized, runnable, braces), indenting them one step. A local variable declared in the lines and used after them is declared before the construct and assigned inside. dry_run defaults to true and returns the new text; dry_run=false writes the file (needs the write right) and refuses if it changed meanwhile."
    )]
    async fn surround_with(
        &self,
        Parameters(args): Parameters<SurroundWithArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::java_structure::{SurroundKind, offset_of, surround};
        if !args.path.ends_with(".java") {
            return Err(McpError::invalid_params("not a .java file", None));
        }
        let kind = SurroundKind::parse(&args.kind).ok_or_else(|| {
            McpError::invalid_params(format!("unknown kind `{}`", args.kind), None)
        })?;
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let start = offset_of(&text, args.start_line.saturating_sub(1), 0);
        let end = offset_of(
            &text,
            args.end_line.max(args.start_line).saturating_sub(1),
            usize::MAX,
        );
        let s = surround(&text, start..end, kind).map_err(|e| McpError::invalid_params(e, None))?;
        let mut new_text = text.clone();
        new_text.replace_range(s.range.clone(), &s.text);
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({ "applied": applied, "text": new_text }))
    }

    #[tool(
        description = "Signatures of the call around a position of a workspace file (parameter info), from its language server: each overload's label, documentation and parameter ranges (chars of the label), the active overload and the parameter the position is in. Lines and characters are 0-based; characters count Unicode scalar values. Returns null outside a call."
    )]
    async fn signature_help(
        &self,
        Parameters(args): Parameters<PositionArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (root, file) = self.source(&args.path)?;
        let result = idecraft_languages::insight::signature_help_in(
            &root,
            &file,
            None,
            args.line,
            args.character,
            INSIGHT_WAIT,
        )
        .await
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(result)
    }

    #[tool(
        description = "Format a workspace file (or a range) with its language server's formatter, or, as Reformat Code does in the window, with the project's own Prettier: a whole file (no `range`) of a trusted project that has `node_modules/.bin/prettier` in or above the file's package (JavaScript, TypeScript, Vue, CSS, SCSS, Less, JSON, Markdown, YAML, HTML, GraphQL) is formatted with it and the project's configuration, and `tab_size`/`insert_spaces` have no effect there; with a range, without Prettier or in safe mode the language server formats. The answer names what formatted in `formatter` (`prettier`, or the server's program) and `formatter_path`. A Python file is formatted with a formatter that is already installed: `ruff` (`ruff format`), else `black`, from the selected environment first (trusted projects only), then from PATH; it runs in the project root on the file's text through standard input, so `pyproject.toml`/`ruff.toml` apply, and nothing is downloaded or installed — without one the answer says what to install (`python_install_packages`); the answer names it in `formatter` and `formatter_path`, and `tab_size`/`insert_spaces` have no effect there. An SQL file and, without Prettier, a Markdown file are formatted by IDECraft itself (`formatter` is `idecraft`, whole files only): SQL gets one clause per line (joins indented under `from`, `and`/`or` under `where`), one row per line after `values`, one column per line in `create table` with aligned types, spaces around operators and after commas — only whitespace between tokens changes, keyword case, comments and strings stay, statements other than queries, insert, update, delete, create table and create view stay as written, and a file that cannot be read without doubt (an open string or comment, parentheses that do not match, a backslash before a quote) is refused with the line; Markdown gets a blank line around headings and aligned table columns, nothing else. `tab_size` and `insert_spaces` default to the file's `.editorconfig`, else to Code Style for its language (2 spaces for JSON, YAML, SCSS and Less, 4 for CSS and most others); trimming trailing whitespace and the final newline follow the `.editorconfig` where it sets them. A `range` of a file whose language server formats whole files only (gopls, rust-analyzer, taplo, yaml-language-server, svelteserver) or formats ranges unreliably (kotlin-language-server) is formatted through the whole file: the lines of the range get the layout of the whole file's result and every other line stays; when that result changes more than white space in or next to those lines, the answer is an error and nothing changes. When nothing can format the file the answer is an error that says why and what to do: the file type has no formatter (unknown types), the language server has none (Groovy), the tool it formats with is missing (shfmt for shell scripts, a `.scalafmt.conf` for Scala), or it showed an error or asked a question instead of formatting. dry_run defaults to true and returns the edits, the formatted text and whether only whitespace changes; dry_run=false writes the file, refusing if it changed since."
    )]
    async fn format_file(
        &self,
        Parameters(args): Parameters<FormatFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::format::{
            FormatOptions, OWN_FORMATTER, OwnFormatter, plan_format_in,
        };
        let (root, file) = self.source(&args.path)?;
        let range = args
            .range
            .map(|[sl, sc, el, ec]| idecraft_languages::insight::Range {
                start_line: sl,
                start_character: sc,
                end_line: el,
                end_character: ec,
            });
        // Python: the project's ruff or black; pyright has no formatter (`SPEC-0329`).
        if LanguageId::detect(&file) == Some(LanguageId::Python) {
            return self
                .python_format_file(&root, &file, range, args.dry_run.unwrap_or(true))
                .await;
        }
        // The project's Prettier where Reformat Code uses it: a whole file of a trusted project
        // (`SPEC-0123` v4 behaviour 5a).
        if range.is_none()
            && self.require_trusted().is_ok()
            && let Some(tool) = idecraft_languages::js_tools::find_prettier(&root, &file)
        {
            return self
                .prettier_format_file(&root, &file, tool, args.dry_run.unwrap_or(true))
                .await;
        }
        // The indentation nobody chose: `.editorconfig`, else Code Style for the language
        // (`SPEC-0043` v5 behaviour 1).
        let style = self
            .ide_settings_file
            .as_deref()
            .map(idecraft_core::load_ide_settings)
            .unwrap_or_default()
            .code_style;
        let defaults = FormatOptions::for_file(&file, &style);
        let options = FormatOptions {
            tab_size: args.tab_size.unwrap_or(defaults.tab_size),
            insert_spaces: args.insert_spaces.unwrap_or(defaults.insert_spaces),
            ..defaults
        };
        let own = OwnFormatter::of(&file);
        // The server formats the shown text (SPEC-0220 v3 behaviour 13).
        let shown = self.editor_text(&file);
        let planned = match (own, &range) {
            // IDECraft's own SQL formatter, which lives with the SQL lexer (behaviour 11).
            (Some(OwnFormatter::Sql), None) => shown
                .clone()
                .map(Ok)
                .unwrap_or_else(|| std::fs::read_to_string(&file))
                .map_err(|e| idecraft_languages::lsp::LspError::Io(e.to_string()))
                .and_then(|old| {
                    let new =
                        idecraft_database::sql_format::format_sql(&old, options.tab_size as usize);
                    OwnFormatter::Sql.plan(&file, &old, new)
                }),
            _ => {
                plan_format_in(
                    &root,
                    &file,
                    shown.as_deref(),
                    range.as_ref(),
                    options,
                    INSIGHT_WAIT,
                )
                .await
            }
        };
        let mut plan = planned.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            // Through the buffer when the file is open (SPEC-0220 v3 behaviours 13 and 14).
            let seen = Self::seen_text(&file, &shown);
            self.write_file_edits(std::slice::from_ref(&plan.edits), &seen, None)
                .await?;
        }
        if let Ok(rel) = plan.edits.path.strip_prefix(&root) {
            plan.edits.path = rel.to_path_buf();
        }
        // The server that formatted (`SPEC-0043` v3 behaviour 7), or IDECraft itself (v5).
        let server = LanguageId::detect(&file)
            .filter(|_| own.is_none())
            .and_then(|l| idecraft_languages::servers::resolve_for(l, &root).ok());
        json_result(serde_json::json!({
            "applied": applied,
            "plan": plan,
            "formatter": match own {
                Some(_) => Some(OWN_FORMATTER),
                None => server.as_ref().map(|s| s.candidate.program),
            },
            "formatter_path": server.as_ref().map(|s| &s.command),
        }))
    }

    #[tool(
        description = "Local history of a workspace file, independent of Git: records the file's current state, then lists its revisions newest first (id, time in ms, size, label, deleted). With `revision`, also returns that revision's content as text."
    )]
    async fn local_history(
        &self,
        Parameters(args): Parameters<LocalHistoryArgs>,
    ) -> Result<CallToolResult, McpError> {
        let path = self.history_path(&args.path)?;
        let (revisions, content) = self.with_history(|history| {
            history
                .record(&path)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
            let content = match args.revision {
                Some(r) => history
                    .content(&path, r)
                    .map_err(|e| McpError::invalid_params(e.to_string(), None))?
                    .map(|b| String::from_utf8_lossy(&b).into_owned()),
                None => None,
            };
            Ok((history.revisions(&path), content))
        })?;
        json_result(serde_json::json!({
            "path": path,
            "revisions": revisions,
            "content": content,
        }))
    }

    #[tool(
        description = "Restore a workspace file to a local-history revision. The current state is recorded first, so the restore can be undone. dry_run defaults to true and returns the content that would be written (null = the file would be deleted)."
    )]
    async fn restore_local_revision(
        &self,
        Parameters(args): Parameters<LocalHistoryArgs>,
    ) -> Result<CallToolResult, McpError> {
        let path = self.history_path(&args.path)?;
        let revision = args
            .revision
            .ok_or_else(|| McpError::invalid_params("revision is required", None))?;
        let content = self.with_history(|history| {
            history
                .content(&path, revision)
                .map_err(|e| McpError::invalid_params(e.to_string(), None))
        })?;
        let restored = !args.dry_run.unwrap_or(true);
        if restored {
            self.require(idecraft_core::Grant::Write).await?;
            // An open file takes the revision in its editor, as one undo step (SPEC-0220 v2
            // behaviour 7); the window's save records it in the local history.
            let file = self.workspace.root().join(&path);
            let text = content
                .as_ref()
                .and_then(|b| String::from_utf8(b.clone()).ok());
            match (self.documents.get(&file), text) {
                (Some(doc), Some(text)) => {
                    self.write_document(&file, &doc.text.to_string(), &text)
                        .await?;
                }
                _ => {
                    self.refuse_unsaved([file.as_path()])?;
                    self.with_history(|history| {
                        history
                            .restore(&path, revision)
                            .map_err(|e| McpError::internal_error(e.to_string(), None))
                    })?;
                }
            }
        }
        json_result(serde_json::json!({
            "path": path,
            "restored": restored,
            "content": content.map(|b| String::from_utf8_lossy(&b).into_owned()),
        }))
    }

    #[tool(
        description = "Read a test report (JUnit XML, TAP, `cargo test` output, Jest/Vitest JSON or `go test -json` output; detected unless given) into a result tree: suites, tests with status (passed, failed, error, skipped), duration, message, details, output, and totals."
    )]
    async fn parse_test_report(
        &self,
        Parameters(args): Parameters<ParseTestReportArgs>,
    ) -> Result<CallToolResult, McpError> {
        let format = match args.format.as_deref() {
            Some(name) => Some(idecraft_core::ReportFormat::from_name(name).ok_or_else(|| {
                McpError::invalid_params(
                    format!("unknown format `{name}` (junit, tap, libtest, jest, gotest)"),
                    None,
                )
            })?),
            None => None,
        };
        let report = idecraft_core::parse_report(&args.text, format)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(report)
    }

    #[tool(
        description = "Requests of a `.http` request file (`###` separators, `@var = value`, `{{var}}`): name, line, method, URL, headers and body with variables resolved from the file, the named environment of `http-client.env.json`/`http-client.private.env.json` and the given variables, plus unresolved names, the request's `settings` (`# @no-redirect`, `# @timeout N`), the files its body takes content from (`body_files`, `< path` lines, not read here) and `notes` on parts that are never sent or run (response handlers, response targets). `{{$uuid}}`, `{{$timestamp}}`, `{{$isoTimestamp}}`, `{{$randomInt}}`, `{{$random.uuid}}`, `{{$random.email}}` (at example.com), `{{$random.integer(from, to)}}` and `{{$random.float(from, to)}}` (`to` not included), `{{$random.alphabetic(n)}}`, `{{$random.alphanumeric(n)}}` and `{{$random.hexadecimal(n)}}` (n 1 to 10000) are generated for each use; any other `$` name, arguments that do not fit and a `{{` without `}}` stay unresolved (SPEC-0046 v6). Without `environment` the only environment of the files is used; with several, a file whose requests use a variable of one is refused with their names (SPEC-0102 v5). Does not send anything."
    )]
    async fn http_requests(
        &self,
        Parameters(args): Parameters<HttpRequestsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let file = self.resolve(&args.path)?;
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let parsed = idecraft_http::parse(&text);
        let env =
            self.http_variables(&file, &parsed, None, args.environment.as_deref(), args.env)?;
        let (requests, masked) = self.readable_requests(&parsed, &env);
        self.log_masked("http_requests", &masked);
        json_result(requests)
    }

    #[tool(
        description = "Project model read from the build files in the workspace (Cargo, npm, Python, Maven, Go; Gradle detected): modules with name, version, folder, toolchain, dependencies with scope, tasks and members; problems per build file; suggested run configurations (Python ones with the workspace's selected interpreter, `${workspace}/…` inside the workspace)."
    )]
    async fn project_model(&self) -> Result<CallToolResult, McpError> {
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let model = idecraft_core::read_project(self.workspace.root(), &files);
        let mut suggested = idecraft_core::suggest_run_configs(&model);
        // Python configurations name the interpreter they run with (SPEC-0050 v2 behaviour 8).
        for c in &mut suggested {
            idecraft_core::show_python(self.workspace.root(), c);
        }
        json_result(serde_json::json!({
            "modules": model.modules,
            "problems": model.problems,
            "suggested_run_configs": suggested,
        }))
    }

    #[tool(
        description = "Run IDECraft's own code inspections over the whole project or one file or folder, as Code | Inspect Code does: Java (unused imports, locals, private fields and methods; == true/false; size()/length() == 0 where the type is known; self-assignment; empty if body; constant and duplicate conditions; printStackTrace(); deprecated boxing constructors; empty finally/synchronized; equals() without hashCode(); empty catch; string ==), Kotlin empty catch, Python bare except, coercing == in JavaScript/TypeScript, unresolved merge conflict markers; .properties duplicate keys and trailing spaces; repeated words, `a`/`an` and (with an English Hunspell word list) typos in comments, Markdown and text files (SPEC-0155). Since SPEC-0125 v2 also redundant casts, fields that may be final, unused parameters of private methods and dereferences of null locals. The project's inspection profile applies (turned-off inspections are skipped, severities replaced; see `inspection_profile`), and findings suppressed with `//noinspection` or `@SuppressWarnings` are left out. A run over the whole project inspects only the project's own sources: virtual environments (`.venv`), installed dependencies (`node_modules`), build output and files ignored by Git are left out, and `not_inspected` says in one line what was; a file or folder named as `path` is inspected whatever it is. Returns `findings`, each with path, 0-based line and column, inspection id and name, level (`error`, `warning` or `weak`), message and the title of its quick fix if it has one (apply it with `fix_inspection`)."
    )]
    async fn inspect_code(
        &self,
        Parameters(args): Parameters<InspectCodeArgs>,
    ) -> Result<CallToolResult, McpError> {
        // The whole project: its own sources. A file or folder named on purpose: whatever it is
        // (SPEC-0098 v8 behaviour 16).
        let path = args.path.as_deref().filter(|p| !p.is_empty());
        if let Some(path) = path {
            self.resolve(path)?;
        }
        let scope = idecraft_languages::inspections::inspection_files(
            self.workspace.root(),
            path.map(Path::new),
        );
        let only =
            match args.id.as_deref() {
                Some(id) => Some(idecraft_languages::inspections::known_id(id).ok_or_else(
                    || McpError::invalid_params(format!("unknown inspection `{id}`"), None),
                )?),
                None => None,
            };
        let findings = idecraft_languages::inspections::inspect_project_only(
            self.workspace.root(),
            &scope.files,
            only,
        );
        let mut out = serde_json::json!({ "findings": findings });
        if let Some(line) = scope.not_inspected {
            out["not_inspected"] = serde_json::json!(format!(
                "{line}. Name a file or folder as `path` to inspect it."
            ));
        }
        json_result(out)
    }

    #[tool(
        description = "The highlighting level of a file (SPEC-0070 v6), as the editor's problem indicator offers it: `none` (no problems shown), `syntax` (errors only), `essential` (errors and warnings) or `all` (default). Without `level` it is only read; with `level` it is set for the file and stored in `.idecraft/highlighting.json`, which the window reads. Returns the path, the level, what it shows and whether the file was written. The analysis itself is not affected: `file_diagnostics` and `inspect_code` still report everything."
    )]
    async fn highlighting_level(
        &self,
        Parameters(args): Parameters<HighlightingLevelArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::highlighting::{HighlightLevel, LEVELS_FILE, level, set_level};
        let file = self.resolve(&args.path)?;
        if !file.is_file() {
            return Err(McpError::invalid_params(
                format!("{} is not a file", args.path),
                None,
            ));
        }
        let root = self.workspace.root().to_path_buf();
        let rel = Path::new(&args.path);
        let written = match args.level.as_deref() {
            Some(name) => {
                let new = HighlightLevel::parse(name).ok_or_else(|| {
                    McpError::invalid_params(
                        format!("unknown level `{name}`: use none, syntax, essential or all"),
                        None,
                    )
                })?;
                self.require(idecraft_core::Grant::Write).await?;
                set_level(&root, rel, new)
                    .map_err(|e| McpError::internal_error(e.to_string(), None))?;
                true
            }
            None => false,
        };
        let now = level(&root, rel);
        json_result(serde_json::json!({
            "path": args.path,
            "level": now.as_str(),
            "shows": now.shows(),
            "file": LEVELS_FILE,
            "written": written,
        }))
    }

    #[tool(
        description = "The editor preview of a problem as the Problems tool window shows it (SPEC-0092 v4): the lines around a 0-based line of a workspace file (`radius` lines above and below, default 5), read as the window shows an open file. Returns the first line's 0-based number, the problem's line and column, and each line with its 0-based number and text."
    )]
    async fn problem_preview(
        &self,
        Parameters(args): Parameters<ProblemPreviewArgs>,
    ) -> Result<CallToolResult, McpError> {
        let path = self.resolve(&args.path)?;
        let text = match self.documents.get(&path) {
            Some(doc) => doc.text.to_string(),
            None => std::fs::read_to_string(&path)
                .map_err(|e| McpError::invalid_params(format!("{}: {e}", args.path), None))?,
        };
        let line_count = text.split('\n').count();
        if args.line >= line_count {
            return Err(McpError::invalid_params(
                format!(
                    "{} has {line_count} lines; line {} is past its end",
                    args.path, args.line
                ),
                None,
            ));
        }
        let radius = args.radius.unwrap_or(5).min(50);
        let (first, lines) =
            idecraft_languages::inspections::preview_lines(&text, args.line, radius);
        let lines: Vec<serde_json::Value> = lines
            .into_iter()
            .enumerate()
            .map(|(i, l)| serde_json::json!({"line": first + i, "text": l}))
            .collect();
        json_result(serde_json::json!({
            "path": args.path,
            "first_line": first,
            "problem_line": args.line,
            "column": args.column.unwrap_or(0),
            "lines": lines,
        }))
    }

    #[tool(
        description = "The project-wide reference index (SPEC-0316): declarations of Java types, methods and fields and of Kotlin classes, objects, functions and properties (v4), and the uses of every name in Java and Kotlin files (counted across the two languages both ways, a Kotlin property also through its Java getter and setter names) and in text files that can name classes (Kotlin scripts, Groovy, Gradle, XML, properties, YAML, HOCON, META-INF/services). It is refreshed incrementally (only new and changed files are read) and cached across calls. Always returns the statistics (`files`, `java_files`, `kotlin_files`, `read`, `removed`, `cached`). With `name`: the declarations of that simple name (path, 0-based line and column, kind, enclosing type) and the files that use it with counts, which explains why a declaration counts as used. With `unused=true`: the unused declarations (global inspections `java.unused-declaration` and `kotlin.unused-declaration`; entry points, annotated members, overrides, operators and possible overrides of library methods excluded; suppressions and the profile apply), optionally limited to a file or folder with `path`, placed as `inspect_code` places findings."
    )]
    async fn reference_index(
        &self,
        Parameters(args): Parameters<ReferenceIndexArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root().to_path_buf();
        // The own sources and merely ignored files (SPEC-0316 v2 behaviour 7).
        let all = idecraft_languages::reference_index::project_files(&root);
        let mut out =
            idecraft_languages::reference_index::with_project_index(&root, &all, |index, stats| {
                let mut out = serde_json::json!({ "stats": stats });
                if let Some(name) = args.name.as_deref() {
                    let declarations: Vec<serde_json::Value> = index
                        .declarations_of(name)
                        .into_iter()
                        .map(|(p, d)| {
                            serde_json::json!({
                                "path": p,
                                "line": d.line,
                                "column": d.column,
                                "kind": d.kind,
                                "container": d.container,
                            })
                        })
                        .collect();
                    let uses: Vec<serde_json::Value> = index
                        .uses_of(name)
                        .into_iter()
                        .map(|(p, n)| serde_json::json!({"path": p, "count": n}))
                        .collect();
                    out["name"] = serde_json::json!({
                        "name": name,
                        "declarations": declarations,
                        "uses": uses,
                    });
                }
                out
            });
        if args.unused {
            // Unused declarations are listed for the project's own files, or for a place named
            // on purpose, as `inspect_code` chooses them (SPEC-0098 v8 behaviour 16).
            let path = args.path.as_deref().filter(|p| !p.is_empty());
            if let Some(path) = path {
                self.resolve(path)?;
            }
            let scope =
                idecraft_languages::inspections::inspection_files(&root, path.map(Path::new)).files;
            // Java's and Kotlin's (SPEC-0316 v4 behaviour 9), each file with its language's id.
            let mut unused = Vec::new();
            for (ext, id) in [
                (
                    "java",
                    idecraft_languages::reference_index::UNUSED_DECLARATION,
                ),
                (
                    "kt",
                    idecraft_languages::reference_index::KOTLIN_UNUSED_DECLARATION,
                ),
            ] {
                unused.extend(idecraft_languages::inspections::inspect_project_only(
                    &root,
                    &scope
                        .iter()
                        .filter(|f| f.extension().is_some_and(|e| e == ext))
                        .cloned()
                        .collect::<Vec<_>>(),
                    Some(id),
                ));
            }
            out["unused"] = serde_json::to_value(unused)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        }
        json_result(out)
    }

    #[tool(
        description = "Apply the quick fix of one finding of IDECraft's own inspections (see `inspect_code`, which names the fix), identified by file, 0-based line and column and inspection id; with all=true (no line and column needed) the fixes of every finding of that inspection in the file, overlapping ones skipped (SPEC-0125 v2). A place with several fixes (Python: `Remove assignment target` and `Remove statement`, `Remove unused import` and `Optimize imports`; at a name that is not defined `Import 'name' from 'module'` for each module of the project or of the standard library that defines it, `Import 'module'` for a standard library module, then `Create parameter 'name'` — SPEC-0098 v14) takes `title`, else the first applies; `Optimize imports` runs `optimize_imports`. A repeated word or wrong article (`grazie.repeated-word`, `grazie.article`) also takes the titles `Ignore '<text>'`, which keeps the text in the project's `.idecraft/grammar-ignore.toml` so `inspect_code` and `check_grammar` no longer report it, and `Disable rule '<name>'`, which turns the rule off in the inspection profile (SPEC-0155 v3); these answer with `kept` and `file` instead of edits. A duplicate property key has no `all` (SPEC-0155 v2). dry_run defaults to true and returns the fix title, the number of fixes, the edits and the new text; dry_run=false writes the file, refusing if it changed meanwhile."
    )]
    async fn fix_inspection(
        &self,
        Parameters(args): Parameters<FixInspectionArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let (title, edits, count) = if args.all {
            // A duplicate property key is removed place by place (SPEC-0155 v2 behaviour 6).
            if !idecraft_languages::inspections::fix_all_applies(&args.id) {
                return Err(McpError::invalid_params(
                    format!(
                        "`{}` has no fix for the whole file: remove one place at a time, the one \
                         to keep is your choice",
                        args.id
                    ),
                    None,
                ));
            }
            // SPEC-0125 v2 behaviour 8: every fix of the inspection in the file.
            let edits = idecraft_languages::inspections::fix_all(&file, &text, &args.id);
            if edits.is_empty() {
                return Err(McpError::invalid_params(
                    format!("no `{}` finding with a quick fix in {}", args.id, args.path),
                    None,
                ));
            }
            let name = match idecraft_languages::inspections::known_id(&args.id) {
                Some(id) => idecraft_languages::inspections::name_of(id),
                None => args.id.as_str(),
            };
            let title = format!("Fix all '{name}' problems in file");
            let count = edits.len();
            (title, edits, count)
        } else {
            let (Some(line), Some(column)) = (args.line, args.column) else {
                return Err(McpError::invalid_params(
                    "line and column are needed unless all=true",
                    None,
                ));
            };
            let fix = fix_at(
                &file,
                &args.path,
                &text,
                line,
                column,
                &args.id,
                args.title.as_deref(),
            )?;
            // A fix that keeps something in the project (SPEC-0155 v3 behaviour 10).
            if let Some(keep) = fix.keep.clone() {
                return self
                    .keep_finding(&file, &fix.title, keep, args.dry_run)
                    .await;
            }
            // A fix that runs an action (SPEC-0098 v9 behaviour 17): Optimize Imports.
            if fix.action == Some("OptimizeImports") {
                return self
                    .optimize_imports(Parameters(JvmFileArgs {
                        path: args.path.clone(),
                        dry_run: args.dry_run,
                    }))
                    .await;
            }
            (fix.title, fix.edits, 1)
        };
        let new_text = idecraft_languages::jvm::apply(&text, &edits);
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({
            "applied": applied,
            "fix": title,
            "fixes": count,
            "edits": edits,
            "text": new_text,
        }))
    }

    #[tool(
        description = "Suppress one finding of IDECraft's Java or Kotlin inspections (SPEC-0125 v2, SPEC-0098 v13 behaviour 28), identified by file, 0-based line and column and inspection id as `inspect_code` returns them. Java: scope `statement` (default) puts `//noinspection <short name>` above the statement or member, `method` and `class` add the short name to the enclosing method's or class's `@SuppressWarnings` or insert one (the id is used where the inspection has no short name). Kotlin: `declaration` (default; `statement` too) adds `@Suppress(\"<short name>\")` to the declaration around the finding, `class` to the class or object around it, `file` writes `@file:Suppress`. dry_run defaults to true and returns the edits and the new text; dry_run=false writes the file, refusing if it changed meanwhile."
    )]
    async fn suppress_inspection(
        &self,
        Parameters(args): Parameters<SuppressInspectionArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::inspections::SuppressScope;
        let (_, file) = self.source(&args.path)?;
        // Java, and Kotlin since SPEC-0098 v13 behaviour 28.
        let kotlin = file.extension().is_some_and(|e| e == "kt");
        if file.extension().is_none_or(|e| e != "java") && !kotlin {
            return Err(McpError::invalid_params(
                "suppression is available for Java and Kotlin files only",
                None,
            ));
        }
        if kotlin != args.id.starts_with("kotlin.") {
            return Err(McpError::invalid_params(
                format!("`{}` is not an inspection of this file's language", args.id),
                None,
            ));
        }
        let scope_name = args.scope.as_deref().unwrap_or("statement");
        // `all`: every inspection for the class (SPEC-0125 v3 behaviour 8).
        let all = scope_name.eq_ignore_ascii_case("all");
        // `file` and `declaration` are Kotlin's; Java has `statement`, `method`, `class`, `all`.
        let parsed = SuppressScope::parse(scope_name).filter(|s| {
            kotlin || (*s != SuppressScope::File && !scope_name.eq_ignore_ascii_case("declaration"))
        });
        let scope = match parsed {
            Some(s) => s,
            None if all && !kotlin => SuppressScope::Class,
            None => {
                let choices = if kotlin {
                    "declaration, class or file"
                } else {
                    "statement, method, class or all"
                };
                return Err(McpError::invalid_params(
                    format!("unknown scope `{scope_name}`: use {choices}"),
                    None,
                ));
            }
        };
        let text = self.read_document(&file)?;
        // The global unused declarations are no findings of the file alone (SPEC-0316): they are
        // placed by line and column.
        let global = [
            idecraft_languages::reference_index::UNUSED_DECLARATION,
            idecraft_languages::reference_index::KOTLIN_UNUSED_DECLARATION,
        ]
        .contains(&args.id.as_str());
        let start = match finding_at(&file, &args.path, &text, args.line, args.column, &args.id) {
            Ok(f) => f.start,
            Err(_) if global => byte_at(&text, args.line, args.column).ok_or_else(|| {
                McpError::invalid_params(
                    format!("no place {}:{} in {}", args.line, args.column, args.path),
                    None,
                )
            })?,
            Err(e) => return Err(e),
        };
        let suppressed = if all { "ALL" } else { args.id.as_str() };
        let edits = idecraft_languages::inspections::suppress(&text, start, suppressed, scope)
            .ok_or_else(|| {
                McpError::invalid_params(
                    format!(
                        "`{}` cannot be suppressed for the {scope_name} here",
                        args.id
                    ),
                    None,
                )
            })?;
        let new_text = idecraft_languages::jvm::apply(&text, &edits);
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({
            "applied": applied,
            "scope": scope_name,
            "edits": edits,
            "text": new_text,
        }))
    }

    #[tool(
        description = "The project's inspection profile (SPEC-0315), stored as the reference stores it in `.idea/inspectionProfiles/Project_Default.xml`: lists every IDECraft inspection with id, short name, name, language, default level, whether it is enabled, its current level, whether it differs from the default, and its description. With `id` only that inspection; with `id` and `enabled` and/or `severity` (`error`, `warning`, `weak`) it changes the profile and writes the file; `reset=true` with `id` returns the inspection to its default. Changes apply to `inspect_code`, `fix_inspection` and the editor."
    )]
    async fn inspection_profile(
        &self,
        Parameters(args): Parameters<InspectionProfileArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::inspection_profile as profile;
        use idecraft_languages::inspections::{Level, catalogue, description};
        let root = self.workspace.root().to_path_buf();
        let mut current = profile::load(&root).map_err(|e| {
            McpError::invalid_params(format!("{}: {e}", profile::PROFILE_FILE), None)
        })?;
        let all = catalogue();
        let info = match args.id.as_deref() {
            Some(id) => Some(all.iter().find(|i| i.id == id).ok_or_else(|| {
                McpError::invalid_params(format!("unknown inspection `{id}`"), None)
            })?),
            None => None,
        };
        let severity = match args.severity.as_deref() {
            Some(s) => Some(Level::parse(s).ok_or_else(|| {
                McpError::invalid_params(
                    format!("unknown severity `{s}`: use error, warning, weak or info"),
                    None,
                )
            })?),
            None => None,
        };
        let change = args.reset || args.enabled.is_some() || severity.is_some();
        if change {
            let Some(info) = info else {
                return Err(McpError::invalid_params(
                    "changing the profile needs an `id`",
                    None,
                ));
            };
            self.require(idecraft_core::Grant::Write).await?;
            if args.reset {
                current.reset(info.id);
            }
            if args.enabled.is_some() || severity.is_some() {
                current.set(info.id, args.enabled, severity);
            }
            profile::save(&root, &current)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        }
        let entry = |i: &idecraft_languages::inspections::InspectionInfo| {
            let (enabled, level) = current.state(i.id);
            serde_json::json!({
                "id": i.id,
                "short_name": i.short_name,
                "name": i.name,
                "language": i.language,
                "default_level": i.level,
                "enabled": enabled,
                "level": level,
                "changed": current.is_changed(i.id),
                "description": description(i.id),
            })
        };
        let inspections: Vec<serde_json::Value> = match info {
            Some(i) => vec![entry(i)],
            None => all.iter().map(entry).collect(),
        };
        json_result(serde_json::json!({
            "profile": profile::PROFILE_NAME,
            "file": profile::PROFILE_FILE,
            "exists": root.join(profile::PROFILE_FILE).exists(),
            "written": change,
            "inspections": inspections,
        }))
    }

    #[tool(
        description = "Write or update the copyright notice at the top of a workspace file (SPEC-0155): the project's profile comes from `.idecraft/copyright.txt` (template; optional first line `keyword: …`) or the reference's `.idea/copyright/` profiles; `$today.year`, `$file.fileName`, `$project.name`, `$username` are replaced; the notice is written as the language's comment after a shebang, XML declaration or encoding line, or replaces a leading comment holding the keyword. Returns `changed`, the notice and the new text; dry_run defaults to true, dry_run=false writes the file (refused if it changed meanwhile)."
    )]
    async fn update_copyright(
        &self,
        Parameters(args): Parameters<UpdateCopyrightArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::copyright;
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let root = self.workspace.root().to_path_buf();
        let profile = copyright::load_profile(&root).ok_or_else(|| {
            McpError::invalid_params(
                "no copyright profile: add .idecraft/copyright.txt or .idea/copyright/",
                None,
            )
        })?;
        let values = copyright::Values {
            year: args.year.unwrap_or_else(copyright::current_year),
            file_name: file
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default(),
            project: root
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default(),
            user: std::env::var("USER").unwrap_or_default(),
        };
        let new_text = copyright::update(&file, &text, &profile, &values);
        let applied = !args.dry_run.unwrap_or(true) && new_text.is_some();
        if let (true, Some(new)) = (applied, &new_text) {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, new).await?;
        }
        json_result(serde_json::json!({
            "changed": new_text.is_some(),
            "applied": applied,
            "notice": profile.render(&values),
            "text": new_text.unwrap_or(text),
        }))
    }

    #[tool(
        description = "Replace text in a workspace text file as the window shows it, saved or not (SPEC-0006 v56 behaviour 8). `old_text` must occur exactly once unless `replace_all` is true; none or several occurrences are an error naming the count and the 1-based lines, and nothing changes. `case_sensitive` defaults to true. Returns `replacements`, the 1-based `lines` of the replaced places and `applied`. dry_run defaults to true; dry_run=false needs the user-granted `write` right and writes through the open editor as one undo step (SPEC-0220), or to the disk when the file is not open."
    )]
    async fn replace_text_in_file(
        &self,
        Parameters(args): Parameters<ReplaceTextArgs>,
    ) -> Result<CallToolResult, McpError> {
        if args.old_text.is_empty() {
            return Err(McpError::invalid_params(
                "old_text is empty; name the text to replace",
                None,
            ));
        }
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let found = occurrences(&text, &args.old_text, args.case_sensitive.unwrap_or(true));
        let line_of = |byte: usize| text[..byte].matches('\n').count() + 1;
        let lines: Vec<usize> = found.iter().map(|r| line_of(r.start)).collect();
        let replace_all = args.replace_all.unwrap_or(false);
        if found.is_empty() {
            return Err(McpError::invalid_params(
                format!("{}: the text does not occur; nothing changed", args.path),
                None,
            ));
        }
        if found.len() > 1 && !replace_all {
            return Err(McpError::invalid_params(
                format!(
                    "{}: the text occurs {} times (lines {}); give more context so it occurs once, or set replace_all; nothing changed",
                    args.path,
                    found.len(),
                    lines
                        .iter()
                        .map(usize::to_string)
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                None,
            ));
        }
        let mut new_text = String::with_capacity(text.len());
        let mut at = 0;
        for r in &found {
            new_text.push_str(&text[at..r.start]);
            new_text.push_str(&args.new_text);
            at = r.end;
        }
        new_text.push_str(&text[at..]);
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({
            "path": args.path,
            "replacements": found.len(),
            "lines": lines,
            "applied": applied,
        }))
    }

    #[tool(
        description = "Read a .properties file as java.util.Properties does (SPEC-0155): every property with its key and value (escapes resolved, continuation lines joined) and 0-based line, and the problems with the title of their fix: every place of a duplicate key (naming the other lines; fix `Remove property`, which `fix_inspection` with `properties.duplicate-key` applies to one place, SPEC-0155 v2) and trailing spaces in values."
    )]
    async fn properties_file(
        &self,
        Parameters(args): Parameters<PropertiesFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (_, file) = self.source(&args.path)?;
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let properties: Vec<serde_json::Value> = idecraft_languages::properties::parse(&text)
            .into_iter()
            .map(|p| serde_json::json!({"key": p.key, "value": p.value, "line": p.line}))
            .collect();
        let line_of = |byte: usize| text[..byte].matches('\n').count();
        let problems: Vec<serde_json::Value> = idecraft_languages::properties::check(&text)
            .into_iter()
            .map(|i| {
                serde_json::json!({
                    "id": i.id, "line": line_of(i.range.start), "message": i.message,
                    "fix": i.fix.map(|(title, _, _)| title),
                })
            })
            .collect();
        json_result(serde_json::json!({ "properties": properties, "problems": problems }))
    }

    #[tool(
        description = "The resource bundle of a .properties file (SPEC-0163): the files of the bundle in its folder with their locale (from the name, as Java reads `Messages_de_AT.properties`; empty for the base file), every key with the locales that have it, the keys missing per locale, and each key's values per locale (`default` for the base file). `set` (key, locale, value) and `remove` (key) edit the bundle as its editor does (SPEC-0212): only the property's own lines change and non-ASCII text is escaped only in ASCII files; `dry_run` defaults to true and returns the bundle as it would be and the files that would change."
    )]
    async fn resource_bundle(
        &self,
        Parameters(args): Parameters<ResourceBundleArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::properties::{Bundle, remove_property, set_property};
        let (root, file) = self.source(&args.path)?;
        // The bundle's files as the window shows them, saved or not (SPEC-0220 v5 behaviour 17).
        let read = |p: &Path| self.read_document(p).ok();
        let Some(bundle) = Bundle::read(&file, read) else {
            return Err(McpError::invalid_params(
                format!("{} is not a .properties file", args.path),
                None,
            ));
        };
        // Edits of the bundle editor (SPEC-0212 behaviour 6): new texts per file.
        let shown: Vec<(PathBuf, String)> = bundle
            .files
            .iter()
            .map(|p| (p.clone(), read(p).unwrap_or_default()))
            .collect();
        let mut texts = shown.clone();
        if let Some(set) = &args.set {
            let at = bundle.locale_index(&set.locale).ok_or_else(|| {
                McpError::invalid_params(format!("no locale `{}` in the bundle", set.locale), None)
            })?;
            texts[at].1 = set_property(&texts[at].1, &set.key, &set.value);
        }
        if let Some(key) = &args.remove {
            for (_, text) in &mut texts {
                *text = remove_property(text, key);
            }
        }
        let changed: Vec<String> = texts
            .iter()
            .zip(&shown)
            .filter(|((_, t), (_, before))| t != before)
            .map(|((p, _), _)| p.strip_prefix(&root).unwrap_or(p).display().to_string())
            .collect();
        let dry_run = args.dry_run.unwrap_or(true);
        if !dry_run && !changed.is_empty() {
            self.require(idecraft_core::Grant::Write).await?;
        }
        if !dry_run {
            // Open files in their editors, all or nothing (SPEC-0220 v5 behaviour 17).
            let writes: Vec<(PathBuf, String, String)> = texts
                .iter()
                .zip(&shown)
                .map(|((p, t), (_, before))| (p.clone(), before.clone(), t.clone()))
                .collect();
            self.write_shown("Edit Resource Bundle", &writes, false)
                .await?;
        }
        let after = Bundle::read(&file, |p| {
            texts
                .iter()
                .find(|(f, _)| f == p)
                .map(|(_, t)| t.clone())
                .or_else(|| read(p))
        })
        .unwrap_or(bundle);
        let locale = |l: &str| {
            if l.is_empty() {
                "default".to_owned()
            } else {
                l.to_owned()
            }
        };
        let files_json: Vec<serde_json::Value> = after
            .files
            .iter()
            .enumerate()
            .map(|(n, p)| {
                let missing: Vec<&String> = after
                    .keys
                    .iter()
                    .filter(|k| k.values[n].is_none())
                    .map(|k| &k.key)
                    .collect();
                serde_json::json!({
                    "locale": after.locales[n],
                    "path": p.strip_prefix(&root).unwrap_or(p).display().to_string(),
                    "keys": after.keys.len() - missing.len(),
                    "missing": missing,
                })
            })
            .collect();
        let keys: std::collections::BTreeMap<&String, Vec<&String>> = after
            .keys
            .iter()
            .map(|k| {
                let locales = (0..after.locales.len())
                    .filter(|&n| k.values[n].is_some())
                    .map(|n| &after.locales[n])
                    .collect();
                (&k.key, locales)
            })
            .collect();
        let values: Vec<serde_json::Value> = after
            .keys
            .iter()
            .map(|k| {
                let by_locale: serde_json::Map<String, serde_json::Value> = after
                    .locales
                    .iter()
                    .zip(&k.values)
                    .map(|(l, v)| (locale(l), serde_json::json!(v)))
                    .collect();
                serde_json::json!({"key": k.key, "values": by_locale})
            })
            .collect();
        json_result(serde_json::json!({
            "files": files_json, "keys": keys, "values": values,
            "changed": changed, "dry_run": dry_run,
        }))
    }

    #[tool(
        description = "The project dictionary of the typo check (SPEC-0163): its words, kept in `.idea/dictionaries/project.xml` of the project as the reference keeps them; `add` saves words (dry_run defaults to true and only shows the result)."
    )]
    async fn project_dictionary(
        &self,
        Parameters(args): Parameters<ProjectDictionaryArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::project_dictionary as pd;
        let root = self
            .workspace
            .root()
            .canonicalize()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let file = root.join(".idea/dictionaries/project.xml");
        let mut words: std::collections::BTreeSet<String> = std::fs::read_to_string(&file)
            .map(|t| pd::parse(&t))
            .unwrap_or_default();
        let added: Vec<String> = args
            .add
            .iter()
            .map(|w| w.trim().to_lowercase())
            .filter(|w| !w.is_empty() && !words.contains(w))
            .collect();
        let applied = !args.dry_run.unwrap_or(true) && !added.is_empty();
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            for w in &added {
                pd::learn_at(&file, w).map_err(|e| McpError::internal_error(e, None))?;
            }
        }
        words.extend(added.iter().cloned());
        json_result(serde_json::json!({
            "file": ".idea/dictionaries/project.xml",
            "words": words,
            "added": added,
            "applied": applied,
        }))
    }

    #[tool(
        description = "Dictionaries of the typo check (SPEC-0159 v2): the English Hunspell dictionaries the user can download in Settings › Editor › Natural Languages (code, name, licence, size, download URL at a fixed LibreOffice commit, SHA-256, `built_in` for English (United States), which IDECraft carries checked against that SHA-256), which are downloaded and which one is `used`, and the word list in effect: the downloaded file in `word_list`, or `built_in` true (then `word_list` is null) when nothing is chosen or downloaded. Read only: downloading is left to the user."
    )]
    async fn spelling_dictionaries(&self) -> Result<CallToolResult, McpError> {
        use idecraft_languages::dictionaries as d;
        let chosen = self
            .ide_settings_file
            .as_deref()
            .map(idecraft_core::load_ide_settings)
            .unwrap_or_default()
            .editor
            .spelling_dictionary;
        let dir = d::dictionaries_dir();
        let active = d::active(dir.as_deref(), &chosen);
        let list: Vec<serde_json::Value> = d::CATALOG
            .iter()
            .map(|e| {
                serde_json::json!({
                    "code": e.code, "name": e.name, "license": e.license,
                    "size": e.dic.0 + e.aff.0, "url": d::url(e.code, "dic"), "sha256": e.dic.1,
                    "downloaded": dir.as_deref().is_some_and(|dir| d::is_installed(dir, e.code)),
                    "built_in": d::is_built_in(e.code),
                })
            })
            .collect();
        // SPEC-0159 v2 behaviour 5: the file in effect, or the built-in word list.
        let in_effect = d::word_list(dir.as_deref(), &chosen);
        json_result(serde_json::json!({
            "dictionaries": list,
            "folder": dir.map(|p| p.display().to_string()),
            "used": active,
            "word_list": match &in_effect {
                d::WordList::File(p) => Some(p.display().to_string()),
                d::WordList::BuiltIn => None,
            },
            "built_in": in_effect == d::WordList::BuiltIn,
        }))
    }

    #[tool(
        description = "Check English prose such as a commit message or a Markdown text (SPEC-0155): repeated words, `a`/`an` before a word, and typos with a suggestion, with the built-in en_US word list or the dictionary chosen or downloaded in Settings (SPEC-0159 v2; `typos_checked` says whether typos were looked for). Texts the project ignores (`.idecraft/grammar-ignore.toml`, SPEC-0155 v3) are left out. Returns each problem with rule, 0-based byte start and end, the text, message and replacement."
    )]
    async fn check_grammar(
        &self,
        Parameters(args): Parameters<CheckGrammarArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::grazie;
        let text = &args.text;
        let prose = if args.markdown.unwrap_or(false) {
            grazie::markdown_prose(text)
        } else {
            std::iter::once(0..text.len()).collect()
        };
        let known = grazie::code_words(text, &prose);
        let dictionary = grazie::Dictionary::current();
        // The workspace's ignored grammar texts (SPEC-0155 v3 behaviour 10).
        let ignored = idecraft_languages::grammar_ignore::file_of(self.workspace.root())
            .map(|f| idecraft_languages::grammar_ignore::load(&f))
            .unwrap_or_default();
        let problems: Vec<serde_json::Value> = grazie::check(
            text,
            &prose,
            dictionary.as_deref(),
            &known,
        )
        .into_iter()
        .filter(|i| {
            !idecraft_languages::grammar_ignore::is_ignored(&ignored, text, i.rule, i.range.clone())
        })
        .map(|i| {
            serde_json::json!({
                "rule": i.rule, "start": i.range.start, "end": i.range.end,
                "text": &text[i.range.clone()], "message": i.message, "replacement": i.replacement,
            })
        })
        .collect();
        json_result(
            serde_json::json!({ "problems": problems, "typos_checked": dictionary.is_some() }),
        )
    }

    #[tool(
        description = "Installed plugins (sandboxed WebAssembly modules in the user's IDECraft plugins folder): name, version, description, file, actions with id, title and kind (replace the selection, show a message, `edit` with the editor's context, SPEC-0156; the extension points `inspect`, `complete`, `status` and `panel`, SPEC-0210), `extensions` (what it contributes, e.g. `completion`, `status bar`, `tool window`, `file types: Conf (.conf)`) and `file_types` as declared, the permissions it asks for and those the user granted, and files that failed to load; `disabled` lists plugins switched off in Settings › Plugins. `file_refusals` holds the last 200 file requests refused to plugins (time, plugin, function `read_file` or `open`, path, reason; SPEC-0156 v3): a plugin with `project-read` gets only the project's own sources and no file whose name commonly holds secrets. Installing, enabling, removing and granting are left to the user (SPEC-0126)."
    )]
    async fn plugins(&self) -> Result<CallToolResult, McpError> {
        let (plugins, problems) = self.installed_plugins();
        let list: Vec<serde_json::Value> = plugins
            .iter()
            .map(|p| {
                let actions: Vec<serde_json::Value> = p
                    .manifest
                    .actions
                    .iter()
                    .map(|a| {
                        serde_json::json!({
                            "id": idecraft_plugins::action_id(p, &a.id),
                            "title": a.title, "kind": a.kind,
                        })
                    })
                    .collect();
                let granted: Vec<&str> = p
                    .manifest
                    .permissions
                    .iter()
                    .filter(|perm| {
                        self.plugins_dir
                            .as_deref()
                            .is_some_and(|d| idecraft_plugins::granted(d, &p.file(), **perm))
                    })
                    .map(|perm| perm.name())
                    .collect();
                serde_json::json!({
                    "name": p.manifest.name, "version": p.manifest.version,
                    "description": p.manifest.description,
                    "file": p.path.display().to_string(), "actions": actions,
                    "permissions": p.manifest.permissions, "granted": granted,
                    "extensions": idecraft_plugins::contributions(&p.manifest),
                    "file_types": p.manifest.file_types,
                })
            })
            .collect();
        let disabled: Vec<serde_json::Value> = self
            .plugins_dir
            .as_deref()
            .map(idecraft_plugins::installed)
            .unwrap_or_default()
            .into_iter()
            .filter(|p| !p.enabled)
            .map(|p| {
                serde_json::json!({
                    "file": p.file,
                    "name": p.manifest.map(|m| m.name),
                    "problem": p.problem,
                })
            })
            .collect();
        let file_refusals = self
            .plugins_dir
            .as_deref()
            .map(|d| idecraft_plugins::file_refusals(d, None, 200))
            .unwrap_or_default();
        json_result(serde_json::json!({
            "folder": self.plugins_dir.as_ref().map(|d| d.display().to_string()),
            "plugins": list, "problems": problems, "disabled": disabled,
            "file_refusals": file_refusals,
        }))
    }

    #[tool(
        description = "The plugin file type of a workspace file (SPEC-0210): the plugin and file type that highlight it (none when IDECraft has a language of its own for the file), its line comment, and the highlighted runs with 0-based line, column, character range and kind (comment, string, number, keyword)."
    )]
    async fn plugin_file_type(
        &self,
        Parameters(args): Parameters<PluginPathArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (_, file) = self.source(&args.path)?;
        let (plugins, _) = self.installed_plugins();
        let builtin = idecraft_languages::LanguageId::detect(&file);
        let Some((plugin, file_type)) =
            idecraft_plugins::file_type_for(&plugins, &file, builtin.is_some())
        else {
            return json_result(serde_json::json!({
                "file_type": null,
                "builtin": builtin.map(|l| l.lsp_id()),
            }));
        };
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let chars: Vec<char> = text.chars().collect();
        let spans: Vec<serde_json::Value> = idecraft_plugins::highlight(file_type, &text)
            .into_iter()
            .map(|(r, kind)| {
                let before = &chars[..r.start];
                let line = before.iter().filter(|c| **c == '\n').count();
                let column = before.iter().rev().take_while(|c| **c != '\n').count();
                serde_json::json!({
                    "line": line, "column": column, "start": r.start, "end": r.end,
                    "kind": kind, "text": chars[r.clone()].iter().collect::<String>(),
                })
            })
            .collect();
        json_result(serde_json::json!({
            "plugin": plugin.manifest.name, "file_type": file_type.name,
            "line_comment": file_type.line_comment, "spans": spans,
        }))
    }

    #[tool(
        description = "Inspect a plugin module (`.wasm`) of the workspace without installing it (SPEC-0211): its manifest, what it contributes, the permissions it asks for and whether they are granted, and what installing it would do against the installed plugins (`install`, `update`, `reinstall` or `downgrade` with the installed version, or `replace` with `from_name` and `from` when a different plugin — another manifest name — is installed under the same file name; grants carry over only to the same plugin, so `granted` is false for `install` and `replace`). A file that is no valid plugin returns the reason. Installing stays with the user."
    )]
    async fn inspect_plugin_file(
        &self,
        Parameters(args): Parameters<PluginPathArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (_, file) = self.source(&args.path)?;
        let dir = self
            .plugins_dir
            .clone()
            .unwrap_or_else(|| std::env::temp_dir().join("idecraft-no-plugins"));
        match idecraft_plugins::review(&dir, &file) {
            Ok(review) => json_result(serde_json::json!({
                "headline": review.headline(), "review": review,
            })),
            Err(e) => json_result(serde_json::json!({ "problem": e.to_string() })),
        }
    }

    #[tool(
        description = "Dependency tree and tasks of one module, as the build tools window shows them: transitive dependencies from Cargo.lock or package-lock.json (each package expanded once, later occurrences marked repeated); for Maven and Gradle (SPEC-0149) from the build tool's resolution (Gradle per classpath configuration, `a → b` where Gradle chose another version), kept until the build file changes, made now with resolve=true (needs the `run` right) — `resolved` says whether the tree is current; direct dependencies with locked versions otherwise; tasks with their commands."
    )]
    async fn dependency_tree(
        &self,
        Parameters(args): Parameters<DependencyTreeArgs>,
    ) -> Result<CallToolResult, McpError> {
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let root = self.workspace.root();
        let model = idecraft_core::read_project(root, &files);
        let module = match args.module.as_deref() {
            Some(dir) => model.modules.iter().find(|m| m.dir == dir),
            None => model.modules.first(),
        }
        .ok_or_else(|| McpError::invalid_params("no such module (see project_model)", None))?;
        let resolvable = idecraft_core::jvmdeps::cache_file(root, module).is_some();
        if args.resolve.unwrap_or(false) && resolvable {
            self.require(idecraft_core::Grant::Run).await?;
            self.require_trusted()?;
            self.log(
                root,
                serde_json::json!({
                    "time": unix_time(), "tool": "dependency_tree", "resolve": module.dir,
                }),
            )?;
            let (r, m) = (root.to_path_buf(), module.clone());
            tokio::task::spawn_blocking(move || idecraft_core::jvmdeps::resolve(&r, &m))
                .await
                .map_err(|e| McpError::internal_error(e.to_string(), None))?
                .map_err(|e| McpError::invalid_params(e, None))?;
        }
        let resolved = resolvable.then(|| idecraft_core::jvmdeps::is_resolved(root, module));
        let mut tree = idecraft_core::dependency_tree(root, module);
        if let Ok(t) = &mut tree {
            idecraft_core::buildtools::unmark_modules(&model, t);
        }
        let tasks: Vec<serde_json::Value> = idecraft_core::module_tasks(module)
            .into_iter()
            .map(|(name, command)| serde_json::json!({ "name": name, "command": command }))
            .collect();
        // The window's groups (Maven lifecycle and plugins, Gradle task groups run from the
        // build's root) and the artifacts the build tool could not find (SPEC-0100 v2).
        let groups = idecraft_core::buildtools::task_groups(root, module);
        let missing = tree
            .as_ref()
            .map(|t| idecraft_core::buildtools::missing_artifacts(t))
            .unwrap_or_default();
        json_result(serde_json::json!({
            "module": module.name, "dir": module.dir, "kind": module.kind,
            "dependencies": tree.as_ref().ok(), "problem": tree.as_ref().err(),
            "resolved": resolved, "tasks": tasks, "task_groups": groups, "missing": missing,
        }))
    }

    #[tool(
        description = "Options of the build tools window (SPEC-0100 v2) that every Maven and Gradle run from it and every dependency resolution gets: offline (Maven -o, Gradle --offline), skip_tests (Maven -DskipTests) and the Maven profiles of the project with their default and current state (-P a,!b). Without arguments it only reads them; setting needs the `write` right and is kept in .idecraft/build-tools.toml."
    )]
    async fn build_tool_options(
        &self,
        Parameters(args): Parameters<BuildToolOptionsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root();
        let mut options = idecraft_core::buildtools::BuildOptions::load(root);
        let change = args.offline.is_some() || args.skip_tests.is_some() || args.profiles.is_some();
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let profiles =
            idecraft_core::buildtools::project_profiles(&idecraft_core::read_project(root, &files));
        if change {
            self.require(idecraft_core::Grant::Write).await?;
            if let Some(v) = args.offline {
                options.offline = v;
            }
            if let Some(v) = args.skip_tests {
                options.skip_tests = v;
            }
            for (id, value) in args.profiles.unwrap_or_default() {
                if !profiles.iter().any(|(p, _)| *p == id) {
                    return Err(McpError::invalid_params(
                        format!("no profile '{id}' in the project's POMs"),
                        None,
                    ));
                }
                match value {
                    Some(on) => options.profiles.insert(id, on),
                    None => options.profiles.remove(&id),
                };
            }
            options
                .save(root)
                .map_err(|e| McpError::internal_error(e, None))?;
        }
        let listed: Vec<serde_json::Value> = profiles
            .iter()
            .map(|(id, default)| {
                serde_json::json!({
                    "id": id, "default": default, "active": options.profile_active(id, *default),
                })
            })
            .collect();
        json_result(serde_json::json!({
            "offline": options.offline, "skip_tests": options.skip_tests, "profiles": listed,
            "example": options.apply(&["mvn".to_owned(), "package".to_owned()], &profiles),
        }))
    }

    /// The project model of the workspace.
    fn build_model(&self) -> Result<idecraft_core::ProjectModel, McpError> {
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        Ok(idecraft_core::read_project(self.workspace.root(), &files))
    }

    #[tool(
        description = "Suggestions of the build tools window's Execute field (SPEC-0100 v3): for the word at the end of `line` the Maven phases and plugin goals or the Gradle tasks of the module, the build tool's options when the word starts with `-` (with their meaning), the project's Maven profiles after `-P`; words already on the line are left out, prefix matches first, at most ten. Each has `text`, `kind` (phase, goal, task, option, profile) and `detail`; `completed` is the line with the first suggestion taken."
    )]
    async fn build_command_suggestions(
        &self,
        Parameters(args): Parameters<BuildCommandSuggestionsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let model = self.build_model()?;
        let module = match args.module.as_deref() {
            Some(dir) => model.modules.iter().find(|m| m.dir == dir),
            None => model.modules.first(),
        }
        .ok_or_else(|| McpError::invalid_params("no such module (see project_model)", None))?;
        let profiles = idecraft_core::buildtools::project_profiles(&model);
        let list = idecraft_core::buildtasks::command_suggestions(
            self.workspace.root(),
            module,
            &profiles,
            &args.line,
        );
        let completed = list
            .first()
            .map(|s| idecraft_core::buildtasks::complete_line(&args.line, &s.text));
        json_result(serde_json::json!({
            "module": module.dir, "suggestions": list, "completed": completed,
        }))
    }

    #[tool(
        description = "Dependency analyzer of the build tools window (SPEC-0100 v3, IMP-0341): for a Maven or Gradle module's resolved tree the artifacts reached in more than one version (`conflict`), the version on the classpath (`chosen`), and every place each is reached with the version asked for there, its status (`used`, `replaced by …`, `omitted for conflict with …`, `omitted for duplicate`), its path from the module and the direct dependency it starts with. `all` adds the artifacts without conflict, `artifact` narrows to one, `diagram` adds the tree as Mermaid text (IMP-0339). `resolve: true` lets the build tool resolve first (`run` right); without a resolution the answer says so."
    )]
    async fn dependency_analysis(
        &self,
        Parameters(args): Parameters<DependencyAnalysisArgs>,
    ) -> Result<CallToolResult, McpError> {
        let model = self.build_model()?;
        let root = self.workspace.root();
        let jvm = |m: &&idecraft_core::Module| {
            matches!(
                m.kind,
                idecraft_core::ModuleKind::Maven | idecraft_core::ModuleKind::Gradle
            )
        };
        let module = match args.module.as_deref() {
            Some(dir) => model.modules.iter().filter(jvm).find(|m| m.dir == dir),
            None => model.modules.iter().find(jvm),
        }
        .ok_or_else(|| McpError::invalid_params("no such Maven or Gradle module", None))?;
        if args.resolve.unwrap_or(false) {
            self.require(idecraft_core::Grant::Run).await?;
            self.require_trusted()?;
            self.log(
                root,
                serde_json::json!({
                    "time": unix_time(), "tool": "dependency_analysis", "resolve": module.dir,
                }),
            )?;
            let (r, m) = (root.to_path_buf(), module.clone());
            tokio::task::spawn_blocking(move || idecraft_core::jvmdeps::resolve(&r, &m))
                .await
                .map_err(|e| McpError::internal_error(e.to_string(), None))?
                .map_err(|e| McpError::invalid_params(e, None))?;
        }
        let Some(mut tree) = idecraft_core::jvmdeps::resolved_tree(root, module) else {
            return json_result(serde_json::json!({
                "module": module.dir, "resolved": false,
                "problem": "not resolved yet: call with resolve=true or reload the build tools window",
            }));
        };
        idecraft_core::buildtools::unmark_modules(&model, &mut tree);
        let label = module.short_name().to_owned();
        let artifacts: Vec<idecraft_core::depanalysis::Artifact> =
            idecraft_core::depanalysis::analyze(&label, &tree)
                .into_iter()
                .filter(|a| args.all.unwrap_or(false) || a.conflict)
                .filter(|a| args.artifact.as_deref().is_none_or(|n| a.name == n))
                .collect();
        let diagram = args
            .diagram
            .unwrap_or(false)
            .then(|| idecraft_core::depanalysis::mermaid(&label, &tree));
        json_result(serde_json::json!({
            "module": module.dir, "resolved": true,
            "conflicts": artifacts.iter().filter(|a| a.conflict).count(),
            "artifacts": artifacts, "diagram": diagram,
        }))
    }

    #[tool(
        description = "Sources and documentation of the Maven and Gradle libraries (SPEC-0149 v3): per resolved library whether its `-sources.jar` and `-javadoc.jar` are in the local caches (Maven repository, Gradle cache) with their paths, and a `summary`. `download: true` first runs the build tools with the build tools window's options (Maven `dependency:sources` and `dependency:resolve -Dclassifier=javadoc` per module, a Gradle init script task per build; `run` right, logged); `dry_run` only lists those commands."
    )]
    async fn library_sources(
        &self,
        Parameters(args): Parameters<LibrarySourcesArgs>,
    ) -> Result<CallToolResult, McpError> {
        let model = self.build_model()?;
        let root = self.workspace.root().to_path_buf();
        let mut failures: Vec<String> = Vec::new();
        if args.dry_run.unwrap_or(false) {
            let options = idecraft_core::buildtools::BuildOptions::load(&root);
            let commands = idecraft_core::jvmsources::download_commands(&root, &model, &options)
                .map_err(|e| McpError::internal_error(e, None))?;
            return json_result(serde_json::json!({ "commands": commands }));
        }
        if args.download.unwrap_or(false) {
            self.require(idecraft_core::Grant::Run).await?;
            self.require_trusted()?;
            self.log(
                &root,
                serde_json::json!({
                    "time": unix_time(), "tool": "library_sources", "download": true,
                }),
            )?;
            let (r, m) = (root.clone(), model.clone());
            failures =
                tokio::task::spawn_blocking(move || idecraft_core::jvmsources::download(&r, &m))
                    .await
                    .map_err(|e| McpError::internal_error(e.to_string(), None))?
                    .map_err(|e| McpError::invalid_params(e, None))?;
        }
        let states = idecraft_core::jvmsources::library_states(&root, &model);
        json_result(serde_json::json!({
            "summary": idecraft_core::jvmsources::summary(&states),
            "libraries": states, "failures": failures,
        }))
    }

    #[tool(
        description = "Build files linked and module folders unlinked by hand in the build tools window (SPEC-0048 v4, SPEC-0100 v3): `link` reads a build file even in an ignored or excluded folder and undoes an unlink of its folder; `unlink` leaves a module folder and the modules inside it out of the project model. Both need the `write` right and are kept in .idecraft/build-tools.toml. Returns the lists and the modules now in the model."
    )]
    async fn build_tool_links(
        &self,
        Parameters(args): Parameters<BuildToolLinksArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root();
        let mut options = idecraft_core::buildtools::BuildOptions::load(root);
        if args.link.is_some() || args.unlink.is_some() {
            self.require(idecraft_core::Grant::Write).await?;
            if let Some(file) = &args.link {
                options
                    .link(root, file)
                    .map_err(|e| McpError::invalid_params(e, None))?;
            }
            if let Some(dir) = &args.unlink {
                options.unlink(dir.trim_end_matches('/'));
            }
            options
                .save(root)
                .map_err(|e| McpError::internal_error(e, None))?;
        }
        let model = self.build_model()?;
        let modules: Vec<serde_json::Value> = model
            .modules
            .iter()
            .map(|m| serde_json::json!({ "dir": m.dir, "name": m.name, "kind": m.kind }))
            .collect();
        json_result(serde_json::json!({
            "linked": options.linked, "unlinked": options.unlinked, "modules": modules,
        }))
    }

    #[tool(
        description = "A task of the build tools window (SPEC-0100 v3): its run configuration (name, command with the window's options, folder), its debug variant (Maven test runs pass a JDWP agent to Surefire, other goals to the Maven JVM via MAVEN_OPTS, Gradle runs get an init script for Test and JavaExec tasks; attach with `debug_attach` once the run prints that the agent listens), its triggers and the keymap action id for `set_shortcut`. `before_sync`, `after_sync` (v4), `before_build`, `after_build` and `before_run` switch its triggers (`write` right). Without `task` it returns the triggers and the Build Project chain (`CompileDirty`). With `file` (SPEC-0100 v5) it returns `recompile`: the step Recompile (`Compile`) runs for that file — the build of the innermost Maven, Gradle, Cargo or Go module that holds it (name, command, folder), null for a file in none — without running it."
    )]
    async fn build_task(
        &self,
        Parameters(args): Parameters<BuildTaskArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_core::buildtasks::{self, When};
        let model = self.build_model()?;
        let root = self.workspace.root();
        let mut options = idecraft_core::buildtools::BuildOptions::load(root);
        // SPEC-0100 v5 behaviour 22: the step of Recompile, read only.
        if let Some(file) = args.file.as_deref() {
            let path = self.resolve(file)?;
            let step = buildtasks::recompile_step(root, &model, &options, &path);
            return json_result(serde_json::json!({ "recompile": step }));
        }
        let Some(label) = args.task.as_deref() else {
            let chain = buildtasks::build_project_chain(root, &model, &options);
            return json_result(serde_json::json!({
                "triggers": options.triggers, "build_project": chain,
            }));
        };
        let module = match args.module.as_deref() {
            Some(dir) => model.modules.iter().find(|m| m.dir == dir),
            None => model.modules.first(),
        }
        .ok_or_else(|| McpError::invalid_params("no such module (see project_model)", None))?;
        let task = buildtasks::find_task(root, module, label).ok_or_else(|| {
            McpError::invalid_params(
                format!(
                    "no task '{label}' in {} (see dependency_tree task_groups)",
                    module.dir
                ),
                None,
            )
        })?;
        let changes = [
            (When::BeforeSync, args.before_sync),
            (When::AfterSync, args.after_sync),
            (When::BeforeBuild, args.before_build),
            (When::AfterBuild, args.after_build),
            (When::BeforeRun, args.before_run),
        ];
        if changes.iter().any(|(_, v)| v.is_some()) {
            self.require(idecraft_core::Grant::Write).await?;
            for (when, value) in changes {
                if let Some(on) = value {
                    options.set_trigger(when, &module.dir, label, on);
                }
            }
            options
                .save(root)
                .map_err(|e| McpError::internal_error(e, None))?;
        }
        let profiles = idecraft_core::buildtools::project_profiles(&model);
        let config = buildtasks::task_config(&module.dir, &task, &options, &profiles);
        let port = args.debug_port.unwrap_or(5005);
        let debug = buildtasks::debug_config(root, &config, port).ok();
        json_result(serde_json::json!({
            "module": module.dir, "task": label, "run": config,
            "debug": debug.map(|d| serde_json::json!({
                "run": d, "port": port,
                "attach": {"runtime": "java", "address": format!("localhost:{port}")},
            })),
            "triggers": options.trigger_labels(&module.dir, label),
            "action": buildtasks::task_action_id(&module.dir, label),
        }))
    }

    #[tool(
        description = "Run the inspections installed plugins offer for a workspace file (SPEC-0166): each plugin `inspect` action whose `files` match, in the plugin's sandbox with the inspection budget; findings with action, 0-based line and column, character range, message, level and quick fix (edits in characters), and the errors of plugins that failed. A file a plugin may not read — a name that commonly holds secrets (`.env`, `*.pem`, `credentials.json`) or a file that is not one of the project's own sources — is refused unless `allow_secret_file` is true, which is noted in `file-audit.jsonl` (SPEC-0156 v4). Nothing is written."
    )]
    async fn plugin_inspections(
        &self,
        Parameters(args): Parameters<PluginInspectionsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (root, file) = self.source(&args.path)?;
        let (plugins, _) = self.installed_plugins();
        // A file a plugin may not read goes to the plugins only on purpose (SPEC-0156 v4
        // behaviour 13).
        let inspecting: Vec<String> = plugins
            .iter()
            .filter(|p| p.manifest.actions.iter().any(|a| a.inspects(&file)))
            .map(idecraft_plugins::Plugin::file)
            .collect();
        self.plugin_file_guard(
            "plugin_inspections",
            &inspecting,
            &args.path,
            &file,
            args.allow_secret_file.unwrap_or(false),
        )?;
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let context = idecraft_plugins::InspectContext {
            path: args.path.clone(),
            language: idecraft_languages::LanguageId::detect(&file).map(|l| l.lsp_id().to_owned()),
            text: text.clone(),
        };
        let mut findings = Vec::new();
        let mut errors = Vec::new();
        let line_col = |chars: usize| {
            let before: String = text.chars().take(chars).collect();
            let line = before.matches('\n').count();
            let column = before.rsplit('\n').next().map_or(0, |l| l.chars().count());
            (line, column)
        };
        for plugin in &plugins {
            for action in plugin.manifest.actions.iter().filter(|a| a.inspects(&file)) {
                let project_read = plugin
                    .manifest
                    .permissions
                    .contains(&idecraft_plugins::Permission::ProjectRead)
                    && self.plugins_dir.as_deref().is_some_and(|d| {
                        idecraft_plugins::granted(
                            d,
                            &plugin.file(),
                            idecraft_plugins::Permission::ProjectRead,
                        )
                    });
                let access = idecraft_plugins::Access {
                    root: Some(root.clone()),
                    project_read,
                    network: None,
                    log: self.plugin_file_log(),
                };
                match plugin.run_inspect(&action.id, &context, access) {
                    Ok(found) => findings.extend(found.into_iter().map(|f| {
                        let (line, column) = line_col(f.start);
                        serde_json::json!({
                            "action": idecraft_plugins::action_id(plugin, &action.id),
                            "line": line, "column": column,
                            "start": f.start, "end": f.end,
                            "message": f.message, "level": f.level, "fix": f.fix,
                        })
                    })),
                    Err(e) => errors.push(e.to_string()),
                }
            }
        }
        json_result(serde_json::json!({ "findings": findings, "errors": errors }))
    }

    #[tool(
        description = "Run a plugin action in the plugin's sandbox (no network or clock; limited instructions and memory) and return its output: the replacement text or the message for `input`; for an `edit` action (SPEC-0156) on the workspace file `path` with a selection, its answer (edits, selection, message, file to open) and the edited text — the plugin reads the project's files only if the user granted it `project-read` in Settings › Plugins. Extension points (SPEC-0210): a `complete` action on `path` at the character `offset` (default: the end) returns its items; a `status` action on `path` with a selection its status bar text; a `panel` action its tool window rows (`path` is passed as the active file). A `path` a plugin may not read — a name that commonly holds secrets (`.env`, `*.pem`, `credentials.json`) or a file that is not one of the project's own sources — is refused unless `allow_secret_file` is true, which is noted in `file-audit.jsonl` (SPEC-0156 v4). Nothing is written."
    )]
    async fn run_plugin_action(
        &self,
        Parameters(args): Parameters<RunPluginActionArgs>,
    ) -> Result<CallToolResult, McpError> {
        let (plugins, _) = self.installed_plugins();
        let found = idecraft_plugins::find_action(&plugins, &args.action)
            .map(|(p, a)| (p.clone(), a.clone()));
        let Some((plugin, action)) = found else {
            return Err(McpError::invalid_params(
                format!("no plugin action `{}` (see plugins)", args.action),
                None,
            ));
        };
        let id = action.id.clone();
        let access = self.plugin_access(&plugin);
        use idecraft_plugins::ActionKind;
        if action.kind == ActionKind::Connector {
            // Network only through a connection and its grants (SPEC-0314).
            return Err(McpError::invalid_params(
                "a database connector: save a connection of its system and use test_connection",
                None,
            ));
        }
        if action.kind == ActionKind::RunConfig {
            // Suggestions only with the user's grant (SPEC-0276 behaviour 2).
            return Err(McpError::invalid_params(
                "a run configuration type: use plugin_run_configurations",
                None,
            ));
        }
        // The file named for the action goes to the plugin only when a plugin may read it, or on
        // purpose (SPEC-0156 v4 behaviour 13).
        if let Some(rel) = args.path.as_deref().filter(|_| {
            matches!(
                action.kind,
                ActionKind::Complete | ActionKind::Panel | ActionKind::Edit | ActionKind::Status
            )
        }) {
            let (_, file) = self.source(rel)?;
            self.plugin_file_guard(
                "run_plugin_action",
                &[plugin.file()],
                rel,
                &file,
                args.allow_secret_file.unwrap_or(false),
            )?;
        }
        if matches!(action.kind, ActionKind::Complete | ActionKind::Panel) {
            // Extension points (SPEC-0210 behaviours 1, 5): completion at an offset of a workspace
            // file, a tool window section for the project.
            let kind = action.kind;
            let context = match (&args.path, kind) {
                (Some(rel), ActionKind::Complete) => {
                    let (_, file) = self.source(rel)?;
                    let text = std::fs::read_to_string(&file)
                        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
                    let chars: Vec<char> = text.chars().collect();
                    let offset = args.offset.unwrap_or(chars.len()).min(chars.len());
                    let start = chars[..offset]
                        .iter()
                        .rposition(|c| !(c.is_alphanumeric() || *c == '_'))
                        .map_or(0, |i| i + 1);
                    Ok(idecraft_plugins::CompleteContext {
                        path: rel.clone(),
                        language: idecraft_languages::LanguageId::detect(&file)
                            .map(|l| l.lsp_id().to_owned()),
                        prefix: chars[start..offset].iter().collect(),
                        text,
                        offset,
                    })
                }
                (None, ActionKind::Complete) => Err(McpError::invalid_params(
                    "a complete action needs `path`",
                    None,
                )),
                _ => Ok(idecraft_plugins::CompleteContext {
                    path: args.path.clone().unwrap_or_default(),
                    language: None,
                    text: String::new(),
                    offset: 0,
                    prefix: String::new(),
                }),
            }?;
            let panel = idecraft_plugins::PanelContext {
                project: self
                    .workspace
                    .root()
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default(),
                active: args.path.clone(),
            };
            let result = tokio::task::spawn_blocking(move || {
                if kind == ActionKind::Complete {
                    plugin
                        .run_complete(&id, &context, access)
                        .map(|items| serde_json::json!({"items": items}))
                } else {
                    plugin
                        .run_panel(&id, &panel, access)
                        .map(|rows| serde_json::json!({"rows": rows}))
                }
            })
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
            return json_result(serde_json::json!({ "kind": kind, "result": result }));
        }
        if matches!(action.kind, ActionKind::Edit | ActionKind::Status) {
            // The editor context of a workspace file; project access only as the user granted it.
            let rel = args.path.ok_or_else(|| {
                McpError::invalid_params("an edit or status action needs `path`", None)
            })?;
            let (_, file) = self.source(&rel)?;
            let text = std::fs::read_to_string(&file)
                .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
            let len = text.chars().count();
            let start = args.selection_start.unwrap_or(0).min(len);
            let end = args.selection_end.unwrap_or(start).clamp(start, len);
            let before: String = text.chars().take(start).collect();
            let line = before.matches('\n').count();
            let column = before.rsplit('\n').next().map_or(0, |l| l.chars().count());
            let context = idecraft_plugins::EditorContext {
                path: rel.clone(),
                language: idecraft_languages::LanguageId::detect(&file)
                    .map(|l| l.lsp_id().to_owned()),
                text: text.clone(),
                selection_start: start,
                selection_end: end,
                line,
                column,
            };
            if action.kind == ActionKind::Status {
                let status =
                    tokio::task::spawn_blocking(move || plugin.run_status(&id, &context, access))
                        .await
                        .map_err(|e| McpError::internal_error(e.to_string(), None))?
                        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
                return json_result(serde_json::json!({ "kind": action.kind, "result": status }));
            }
            let result =
                tokio::task::spawn_blocking(move || plugin.run_edit(&id, &context, access))
                    .await
                    .map_err(|e| McpError::internal_error(e.to_string(), None))?
                    .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
            let mut chars: Vec<char> = text.chars().collect();
            for e in result.edits.iter().rev() {
                chars.splice(e.start..e.end, e.text.chars());
            }
            let new_text: String = chars.into_iter().collect();
            return json_result(serde_json::json!({
                "kind": action.kind, "result": result, "text": new_text,
            }));
        }
        let input = args.input;
        let output = tokio::task::spawn_blocking(move || plugin.run(&id, &input))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "kind": action.kind, "output": output }))
    }

    #[tool(
        description = "HTTP endpoints declared in the project's code, as the Endpoints tool window lists them: Spring MVC, JAX-RS (Jakarta EE, Quarkus), Micronaut and NestJS annotations, FastAPI and Flask decorators, Express routes. Only the project's own sources are scanned: virtual environments (`.venv`), installed dependencies (`node_modules`), build output, files ignored by Git and test sources under `src/test/` are left out. One entry per row of the window: a mapping with several paths gives one for each path, a class with several paths lists its endpoints under each, and a mapping with several HTTP methods is one entry that names them all. Each with framework, `kind` (`server` for a route the application serves, `client` for a method of a REST client interface: `@RegisterRestClient`, Micronaut `@Client`, `@FeignClient`), `methods` (the list in the mapping's order; empty when the mapping names no method and so takes every method), `method` (the same as one text: `GET`, `POST|PUT`, `ANY` for the empty list), path (class or router prefix included; a served JAX-RS path starts with the project's one `@ApplicationPath`; a slash at the end of the handler's path is kept for Spring, FastAPI and Flask), handler, file and 0-based line of the mapping annotation, plus `request`: a ready `.http` request on the framework's port with the first method (GET without one), null for a client row. `query` searches the entries as the Endpoints tab of Search Everywhere does and returns the matching ones, best first: the text is matched without regard to case against the path and the handler, every fragment at the start of a path segment or word (`ord` finds `/api/orders/{id}`, `api/ord` too, `*rders` matches inside a word); several words must each match the path or the handler; a leading HTTP method and a space (`GET users`, `post `) keeps the entries of that method and those without a method; entries whose path matches come before those found by their handler. Without `query` every entry is returned, sorted by path and methods."
    )]
    async fn endpoints(
        &self,
        Parameters(args): Parameters<EndpointsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root();
        // Only the project's own sources (SPEC-0103 v2 behaviour 5).
        let all = idecraft_languages::endpoints::project_endpoints(root);
        // The search of the Endpoints tab (SPEC-0067 v9 behaviour 20, SPEC-0103 v5 behaviour 8).
        let rows: Vec<idecraft_languages::endpoints::Endpoint> = match args.query.as_deref() {
            Some(query) if !query.trim().is_empty() => {
                idecraft_languages::endpoints::search_endpoints(&all, query, usize::MAX)
                    .into_iter()
                    .map(|hit| hit.endpoint)
                    .collect()
            }
            _ => all,
        };
        let list: Vec<serde_json::Value> = rows
            .into_iter()
            .map(|e| {
                let request = idecraft_languages::endpoints::request(root, &e)
                    .map(|(method, url)| format!("{method} {url}"));
                let mut v = serde_json::json!(e);
                // The methods as one text; `ANY` says in words what the empty list means
                // (SPEC-0103 v4 behaviour 7).
                v["method"] = serde_json::json!(if e.methods.is_empty() {
                    "ANY".to_owned()
                } else {
                    e.method_label()
                });
                v["request"] = serde_json::json!(request);
                v
            })
            .collect();
        json_result(list)
    }

    #[tool(
        description = "The project's beans as IDECraft reads them from the Java sources, for Spring, Jakarta EE/CDI, Quarkus and Micronaut: beans (stereotype and scope annotations such as @Service, @ApplicationScoped, @Stateless, @Singleton, composed annotations that carry a stereotype, @Bean/@Produces/factory methods and producer fields, and interfaces the framework implements such as Spring Data repositories, @ConfigMapping and REST clients, with name, type, kind, file, 0-based line, @Primary or @Alternative @Priority, and where they apply `aliases`, `qualifiers` (qualifier annotations of the project), `conditional` (a profile or condition) and `fallback`), injection points (constructor and producer parameters, @Autowired/@Inject fields and setters, @Qualifier/@Named) with the beans that can be injected, configuration keys from application*.properties/yml (the keys that carry a value, list items as `key[0]`), @Value/@ConfigProperty/@Property keys, the frameworks imported (`frameworks`, most specific first; `framework` labels the problems), and problems (no bean or several beans of a project type, keys defined nowhere without default, each with `severity` `warning`; and with `severity` `weak` a field annotated `@Autowired` in a Spring project or `@Inject` in a Micronaut project outside the test sources, where the framework's documentation recommends constructor injection). Since SPEC-0115 v5: a bean of the test sources (`src/test/`) carries `test: true`, and `main_beans` and `test_beans` count the two groups (the Spring tool window lists the main ones by default); an injection point names its class (`owner`) and, for a producer method's parameter, the bean made (`producer`); a property carries `column`, the byte range of its key and its `profile` (of the file, the YAML document or a `%profile.` key), never its value; a key in the code carries `prefix: true` when it is the prefix of @ConfigurationProperties or @ConfigMapping. With `path`: `marks`, the gutter marks of that file (0-based `line`, `kind` bean or injection, `tip`, `targets` with name, file and line: a bean leads to the places it is injected, an injection point to the beans that fit), and `values`, the resolved values the editor shows in place of the file's `${…}` placeholders (masked as `•••` for keys that look like secrets). With `bean`: `dependencies` and `dependents` of that bean. For one configuration key use `config_key`."
    )]
    async fn spring_beans(
        &self,
        Parameters(args): Parameters<SpringBeansArgs>,
    ) -> Result<CallToolResult, McpError> {
        // Only the project's own sources (SPEC-0115 v2 behaviour 8).
        let model = idecraft_languages::spring::project_model(self.workspace.root());
        let problems = model.problems();
        let tests = model.beans.iter().filter(|b| b.test).count();
        let mut out = serde_json::json!({
            "framework": model.label(),
            "model": model,
            "problems": problems,
            "main_beans": model.beans.len() - tests,
            "test_beans": tests,
        });
        if let Some(path) = &args.path {
            self.resolve(path)?;
            let rel = Path::new(path);
            out["marks"] = serde_json::json!(model.gutter_marks(rel));
            out["values"] = serde_json::json!(model.value_folds(rel));
        }
        if let Some(name) = &args.bean {
            let index = model
                .beans
                .iter()
                .position(|b| b.name == *name || b.aliases.contains(name))
                .ok_or_else(|| McpError::invalid_params(format!("no bean named {name}"), None))?;
            out["dependencies"] = serde_json::json!(model.dependencies(index));
            out["dependents"] = serde_json::json!(model.dependents(index));
        }
        json_result(out)
    }

    #[tool(
        description = "One configuration key of the project (SPEC-0115 v5, SPEC-0134 v5), from the bean model IDECraft reads from the project's own sources: `definitions`, the lines of application*.properties/.yml/.yaml that define it (file, 0-based line and column, `profile` for a profile's file, a profile's YAML document or a `%profile.` key, and the value as written), `usages`, the places in the Java sources that read it (@Value placeholders, @ConfigProperty, @Property, and with `prefix: true` the prefixes of @ConfigurationProperties and @ConfigMapping it lies below), `value`, what the application gets — the value of a profile the configuration itself switches on (spring.profiles.active, quarkus.profile, micronaut.environments), else of the default profile — with `value_profile`, and `secret`. Relaxed binding as for @Value: `shop.max-items` finds `shop.maxItems`. Security: for a key whose name contains password, passwd, secret, token, key or credential every value is returned as `•••`, never as written. Ask with `key`, or with `path`, `line` and `column` of a place inside a key in a Java file or a configuration file (from a configuration file, `usages` are the places that read that line's key). Read-only."
    )]
    async fn config_key(
        &self,
        Parameters(args): Parameters<ConfigKeyArgs>,
    ) -> Result<CallToolResult, McpError> {
        let model = idecraft_languages::spring::project_model(self.workspace.root());
        if let Some(key) = args.key.as_deref().filter(|k| !k.trim().is_empty()) {
            return json_result(model.key_info(key.trim()));
        }
        let (Some(path), Some(line), Some(column)) = (&args.path, args.line, args.column) else {
            return Err(McpError::invalid_params(
                "give `key`, or `path` with `line` and `column`",
                None,
            ));
        };
        let file = self.resolve(path)?;
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(format!("{path}: {e}"), None))?;
        let start: usize = text
            .split_inclusive('\n')
            .take(line as usize)
            .map(str::len)
            .sum();
        let byte = text[start.min(text.len())..]
            .char_indices()
            .nth(column as usize)
            .map_or(text.len(), |(b, _)| start + b);
        match model.key_info_at(Path::new(path), byte) {
            Some(info) => json_result(info),
            None => Err(McpError::invalid_params(
                format!("no configuration key at {path}:{line}:{column}"),
                None,
            )),
        }
    }

    #[tool(
        description = "Project files of the reference IDE in the workspace's `.idea` folder, read only: project name, SDK, language level, compiler output, modules from `modules.xml` with content roots, source/test/resource folders, excluded folders, module SDK and dependencies (modules, project/global libraries, module libraries), project libraries, version control mappings and problems (malformed files, missing module files, unknown modules or libraries), and `folders`: each existing folder below the project the modules give a role in the Project tree (`dir` project-relative, `role` module, sources, tests, resources, test_resources or excluded, `module_name` when it differs from the folder's name; SPEC-0049 v2). A folder without `.idea` but with a `<name>.ipr` is read from that file (`ipr` names it; SPEC-0049 v3). `run_configurations`: the reference's run configurations from `.idea/runConfigurations`, the `.ipr` and the `RunManager` part of `workspace.xml` or the `.iws` (nothing else of that personal state is used), each with `name`, `type`, `source`, `folder` and either the IDECraft translation (`kind`, `command`, `cwd`, `env` with variable names only, never values) or `reason` why it was not translated; translated ones appear in the run list after `.idecraft/run.toml` and start only in a trusted project. Each module lists `facets` (`type`, `name`) as hints of its frameworks. Database tool files are never opened. Returns null when there is neither `.idea` nor an `.ipr`."
    )]
    async fn idea_project(&self) -> Result<CallToolResult, McpError> {
        json_result(idecraft_core::read_idea_project(self.workspace.root()))
    }

    #[tool(
        description = "Project folders this user opened recently in IDECraft, most recent first, as listed in the window's project popup (folders that no longer exist are left out). They lie outside this workspace, so the tool needs the user-granted `recent-projects` right (SPEC-0094 v9); without it the call is refused with \"not granted\" and the right's name. Every read is written to the local agent log, with the number of folders, never their paths."
    )]
    async fn recent_projects(&self) -> Result<CallToolResult, McpError> {
        // The folders of other projects lie outside the workspace (SPEC-0094 v9 behaviour 23).
        self.require(idecraft_core::Grant::RecentProjects).await?;
        let projects = self
            .recent_projects_file
            .as_deref()
            .map(idecraft_core::load_recent_projects)
            .unwrap_or_default();
        self.log(
            self.workspace.root(),
            serde_json::json!({
                "time": unix_time(), "tool": "recent_projects", "count": projects.len(),
                "right": idecraft_core::Grant::RecentProjects.name(),
            }),
        )?;
        json_result(projects)
    }

    #[tool(
        description = "Change the user's keymap as Settings › Keymap does (needs the `settings` right: the keymap holds for every project): give an action exactly the given shortcuts (keymap notation; an empty list removes them) or restore its bundled shortcuts with `reset`. Saved as the TOML user keymap `keymaps/IDECraft.toml` (SPEC-0303; an older `IDECraft.xml` is read until then and kept as `.bak`) over this platform's bundled keymap; windows use it when changed there or at their next start. Returns the action's shortcuts and other actions that share the first keystroke."
    )]
    async fn set_shortcut(
        &self,
        Parameters(args): Parameters<SetShortcutArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_ui::keymap::{KeymapFile, Shortcut};
        let invalid = |m: String| McpError::invalid_params(m, None);
        let change = match (args.reset.unwrap_or(false), args.shortcuts) {
            (true, None) => None,
            (false, Some(list)) => Some(
                list.iter()
                    .map(|t| Shortcut::parse_keyboard(t))
                    .collect::<Result<Vec<_>, _>>()
                    .map_err(|e| invalid(e.to_string()))?,
            ),
            _ => return Err(invalid("give either `shortcuts` or `reset: true`".into())),
        };
        let file = self.keymap_file.as_ref().ok_or_else(|| {
            McpError::internal_error("no settings folder (HOME is not set)", None)
        })?;
        // The keymap is the user's and holds for every project (SPEC-0053 v8 behaviour 12).
        self.require(idecraft_core::Grant::Settings).await?;
        let mut user = KeymapFile::read_user(Some(file));
        user.set_action(&args.action, change);
        user.write(file)
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let map = self.user_keymap();
        let shortcuts = map.shortcuts(&args.action);
        let mut conflicts: Vec<String> = Vec::new();
        for s in shortcuts {
            if let Shortcut::Keyboard { first, .. } = s {
                for id in map.actions_for(first, None) {
                    if id != args.action && !conflicts.iter().any(|c| c == id) {
                        conflicts.push(id.to_owned());
                    }
                }
            }
        }
        let shown: Vec<serde_json::Value> = shortcuts
            .iter()
            .map(|s| serde_json::json!({"shortcut": s, "display": s.display(map.macos)}))
            .collect();
        json_result(serde_json::json!({
            "action": args.action, "shortcuts": shown, "conflicts": conflicts,
        }))
    }

    /// Where an import writes and an export reads: this workspace and the server's user files.
    fn format_targets(&self) -> idecraft_formats::Targets {
        idecraft_formats::Targets {
            root: self.workspace.root().to_path_buf(),
            keymap_file: self.keymap_file.clone(),
            settings_file: self.ide_settings_file.clone(),
            legacy_theme_file: self.theme_file.clone(),
        }
    }

    /// A path given to the file-format tools: absolute, or relative to the workspace.
    /// The existing file `path` (workspace-relative, or absolute inside the workspace) as an
    /// absolute path; a path outside the workspace (also through `..` or a link), a folder and a
    /// missing file are refused (`SPEC-0094` v7 behaviour 21).
    fn workspace_file(&self, path: Option<&str>) -> Result<PathBuf, McpError> {
        let Some(path) = path else {
            return Err(McpError::invalid_params(
                "`open` needs the file's `path`",
                None,
            ));
        };
        let p = Path::new(path);
        let relative = if p.is_absolute() {
            p.strip_prefix(self.workspace.root()).map_err(|_| {
                McpError::invalid_params(format!("{path} is not inside the workspace"), None)
            })?
        } else {
            p
        };
        let file = self.resolve(&relative.to_string_lossy())?;
        if !file.is_file() {
            return Err(McpError::invalid_params(
                format!("{path} is not a file"),
                None,
            ));
        }
        Ok(file)
    }

    fn any_path(&self, path: &str) -> PathBuf {
        let p = Path::new(path);
        if p.is_absolute() {
            p.to_path_buf()
        } else {
            self.workspace.root().join(p)
        }
    }

    #[tool(
        description = "Open an IDECraft exchange file (SPEC-0303: `.idcrun` run configuration, `.idckeymap` keymap, `.idctheme` theme, `.idcsources` data sources without passwords, `.idcsettings` settings bundle, or such a file renamed to `.toml`) as the window's import preview does: returns kind, format (and `migrated_from` for older files), the envelope (name, author, licence, homepage), the contents as lines, the changes it would make (target, add/replace/unchanged, old and new value) and every problem with its key path. Files of a newer format, over 64 KiB, with secrets, paths outside the workspace or private settings are refused. dry_run defaults to true; dry_run=false imports (needs the `write` right for files of the project and the `settings` right for the IDE settings, the keymap and the theme; refused when there are problems). show=true asks the running window to show the preview so the user confirms there (MCP over HTTP only; needs the `ui` right)."
    )]
    async fn import_file(
        &self,
        Parameters(args): Parameters<ImportFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        let path = self.any_path(&args.path);
        if args.show.unwrap_or(false) {
            let Some(window) = self.window.clone() else {
                return Err(McpError::invalid_params(
                    "no window to show the preview: this MCP server runs without the IDECraft window (stdio, `idecraft mcp`); use dry_run=false, or `idecraft open <file>`",
                    None,
                ));
            };
            // Opening a preview in the user's window is operating it (SPEC-0053 v8).
            self.require(idecraft_core::Grant::Ui).await?;
            let (reply, answer) = tokio::sync::oneshot::channel();
            window.show_import(path, reply);
            let project = answer
                .await
                .map_err(|_| McpError::internal_error("the window could not show it", None))?
                .map_err(|e| McpError::invalid_params(e, None))?;
            return json_result(serde_json::json!({ "shown": true, "project": project }));
        }
        let targets = self.format_targets();
        let preview = idecraft_formats::preview_file(&path, &targets);
        let mut value = serde_json::to_value(&preview)
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        value["can_import"] = serde_json::json!(preview.can_import());
        if args.dry_run.unwrap_or(true) {
            value["dry_run"] = serde_json::json!(true);
            return json_result(value);
        }
        if !preview.problems.is_empty() {
            return Err(McpError::invalid_params(
                format!(
                    "{} has problems; nothing was imported: {}",
                    preview.file,
                    idecraft_core::format::problems_text(&preview.problems)
                ),
                None,
            ));
        }
        // Files of the project need `write`; the user's IDE settings, keymap and theme need
        // `settings` (SPEC-0053 v8 behaviour 12).
        let in_project = |c: &idecraft_formats::Change| c.target.starts_with('.');
        if preview.changes.is_empty() || preview.changes.iter().any(in_project) {
            self.require(idecraft_core::Grant::Write).await?;
        }
        if preview.changes.iter().any(|c| !in_project(c)) {
            self.require(idecraft_core::Grant::Settings).await?;
        }
        let written = idecraft_formats::apply(&preview, &targets)
            .map_err(|e| McpError::invalid_params(e, None))?;
        value["dry_run"] = serde_json::json!(false);
        value["written"] = serde_json::json!(written);
        json_result(value)
    }

    #[tool(
        description = "Export an IDECraft exchange file (SPEC-0303) in the current format: kind `run` (one configuration of `.idecraft/run.toml`, by `name`), `keymap` (the user keymap), `theme` (chosen theme and compact mode), `sources` (connections, all or `ids`), `settings` (editor, appearance, version control and code style settings plus the user keymap). Passwords, stored-password references, agent rights, environment variables named like secrets, paths outside the workspace and the AI, MCP and terminal settings are left out and listed in `left_out`. Returns `text` and a suggested `file_name`; with `path` (inside the workspace) writes the file (needs the `write` right; an existing file only with overwrite=true). share=true adds `share_url`, a prefilled GitHub issue to open in a browser; IDECraft sends nothing."
    )]
    async fn export_file(
        &self,
        Parameters(args): Parameters<ExportFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        let selection = idecraft_formats::Selection {
            name: args.name.clone(),
            ids: args.ids.clone(),
        };
        let out = idecraft_formats::export(&args.kind, &selection, &self.format_targets())
            .map_err(|e| McpError::invalid_params(e, None))?;
        let mut value = serde_json::to_value(&out)
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        if args.share.unwrap_or(false) {
            let name = args.name.clone().unwrap_or_else(|| {
                out.file_name
                    .rsplit_once('.')
                    .map_or(out.file_name.clone(), |(s, _)| s.to_owned())
            });
            let (url, whole) = idecraft_formats::share_url(&args.kind, &name, &out.text);
            value["share_url"] = serde_json::json!(url);
            value["share_contains_file"] = serde_json::json!(whole);
        }
        if let Some(p) = &args.path {
            // An agent writes files inside the workspace only (SPEC-0053 v8 behaviour 13).
            let inside = Path::new(p);
            if inside.is_absolute()
                || inside
                    .components()
                    .any(|c| matches!(c, Component::ParentDir | Component::Prefix(_)))
            {
                return Err(McpError::invalid_params(
                    format!("{p} is not inside the workspace"),
                    None,
                ));
            }
            if self.workspace.root().join(inside).exists() && !args.overwrite.unwrap_or(false) {
                return Err(McpError::invalid_params(
                    format!("{p} exists; pass overwrite=true to replace it"),
                    None,
                ));
            }
            self.require(idecraft_core::Grant::Write).await?;
            let file = self.resolve_new(p)?;
            // An overwritten file open in an editor (SPEC-0220 v2 behaviour 9).
            self.refuse_unsaved([file.as_path()])?;
            std::fs::write(&file, &out.text)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
            value["written"] = serde_json::json!(file.display().to_string());
        }
        json_result(value)
    }

    #[tool(
        description = "Where this IDECraft process got its environment from (SPEC-0328): `source` is `inherited` (as started), `login_shell` (a window not started from a shell asked the user's login shell once at its start, so tools are found as in a terminal) or `fallback` (the shell failed or took longer than 5 s; the usual tool folders were added to PATH); `duration_ms` is how long asking took, `note` says why in words, `path` lists the folders of PATH in order. No variable's value is returned. Served by a window over HTTP it describes the window; `idecraft mcp` and `idecraft call` keep the environment they were started with unless IDECRAFT_SHELL_ENV=force is set (`off` never asks the shell)."
    )]
    async fn environment_source(&self) -> Result<CallToolResult, McpError> {
        let report = idecraft_core::shell_env::report();
        let path: Vec<String> = std::env::var_os("PATH")
            .map(|p| {
                std::env::split_paths(&p)
                    .map(|d| d.display().to_string())
                    .collect()
            })
            .unwrap_or_default();
        json_result(serde_json::json!({
            "source": report.source.as_str(),
            "duration_ms": u64::try_from(report.duration.as_millis()).unwrap_or(u64::MAX),
            "note": report.note,
            "path": path,
        }))
    }

    #[tool(
        description = "Keyboard diagnostics log (SPEC-0270): while the mode `Keyboard Diagnostics` is on in an IDECraft window (Help › Diagnostics, or Find Action), every keystroke the window receives is logged with key, character (typed text hidden), modifiers, the US key a layout key stands in for, the keymap stroke, the bound actions, the action that ran and the focus. Returns the log's path, whether it exists and its last `lines` lines (default 50, at most 500), each with its fields."
    )]
    async fn keyboard_diagnostics(
        &self,
        Parameters(args): Parameters<KeyboardDiagnosticsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let dir = self
            .log_dir
            .clone()
            .ok_or_else(|| McpError::internal_error("no log folder (HOME is not set)", None))?;
        let path = dir.join(idecraft_core::logs::KEYBOARD_LOG);
        let n = args.lines.unwrap_or(50).clamp(1, 500);
        let entries: Vec<serde_json::Value> = idecraft_core::logs::tail(&path, n)
            .iter()
            .map(|line| {
                let mut parts = line.split('\t');
                let mut entry = serde_json::Map::new();
                entry.insert("time".into(), parts.next().unwrap_or_default().into());
                entry.insert("event".into(), parts.next().unwrap_or_default().into());
                for field in parts {
                    if let Some((k, v)) = field.split_once('=') {
                        entry.insert(k.into(), v.into());
                    }
                }
                serde_json::Value::Object(entry)
            })
            .collect();
        json_result(serde_json::json!({
            "path": path.display().to_string(),
            "exists": path.exists(),
            "entries": entries,
        }))
    }

    #[tool(
        description = "The bundled themes (UI theme with its editor colour scheme: the IDECraft brand themes `IDECraft Dark`, the default for new installs, and `IDECraft Light`, and the reference's `Islands Dark`, `Islands Light`, `Dark`, `Light`), the one chosen and the default, with the chosen theme's `metrics` of trees, tabs and menus (row height, indentation, tab bar and tab height, pill or underline, paddings, corners, menu item height; SPEC-0154); `sync_with_os` with the preferred `dark_theme` and `light_theme` (SPEC-0131: while it is on the window shows the dark one while the system is dark and the light one otherwise, so `chosen` is not what is shown; `shown` names the theme only while it is off). With `set`, chooses a theme for IDECraft's windows; while Sync with OS is on the theme becomes the preferred theme of its kind instead, as in the theme popup (`saved_as` says which: `theme`, `dark_theme` or `light_theme`). `sync_with_os: true|false` switches Sync with OS, before `set`. Both need the `settings` right: the choice holds for every project. A running window switches when the theme is chosen in its theme popup (Quick Switch Scheme) and otherwise uses the choice at its next start."
    )]
    async fn themes(
        &self,
        Parameters(args): Parameters<ThemesArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_ui::theme::ThemeId;
        let theme = match &args.set {
            Some(name) => Some(ThemeId::from_name(name).ok_or_else(|| {
                let known: Vec<&str> = ThemeId::ALL.iter().map(|t| t.name()).collect();
                McpError::invalid_params(
                    format!("unknown theme `{name}` ({})", known.join(", ")),
                    None,
                )
            })?),
            None => None,
        };
        let mut saved_as = None;
        if theme.is_some() || args.sync_with_os.is_some() {
            let file = self.ide_settings_file.as_ref().ok_or_else(|| {
                McpError::internal_error("no settings folder (HOME is not set)", None)
            })?;
            // The theme is the user's choice for every project (SPEC-0053 v8 behaviour 12).
            self.require(idecraft_core::Grant::Settings).await?;
            let io = |e: std::io::Error| McpError::internal_error(e.to_string(), None);
            if let Some(on) = args.sync_with_os {
                let mut s = idecraft_core::load_ide_settings(file);
                s.appearance.sync_with_os = on;
                idecraft_core::save_ide_settings(file, &s).map_err(io)?;
            }
            if let Some(theme) = theme {
                let mut s = idecraft_core::load_ide_settings(file);
                if s.appearance.sync_with_os {
                    // While the theme follows the system, a chosen theme becomes the preferred
                    // theme of its kind, as in the window's popup (SPEC-0131 behaviour 3).
                    if theme.is_dark() {
                        s.appearance.dark_theme = theme.name().into();
                        saved_as = Some("dark_theme");
                    } else {
                        s.appearance.light_theme = theme.name().into();
                        saved_as = Some("light_theme");
                    }
                    idecraft_core::save_ide_settings(file, &s).map_err(io)?;
                } else {
                    // `appearance.theme` of the IDE settings (SPEC-0303 behaviour 14).
                    idecraft_core::save_chosen_theme(
                        file,
                        self.theme_file.as_deref(),
                        theme.name(),
                    )
                    .map_err(io)?;
                    saved_as = Some("theme");
                }
            }
        }
        // A missing or unknown choice means the default, IDECraft Dark (SPEC-0060 v6).
        let saved = match &self.ide_settings_file {
            Some(f) => idecraft_core::chosen_theme(f, self.theme_file.as_deref()),
            None => self
                .theme_file
                .as_deref()
                .and_then(idecraft_core::load_theme),
        };
        let chosen = ThemeId::from_saved(saved.as_deref());
        let appearance = self
            .ide_settings_file
            .as_deref()
            .map(idecraft_core::load_ide_settings)
            .unwrap_or_default()
            .appearance;
        // A preferred name that is no bundled theme gives the default of its kind (SPEC-0131
        // behaviour 2).
        let dark_theme =
            ThemeId::from_name(&appearance.dark_theme).unwrap_or(ThemeId::IdecraftDark);
        let light_theme =
            ThemeId::from_name(&appearance.light_theme).unwrap_or(ThemeId::IdecraftLight);
        let themes: Vec<serde_json::Value> = ThemeId::ALL
            .iter()
            .map(|t| {
                serde_json::json!({ "name": t.name(), "dark": t.is_dark(), "brand": t.is_brand() })
            })
            .collect();
        // Metrics of trees, tabs and menus in the chosen theme (SPEC-0154).
        let ui = idecraft_ui::theme::UiTheme::for_theme(chosen);
        let metrics = idecraft_ui::metrics::ThemeMetrics::of(&ui);
        // SPEC-0165: the same metrics in compact mode.
        let compact = idecraft_ui::metrics::ThemeMetrics::of_density(&ui, true);
        let shown = (!appearance.sync_with_os).then(|| chosen.name());
        json_result(serde_json::json!({
            "themes": themes, "chosen": chosen.name(), "default": ThemeId::DEFAULT.name(),
            "sync_with_os": appearance.sync_with_os, "dark_theme": dark_theme.name(),
            "light_theme": light_theme.name(), "shown": shown, "saved_as": saved_as,
            "metrics": metrics, "compact_metrics": compact,
        }))
    }

    #[tool(
        description = "The named tool window layouts of the user (SPEC-0333): arrangements of the tool windows saved under a name, kept in `window-layouts.json` in the user's settings folder and shared by all projects. `action: \"list\"` (default) returns `file`, `selected` (the selected layout's name, `Default` for the default layout), `layouts` (each with name, selected, shown, active_window, stripes and windows with id, side, placement, order, size, mode, removed), `skipped`, `problem` (the file could not be read: the default layout is used) and `limits`. `save` with `name` saves the workspace's saved tool window layout (`.idecraft/tool-windows.json`) with `shown` (ids of the shown tool windows) and `active_window` as a new layout and selects it; without `name` it saves them into the selected layout. `apply` with `name` (`Default` for the default layout) selects the layout and writes its arrangement to the workspace's layout file; `restore` does so for the selected layout; both return `shown` and `active_window`, and a running window uses the file at its next start. `rename` takes `name` and `new_name`; `delete` takes `name` (not the selected layout). Names: trimmed, 1 to 64 characters, no `/`, `\\` or control characters, not `Default`, unique when capitals are ignored. Every action but `list` takes `dry_run` (default true: `would` says what would change, nothing is written); with `dry_run: false` it needs the `settings` right for save, rename and delete (the named layouts are the user's own, for every project) and the `write` right for apply and restore (they write the project's tool window layout; `settings` too when the chosen layout changes)."
    )]
    async fn window_layouts(
        &self,
        Parameters(args): Parameters<WindowLayoutsArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_ui::tool_windows::{LAYOUT_FILE, Layout, ToolWindow};
        use idecraft_ui::window_layouts::{
            Applied, Arrangement, DEFAULT_TITLE, LayoutError, Layouts, MAX_LAYOUTS, MAX_NAME,
            Problem,
        };
        let invalid = |m: String| McpError::invalid_params(m, None);
        let file = self.window_layouts_file.clone().ok_or_else(|| {
            McpError::internal_error("no settings folder (HOME is not set)", None)
        })?;
        let root = self.workspace.root();
        let ids = |ws: &[ToolWindow]| ws.iter().map(|w| w.id()).collect::<Vec<_>>();
        let listing = |l: &Layouts| {
            let layouts: Vec<serde_json::Value> = l
                .saved()
                .map(|(name, a)| {
                    let windows: Vec<serde_json::Value> = ToolWindow::ALL
                        .into_iter()
                        .map(|w| {
                            serde_json::json!({
                                "id": w.id(),
                                "side": a.layout.side(w).name(),
                                "placement": a.layout.placement(w).name(),
                                "order": a.layout.position(w),
                                "size": a.layout.size(w),
                                "mode": a.layout.mode(w).id(),
                                "removed": a.layout.removed(w),
                            })
                        })
                        .collect();
                    serde_json::json!({
                        "name": name,
                        "selected": l.selected() == Some(name),
                        "shown": ids(&a.shown),
                        "active_window": a.active.map(|w| w.id()),
                        "stripes": a.layout.stripes,
                        "windows": windows,
                    })
                })
                .collect();
            serde_json::json!({
                "file": file.display().to_string(),
                "selected": l.selected_title(),
                "layouts": layouts,
                "skipped": l.skipped,
                "problem": l.problem.as_ref().map(Problem::message),
                "limits": { "name_characters": MAX_NAME, "layouts": MAX_LAYOUTS },
            })
        };
        let action = args.action.as_deref().unwrap_or("list");
        if action == "list" {
            return json_result(listing(&Layouts::load(&file)));
        }
        // What `save` saves: the workspace's saved layout with the windows the caller names.
        let arrangement = if action == "save" {
            let mut shown = Vec::new();
            for id in args.shown.as_deref().unwrap_or_default() {
                shown.push(
                    ToolWindow::from_id(id)
                        .ok_or_else(|| invalid(format!("unknown tool window `{id}`")))?,
                );
            }
            let active = match args.active_window.as_deref() {
                None => None,
                Some(id) => {
                    let w = ToolWindow::from_id(id)
                        .ok_or_else(|| invalid(format!("unknown tool window `{id}`")))?;
                    if !shown.contains(&w) {
                        return Err(invalid(format!(
                            "`active_window` {id} is not one of `shown`"
                        )));
                    }
                    Some(w)
                }
            };
            Some(Arrangement::new(&Layout::load(root), &shown, active))
        } else {
            None
        };
        let name = || {
            args.name
                .as_deref()
                .ok_or_else(|| invalid(format!("`{action}` needs `name`")))
        };
        let applied_json = |a: &Applied| {
            serde_json::json!({
                "selected": a.name.as_deref().unwrap_or(DEFAULT_TITLE),
                "writes": LAYOUT_FILE,
                "shown": a.shown.as_deref().map(ids),
                "active_window": a.active.map(|w| w.id()),
            })
        };
        // The change on the layouts as they are read; also what a dry run reports.
        let change = |l: &mut Layouts| -> Result<(serde_json::Value, Option<Applied>), McpError> {
            if let Some(problem @ Problem::Newer(_)) = &l.problem {
                return Err(invalid(problem.message()));
            }
            let refused = |e: LayoutError| invalid(e.to_string());
            Ok(match action {
                "save" => {
                    let arrangement = arrangement
                        .clone()
                        .unwrap_or_else(|| Arrangement::new(&Layout::default(), &[], None));
                    let (saved, new) = match args.name.as_deref() {
                        Some(n) => (l.save_new(n, arrangement).map_err(refused)?, true),
                        None => (l.save_changes(arrangement).map_err(refused)?, false),
                    };
                    (serde_json::json!({ "saved": saved, "new": new }), None)
                }
                "apply" => {
                    let a = l.select(Some(name()?)).map_err(refused)?;
                    (applied_json(&a), Some(a))
                }
                "restore" => {
                    let a = l.current();
                    (applied_json(&a), Some(a))
                }
                "rename" => {
                    let old = name()?;
                    let new = args
                        .new_name
                        .as_deref()
                        .ok_or_else(|| invalid("`rename` needs `new_name`".into()))?;
                    let renamed = l.rename(old, new).map_err(refused)?;
                    (
                        serde_json::json!({ "renamed": old.trim(), "to": renamed, "unchanged": renamed.is_none() }),
                        None,
                    )
                }
                "delete" => {
                    let deleted = l.delete(name()?).map_err(refused)?;
                    (serde_json::json!({ "deleted": deleted }), None)
                }
                other => {
                    return Err(invalid(format!(
                        "unknown action `{other}`: list, save, apply, restore, rename or delete"
                    )));
                }
            })
        };
        if args.dry_run.unwrap_or(true) {
            let mut layouts = Layouts::load(&file);
            let (would, _) = change(&mut layouts)?;
            let mut answer = listing(&Layouts::load(&file));
            answer["dry_run"] = serde_json::json!(true);
            answer["would"] = would;
            return json_result(answer);
        }
        // The named layouts are the user's own, for every project; applying one writes the
        // project's tool window layout (SPEC-0053 v8 behaviours 12 and 13).
        let user_file_only = matches!(action, "save" | "rename" | "delete");
        if user_file_only {
            self.require(idecraft_core::Grant::Settings).await?;
        } else {
            self.require(idecraft_core::Grant::Write).await?;
        }
        // Read again: the user may have been asked, and a window may have saved meanwhile.
        let mut layouts = Layouts::load(&file);
        let before = layouts.clone();
        let (done, applied) = change(&mut layouts)?;
        if !user_file_only && layouts != before {
            self.require(idecraft_core::Grant::Settings).await?;
        }
        if let Some(applied) = &applied {
            applied
                .layout
                .save(root)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        }
        if layouts != before {
            layouts
                .save(&file)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        }
        self.log(
            root,
            serde_json::json!({
                "time": unix_time(), "tool": "window_layouts", "action": action,
                "name": args.name, "new_name": args.new_name,
            }),
        )?;
        let mut answer = listing(&Layouts::load(&file));
        answer["dry_run"] = serde_json::json!(false);
        answer["done"] = done;
        json_result(answer)
    }

    #[tool(
        description = "The tool window layout of the workspace (SPEC-0167): each tool window with its id, title, side (left, bottom, right), order on that side, default side and activation action, and whether the stripes are shown. With `move` and `side`, docks a tool window to another side (last there); with `stripes`, shows or hides the stripes. Changes are saved in `.idecraft/tool-windows.json`; a running window uses them at its next start. With `restore_default`, puts the saved layout back to the default (sides, halves, order, no own sizes, view modes or removed buttons, stripes shown; SPEC-0167 v5). Each window also has its stripe icon, stripe (left/right), group (top/foot, the foot stacked from the bottom up) and index, header actions and views (SPEC-0061 v4) and its header (SPEC-0061 v5: shared or own, height, title, content_tabs, own toolbar buttons, actions); project_view lists the Project view extra nodes (External Libraries entries, Scratches and Consoles folders); with width and height (and shown, default project) the laid-out frame of stripes, side windows, editor, bottom windows and status bar in the chosen theme, with headers (each shown window's header, Options and Hide rectangles); main_toolbar lists the buttons right of the run configuration and the more-actions menu's entries. SPEC-0061 v7: each window has its placement (left_top, left_bottom, bottom_left, bottom_right, right_top, right_bottom), split, view mode (docked, unpinned, undocked, float, window), removed (no stripe button) and bounds (last Float/Window frame); `move` with `split` docks to a side's second half, `set_mode` with `mode` sets a view mode, `remove` and `restore` take a stripe button away or bring it back; the frame lays out split columns and bottom parts, lists Undock windows as overlays and Float/Window windows as separate; more_tool_windows lists the … popup's entries. SPEC-0061 v10: one tool window per placement (one_per_placement): in the frame a later id of `shown` replaces an earlier one of the same placement (listed in `replaced`), and `split_shown` shows windows in the other half of their side as ⌥-click on a stripe button does, without changing their placement; each window has default_placement, on_sidebar (a button when not shown; `restore` adds a window to the sidebar), on_sidebar_by_default and alt_click (the placement ⌥-click shows it in); layout_version and migrated (an untouched layout read with the new defaults)."
    )]
    async fn tool_windows(
        &self,
        Parameters(args): Parameters<ToolWindowsArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_ui::tool_windows::{Layout, Placement, Side, ToolWindow, ViewMode};
        let root = self.workspace.root();
        let mut layout = Layout::load(root);
        let mut changed = false;
        let window_of = |id: &str| {
            ToolWindow::from_id(id).ok_or_else(|| {
                McpError::invalid_params(format!("unknown tool window `{id}`"), None)
            })
        };
        // Restore Default Layout (SPEC-0167 v5 behaviour 17).
        if args.restore_default == Some(true) {
            changed |= layout.restore_default();
        }
        if let Some(id) = &args.r#move {
            let window = window_of(id)?;
            let side = args
                .side
                .as_deref()
                .and_then(Side::from_name)
                .ok_or_else(|| {
                    McpError::invalid_params("`side` must be left, bottom or right", None)
                })?;
            // SPEC-0061 v7 behaviour 46: the second half with `split`.
            changed |= layout.place(window, Placement::new(side, args.split.unwrap_or(false)));
        }
        if let Some(id) = &args.set_mode {
            let window = window_of(id)?;
            let mode = args
                .mode
                .as_deref()
                .and_then(ViewMode::from_id)
                .ok_or_else(|| {
                    McpError::invalid_params(
                        "`mode` must be docked, unpinned, undocked, float or window",
                        None,
                    )
                })?;
            changed |= layout.set_mode(window, mode);
        }
        if let Some(id) = &args.remove {
            changed |= layout.remove(window_of(id)?);
        }
        if let Some(id) = &args.restore {
            changed |= layout.restore(window_of(id)?);
        }
        if let Some(stripes) = args.stripes {
            changed |= layout.stripes != stripes;
            layout.stripes = stripes;
        }
        // The size of a tool window as dragging its edge sets it (SPEC-0061 v6 behaviour 34).
        if let Some(id) = &args.resize {
            let window = ToolWindow::from_id(id).ok_or_else(|| {
                McpError::invalid_params(format!("unknown tool window `{id}`"), None)
            })?;
            let size = args
                .size
                .ok_or_else(|| McpError::invalid_params("`resize` needs `size`", None))?;
            let before = layout.size(window);
            if size <= 0.0 {
                layout.clear_size(window);
            } else {
                layout.set_size(window, size);
            }
            changed |= layout.size(window) != before;
        }
        if changed {
            self.require(idecraft_core::Grant::Write).await?;
            layout
                .save(root)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        }
        // Stripe groups and positions, header actions and views (SPEC-0061 v4 behaviour 17).
        let stripe_of = |w: ToolWindow| -> (&'static str, &'static str, usize) {
            for stripe in [Side::Left, Side::Right] {
                let g = layout.stripe(stripe);
                for (name, group) in [("top", &g.top), ("split", &g.split), ("foot", &g.foot)] {
                    if let Some(i) = group.iter().position(|x| *x == w) {
                        return (stripe.name(), name, i);
                    }
                }
            }
            // A removed window has no button (SPEC-0061 v7 behaviour 40).
            ("none", "none", 0)
        };
        let header_height = {
            let saved = match &self.ide_settings_file {
                Some(f) => idecraft_core::chosen_theme(f, self.theme_file.as_deref()),
                None => self
                    .theme_file
                    .as_deref()
                    .and_then(idecraft_core::load_theme),
            };
            let theme = idecraft_ui::theme::ThemeId::from_saved(saved.as_deref());
            idecraft_ui::metrics::ThemeMetrics::of(&idecraft_ui::theme::UiTheme::for_theme(theme))
                .header
                .height
        };
        let windows: Vec<serde_json::Value> = ToolWindow::ALL
            .iter()
            .map(|w| {
                let (stripe, group, index) = stripe_of(*w);
                // The header per window (SPEC-0061 v5 behaviour 20).
                let h = w.header();
                let header = serde_json::json!({
                    "shared": h.shared, "height": header_height, "title": h.title,
                    "content_tabs": h.content_tabs, "toolbar": h.toolbar, "actions": h.actions,
                    // SPEC-0061 v6 behaviours 24 to 26: header buttons, toolbar row, line.
                    "buttons": h.buttons, "toolbar_row": !h.toolbar.is_empty(), "line": h.line,
                });
                let views: Vec<&str> = if *w == ToolWindow::Project {
                    vec!["Project", "Project Files"]
                } else {
                    Vec::new()
                };
                serde_json::json!({
                    "size": layout.size(*w),
                    "id": w.id(), "title": w.title(), "side": layout.side(*w).name(),
                    "order": layout.position(*w), "default_side": w.default_side().name(),
                    "action": w.action(), "icon": w.stripe_icon(),
                    "stripe": stripe, "stripe_group": group, "stripe_index": index,
                    "header_actions": h.actions, "views": views, "header": header,
                    // SPEC-0061 v7 behaviour 46.
                    "placement": layout.placement(*w).name(), "split": layout.placement(*w).split,
                    "mode": layout.mode(*w).id(), "removed": layout.removed(*w),
                    "bounds": layout.bounds(*w).map(|r| [r.x, r.y, r.w, r.h]),
                    // SPEC-0061 v10 behaviour 56.
                    "default_placement": w.default_placement().name(),
                    "on_sidebar": !layout.removed(*w),
                    "on_sidebar_by_default": w.on_sidebar_by_default(),
                    "alt_click": layout.other_half(*w).name(),
                })
            })
            .collect();
        // The Project view's extra top-level nodes (SPEC-0061 v4 behaviour 16).
        let scratches = idecraft_core::user_config_dir().map(|d| d.join("scratches"));
        let consoles = root.join(".idecraft/consoles");
        let files = self.workspace.files().unwrap_or_default();
        let project_view = serde_json::json!({
            "external_libraries": idecraft_core::library_entries(&idecraft_core::read_project(root, &files)),
            "scratches_and_consoles": {
                "scratches": scratches.filter(|d| d.is_dir()).map(|d| d.display().to_string()),
                "database_consoles": consoles.is_dir().then(|| consoles.display().to_string()),
            },
        });
        // The laid-out frame for a window size (SPEC-0061 v4 behaviour 17).
        let frame = match (args.width, args.height) {
            (Some(width), Some(height)) => {
                let shown: Vec<ToolWindow> = args
                    .shown
                    .clone()
                    .unwrap_or_else(|| vec!["project".into()])
                    .iter()
                    .filter_map(|id| ToolWindow::from_id(id))
                    .collect();
                {
                    let saved = match &self.ide_settings_file {
                        Some(f) => idecraft_core::chosen_theme(f, self.theme_file.as_deref()),
                        None => self
                            .theme_file
                            .as_deref()
                            .and_then(idecraft_core::load_theme),
                    };
                    let theme = idecraft_ui::theme::ThemeId::from_saved(saved.as_deref());
                    let split_shown: Vec<ToolWindow> = args
                        .split_shown
                        .clone()
                        .unwrap_or_default()
                        .iter()
                        .map(|id| window_of(id))
                        .collect::<Result<_, _>>()?;
                    Some(tool_window_frame(
                        theme,
                        &layout,
                        &shown,
                        &split_shown,
                        width,
                        height,
                    ))
                }
            }
            _ => None,
        };
        // The buttons right of the run configuration and the more-actions menu (SPEC-0061 v5
        // behaviour 20).
        let more: Vec<serde_json::Value> = idecraft_ui::menus::RUN_WIDGET_MORE
            .iter()
            .map(|e| match e {
                idecraft_ui::menus::Entry::Action(label, action) => {
                    serde_json::json!({"label": label, "action": action})
                }
                _ => serde_json::json!({"separator": true}),
            })
            .collect();
        // The Settings button's menu (SPEC-0061 v6 behaviour 28).
        let settings: Vec<serde_json::Value> = idecraft_ui::menus::SETTINGS_BUTTON_MENU
            .iter()
            .map(|e| match e {
                idecraft_ui::menus::Entry::Action(label, action) => {
                    serde_json::json!({"label": label, "action": action})
                }
                _ => serde_json::json!({"separator": true}),
            })
            .collect();
        let main_toolbar = serde_json::json!({
            "right": idecraft_ui::menus::MAIN_TOOLBAR_RIGHT, "more_actions": more,
            "settings_menu": settings,
            "run_widget_without_configuration": "Current File",
        });
        // The More tool windows popup (SPEC-0061 v7 behaviour 41): every tool window by title;
        // the window lists only those that exist.
        let more: Vec<serde_json::Value> =
            idecraft_ui::tool_windows::more_tool_windows(&ToolWindow::ALL)
                .into_iter()
                .map(|w| {
                    serde_json::json!({
                        "id": w.id(), "title": w.title(), "action": w.action(),
                        "icon": w.icon(), "removed": layout.removed(w),
                        "on_sidebar": !layout.removed(w),
                    })
                })
                .collect();
        json_result(serde_json::json!({
            "windows": windows, "stripes": layout.stripes, "changed": changed,
            "project_view": project_view, "frame": frame, "main_toolbar": main_toolbar,
            "more_tool_windows": more,
            // SPEC-0061 v10 behaviours 49, 54 and 56.
            "one_per_placement": true,
            "layout_version": idecraft_ui::tool_windows::LAYOUT_VERSION,
            "migrated": layout.migrated,
        }))
    }

    #[tool(
        description = "Python interpreters for the workspace without starting any of them: virtual environments in the project, the active VIRTUAL_ENV/CONDA_PREFIX environment, pyenv versions and interpreters on PATH, with version and kind; which one is selected and why; whether it satisfies `requires-python`; installed packages of the selected environment; declared dependencies that are missing or have a non-matching version; test framework and a suggested test run configuration."
    )]
    async fn python_environments(
        &self,
        Parameters(args): Parameters<PythonEnvironmentsArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root();
        let mut search = idecraft_core::PythonSearch::for_workspace(root);
        if let Some(i) = args.interpreter {
            search.configured = Some(std::path::PathBuf::from(i));
        }
        json_result(self.python_env(search)?)
    }

    /// The Python environment for `search` with the root module's declarations (SPEC-0050).
    fn python_env(
        &self,
        search: idecraft_core::PythonSearch,
    ) -> Result<idecraft_core::PythonEnvironments, McpError> {
        let root = self.workspace.root();
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let model = idecraft_core::read_project(root, &files);
        let python = model
            .modules
            .iter()
            .find(|m| m.kind == idecraft_core::ModuleKind::Python && m.dir == ".");
        let requires = python
            .and_then(|m| m.toolchain.as_deref())
            .map(|t| t.strip_prefix("python ").unwrap_or(t));
        let declared = python.map(|m| m.dependencies.as_slice()).unwrap_or(&[]);
        Ok(idecraft_core::python_environments(
            &search, requires, declared,
        ))
    }

    #[tool(
        description = "Choose the workspace's Python interpreter as the status bar chooser does: saved in `.idecraft/python.toml` (workspace-relative inside the workspace) and used by python_environments, the Python Packages window and new installs. Omit `interpreter` to return to the automatic choice. dry_run defaults to true and only reports what would be saved and which interpreter would then be selected."
    )]
    async fn python_select_interpreter(
        &self,
        Parameters(args): Parameters<PythonSelectArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root().to_path_buf();
        let path = match &args.interpreter {
            Some(i) => {
                // Any interpreter the chooser lists may be chosen (SPEC-0117 behaviour 2); other
                // paths only inside the workspace.
                let found = self
                    .python_env(idecraft_core::PythonSearch::from_env(&root))?
                    .interpreters
                    .into_iter()
                    .find(|f| f.path == *i);
                let p = match found {
                    Some(f) => PathBuf::from(f.path),
                    None => self.resolve(i)?,
                };
                if !p.exists() {
                    return Err(McpError::invalid_params(
                        format!("{i} does not exist"),
                        None,
                    ));
                }
                Some(p)
            }
            None => None,
        };
        let mut search = idecraft_core::PythonSearch::from_env(&root);
        search.configured = path.clone();
        let env = self.python_env(search)?;
        let selected = env.selected.and_then(|i| env.interpreters.get(i)).cloned();
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true,
                "would_save": path.as_ref().map(|p| p.strip_prefix(&root).unwrap_or(p).display().to_string()),
                "selected": selected,
            }));
        }
        self.require(idecraft_core::Grant::Write).await?;
        let saved = idecraft_core::save_interpreter(&root, path.as_deref())
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        // Running Python language servers follow the new choice (SPEC-0170 behaviour 4).
        let pushed = tokio::task::spawn_blocking(move || {
            idecraft_languages::python_server::interpreter_changed(&root)
        })
        .await
        .unwrap_or(0);
        json_result(serde_json::json!({
            "dry_run": false, "saved": saved, "selected": selected, "language_servers_updated": pushed,
        }))
    }

    #[tool(
        description = "The Python language server (pyright or basedpyright) of the workspace and the interpreter it resolves imports with: server program and path (or why there is none), the selected interpreter and why, the settings answered to the server's `workspace/configuration` (`python.pythonPath`), and whether `pyrightconfig.json` or `[tool.pyright]` names an environment (then that file decides). `apply: true` sends the settings to running servers with `workspace/didChangeConfiguration` and reports how many got them."
    )]
    async fn python_language_server(
        &self,
        Parameters(args): Parameters<PythonLanguageServerArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root().to_path_buf();
        let apply = args.apply.unwrap_or(false);
        if apply {
            // Pushing settings to the running servers changes them (SPEC-0053 v8).
            self.require(idecraft_core::Grant::Write).await?;
        }
        let report = tokio::task::spawn_blocking(move || {
            idecraft_languages::python_server::report(&root, apply)
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        json_result(report)
    }

    #[tool(
        description = "Search the Python package index (PyPI) by package name: exact name first, then names starting with the query, then names containing it (normalised, at most 50), each with the version installed in the selected environment. The name list is downloaded once into the user cache and refreshed weekly. Needs the user-granted `http` right."
    )]
    async fn python_search_packages(
        &self,
        Parameters(args): Parameters<PythonSearchPackagesArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Http).await?;
        let (index, cache) = self.package_index()?;
        let query = args.query.clone();
        let (matches, total) = tokio::task::spawn_blocking(move || {
            idecraft_core::names(&idecraft_core::http_fetch, &index, &cache).map(|names| {
                (
                    idecraft_core::search_names(&names, &query, idecraft_core::SEARCH_LIMIT),
                    names.len(),
                )
            })
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?
        .map_err(|e| McpError::internal_error(e, None))?;
        let env = self.python_env(idecraft_core::PythonSearch::for_workspace(
            self.workspace.root(),
        ))?;
        let matches: Vec<_> = matches
            .into_iter()
            .map(|name| {
                let installed = env
                    .packages
                    .iter()
                    .find(|p| p.name == idecraft_core::normalize_name(&name))
                    .map(|p| p.version.clone());
                serde_json::json!({"name": name, "installed": installed})
            })
            .collect();
        json_result(
            serde_json::json!({"query": args.query, "index_names": total, "matches": matches}),
        )
    }

    #[tool(
        description = "Details of one Python package from the package index (PyPI): summary, latest version, requires-python, home page and the versions newest first (fully yanked ones left out, pre-releases marked), the version installed in the selected environment, and how it would be installed (uv when uv.lock or [tool.uv], Poetry when poetry.lock or [tool.poetry]; else by the environment: uv when it was made by uv or has no pip, else pip; a tool that is not on PATH is replaced with the reason in `notes`, and an environment without pip and without uv is refused with the remedies): the exact command for `version` or the latest. `install: true` runs it (needs the user-granted `run` right; logged in `.idecraft/agent-log.jsonl`). Shared system/pyenv interpreters are refused for uv and pip. Needs the `http` right."
    )]
    async fn python_package_info(
        &self,
        Parameters(args): Parameters<PythonPackageInfoArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Http).await?;
        let (index, _) = self.package_index()?;
        let name = args.name.clone();
        let info = tokio::task::spawn_blocking(move || {
            idecraft_core::package_info(&idecraft_core::http_fetch, &index, &name)
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?
        .map_err(|e| McpError::internal_error(e, None))?
        .ok_or_else(|| {
            McpError::invalid_params(format!("{} is not on the package index", args.name), None)
        })?;
        let root = self.workspace.root().to_path_buf();
        let env = self.python_env(idecraft_core::PythonSearch::for_workspace(&root))?;
        let chosen = env.selected.and_then(|i| env.interpreters.get(i));
        let installed = env
            .packages
            .iter()
            .find(|p| p.name == idecraft_core::normalize_name(&info.name))
            .map(|p| p.version.clone());
        let version = args.version.clone().unwrap_or_else(|| info.latest.clone());
        if !info.releases.iter().any(|r| r.version == version) {
            return Err(McpError::invalid_params(
                format!("{} has no version {version}", info.name),
                None,
            ));
        }
        let tools = self.python_tool_path.clone();
        let plan = idecraft_core::install_plan(
            &root,
            chosen,
            &idecraft_core::requirement(&info.name, Some(&version)),
            &|program| idecraft_core::find_tool(tools.as_deref(), program),
        );
        if !args.install.unwrap_or(false) {
            return json_result(serde_json::json!({
                "package": info, "installed": installed, "install": plan,
            }));
        }
        if let Some(why) = &plan.refused {
            return Err(McpError::invalid_params(why.clone(), None));
        }
        self.require(idecraft_core::Grant::Run).await?;
        let command = plan.command.clone();
        let cwd = root.clone();
        let run = tokio::task::spawn_blocking(move || idecraft_core::run_tool(&command, &cwd))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.log(
            &root,
            serde_json::json!({"time": unix_time(), "tool": "python_package_info", "command": plan.command, "exit_code": run.exit_code}),
        )?;
        json_result(
            serde_json::json!({"package": info.name, "version": version, "install": plan, "run": run}),
        )
    }

    #[tool(
        description = "Create a Python virtual environment in the workspace (`<base> -m venv <path>`, path default `.venv`) from the selected interpreter or its base, and choose it. dry_run defaults to true and returns the command; dry_run=false runs it (needs the user-granted `run` right), saves the new interpreter as the workspace's choice and returns the outcome. An existing folder is refused. Logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn python_create_venv(
        &self,
        Parameters(args): Parameters<PythonCreateVenvArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root().to_path_buf();
        let rel = args.path.unwrap_or_else(|| ".venv".into());
        let relative = Path::new(&rel);
        if relative.is_absolute()
            || relative
                .components()
                .any(|c| !matches!(c, std::path::Component::Normal(_)))
        {
            return Err(McpError::invalid_params(
                format!("{rel} must be a folder inside the workspace, written relative to it"),
                None,
            ));
        }
        let target = root.join(relative);
        if target.exists() {
            return Err(McpError::invalid_params(
                format!("{rel} exists already"),
                None,
            ));
        }
        let env = self.python_env(idecraft_core::PythonSearch::for_workspace(&root))?;
        let command = idecraft_core::venv_command(&idecraft_core::venv_base(&env), Path::new(&rel));
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({ "dry_run": true, "would_run": command }));
        }
        self.require(idecraft_core::Grant::Run).await?;
        // The environment and `.idecraft/python.toml` are files of the project (SPEC-0053 v8).
        self.require(idecraft_core::Grant::Write).await?;
        let cwd = root.clone();
        let run_command = command.clone();
        let run = tokio::task::spawn_blocking(move || idecraft_core::run_tool(&run_command, &cwd))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let python = idecraft_core::venv_python(&target);
        let saved = if run.ok {
            idecraft_core::save_interpreter(&root, Some(&python))
                .map_err(|e| McpError::internal_error(e.to_string(), None))?
        } else {
            None
        };
        self.log(
            &root,
            serde_json::json!({"time": unix_time(), "tool": "python_create_venv", "command": command, "exit_code": run.exit_code}),
        )?;
        json_result(serde_json::json!({ "dry_run": false, "run": run, "saved": saved }))
    }

    #[tool(
        description = "Install Python packages into the selected environment (no shell). The installer is chosen as in the Python Packages window: `uv pip install --python <interpreter> …` when the project uses uv (`uv.lock`, `[tool.uv]`), the environment was made by uv (`uv = …` in `pyvenv.cfg`) or has no pip, and uv is on PATH; else `<interpreter> -m pip install …`. The answer names it in `installer` (`uv` or `pip`) with the reasons in `notes`; an environment without pip when uv is not found is refused, naming the remedies (`python -m ensurepip` there, or installing uv). Without `packages` and `imports`, installs every declared dependency the environment does not satisfy (PEP 440 requirements kept, Poetry `^`/`~` as the bare name). `imports` takes module names of unresolved imports (`yaml`, `PIL.Image`) and maps each to its distribution: an unsatisfied declared requirement first, then well-known names (`yaml` PyYAML, `PIL` Pillow, `cv2` opencv-python, `sklearn` scikit-learn, `bs4` beautifulsoup4, …), else the import name; the answer lists the mapping (import, package, spec, source requirement/known/import). A plain system or pyenv interpreter is refused: create or choose a virtual environment first. dry_run defaults to true and returns in `would_run` the command that would really run; dry_run=false runs it (needs the user-granted `run` right) and returns exit code and the last output lines. Logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn python_install_packages(
        &self,
        Parameters(args): Parameters<PythonInstallArgs>,
    ) -> Result<CallToolResult, McpError> {
        let root = self.workspace.root().to_path_buf();
        let env = self.python_env(idecraft_core::PythonSearch::for_workspace(&root))?;
        let Some(chosen) = env.selected.and_then(|i| env.interpreters.get(i)).cloned() else {
            return Err(McpError::invalid_params(
                "no Python interpreter found",
                None,
            ));
        };
        // Imports become distributions (SPEC-0117 v4 behaviour 8).
        let mut mapping = Vec::new();
        for module in args.imports.iter().flatten() {
            let found =
                idecraft_core::import_package(module, &env.unsatisfied).ok_or_else(|| {
                    McpError::invalid_params(format!("{module:?} is no absolute module name"), None)
                })?;
            mapping.push(found);
        }
        let mut specs: Vec<String> = match &args.packages {
            Some(p) => p.iter().filter(|s| !s.trim().is_empty()).cloned().collect(),
            None if args.imports.is_some() => Vec::new(),
            None => env
                .unsatisfied
                .iter()
                .map(idecraft_core::pip_spec)
                .collect::<Vec<_>>(),
        };
        for found in &mapping {
            if !specs.contains(&found.spec) {
                specs.push(found.spec.clone());
            }
        }
        if specs.is_empty() {
            return json_result(
                serde_json::json!({ "dry_run": args.dry_run.unwrap_or(true), "nothing_to_install": true }),
            );
        }
        // The installer the window uses too (SPEC-0171 v2 behaviour 4): uv or pip by the project
        // and the environment; a shared interpreter and an environment without pip and without
        // uv are refused before anything runs, in the preview as well.
        let tools = self.python_tool_path.clone();
        let plan =
            idecraft_core::environment_install_plan(&root, Some(&chosen), &specs, &|program| {
                idecraft_core::find_tool(tools.as_deref(), program)
            });
        if let Some(why) = &plan.refused {
            return Err(McpError::invalid_params(why.clone(), None));
        }
        let command = plan.command.clone();
        let mapping = (!mapping.is_empty()).then_some(mapping);
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true, "would_run": command, "installer": plan.installer,
                "notes": plan.notes, "mapping": mapping,
            }));
        }
        self.require(idecraft_core::Grant::Run).await?;
        self.require_trusted()?;
        let cwd = root.clone();
        let run_command = command.clone();
        let run = tokio::task::spawn_blocking(move || idecraft_core::run_tool(&run_command, &cwd))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.log(
            &root,
            serde_json::json!({"time": unix_time(), "tool": "python_install_packages", "command": command, "exit_code": run.exit_code}),
        )?;
        // The Python language server reads the environment again (SPEC-0117 v3 behaviour 7).
        if run.ok {
            idecraft_languages::pool::restart_language(
                &root,
                idecraft_languages::LanguageId::Python,
            );
        }
        json_result(serde_json::json!({
            "dry_run": false, "run": run, "installer": plan.installer, "notes": plan.notes,
            "mapping": mapping,
        }))
    }

    #[tool(
        description = "Check a JavaScript/TypeScript file with the project's own ESLint (`node_modules/.bin/eslint` with an `eslint.config.*`/`.eslintrc*`/`eslintConfig` in or above its package, inside the workspace; nothing is downloaded): findings with 1-based line, severity, rule, message and whether `--fix` can fix them. With `fix`, also the fixed text; `dry_run=false` writes it, refusing if the file changed meanwhile."
    )]
    async fn eslint_file(
        &self,
        Parameters(args): Parameters<EslintFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::js_tools;
        let (root, file) = self.source(&args.path)?;
        let tool = js_tools::find_eslint(&root, &file).ok_or_else(|| {
            McpError::invalid_params("no ESLint with a configuration in this project", None)
        })?;
        self.require_trusted()?;
        let text = self.read_document(&file)?;
        let fix = args.fix.unwrap_or(false);
        let (t, f, x) = (tool.clone(), file.clone(), text.clone());
        let (problems, fixed) = tokio::task::spawn_blocking(move || {
            let problems = js_tools::eslint_check(&t, &f, &x)?;
            let fixed = if fix {
                js_tools::eslint_fix(&t, &f, &x)?
            } else {
                None
            };
            Ok::<_, String>((problems, fixed))
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?
        .map_err(|e| McpError::invalid_params(e, None))?;
        let applied = fix && fixed.is_some() && !args.dry_run.unwrap_or(true);
        if applied && let Some(new) = &fixed {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, new).await?;
        }
        json_result(serde_json::json!({
            "problems": problems,
            "fixed": fixed,
            "applied": applied,
        }))
    }

    #[tool(
        description = "Format a file with the project's own Prettier (`node_modules/.bin/prettier` in or above its package, inside the workspace, with the project's configuration; nothing is downloaded). dry_run defaults to true and returns whether it changes and the formatted text; dry_run=false writes it, refusing if the file changed meanwhile."
    )]
    async fn prettier_file(
        &self,
        Parameters(args): Parameters<JvmFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::js_tools;
        let (root, file) = self.source(&args.path)?;
        let tool = js_tools::find_prettier(&root, &file)
            .ok_or_else(|| McpError::invalid_params("no Prettier in this project", None))?;
        self.require_trusted()?;
        let text = self.read_document(&file)?;
        let (t, f, x) = (tool.clone(), file.clone(), text.clone());
        let formatted = tokio::task::spawn_blocking(move || js_tools::prettier_format(&t, &f, &x))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?
            .map_err(|e| McpError::invalid_params(e, None))?;
        let changed = formatted != text;
        let applied = changed && !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &formatted).await?;
        }
        json_result(serde_json::json!({
            "changed": changed,
            "applied": applied,
            "text": formatted,
        }))
    }

    #[tool(
        description = "The run markers of a Java or Kotlin file (what the ▶ in the editor gutter offers): `main` classes and functions, test classes and test methods (JUnit 4/5 `@Test`, `@ParameterizedTest`, `@RepeatedTest`, `@TestFactory`, `@TestTemplate`) with their 1-based line and the run configuration each starts — a single test method runs alone through Maven (`-Dtest=Class#method`) or Gradle (`--tests pkg.Class.method`). Also the `describe`, `it` and `test` calls of a Vitest or Jest file (`*.test.*`, `*.spec.*`), each running alone with the runner's `-t` name filter; `class` is then the full test name. Also the tests of pytest (`test_*.py`, `*_test.py`: `test*` functions and `Test*` classes, run as `file::Class::name`), Go (`*_test.go`: `TestXxx`, run with `-run '^TestXxx$'`) and Rust (`#[test]` functions, `class` their module path, run with `cargo test path -- --exact`). Run one with `run_command`."
    )]
    async fn run_markers(
        &self,
        Parameters(args): Parameters<JvmFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::jvm::{Jvm, MarkerKind};
        let (root, file) = self.source(&args.path)?;
        let lang = Jvm::of(&args.path);
        // pytest, Go and Rust tests (SPEC-0045 v5 behaviour 13).
        let other = idecraft_languages::test_markers::test_file(&args.path).is_some();
        if lang.is_none() && !idecraft_core::is_js_test_file(&args.path) && !other {
            return Err(McpError::invalid_params(
                "not a .java, .kt, JavaScript/TypeScript, pytest, Go or Rust test file",
                None,
            ));
        }
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let rel = file
            .strip_prefix(&root)
            .unwrap_or(&file)
            .to_string_lossy()
            .replace('\\', "/");
        let files = self
            .workspace
            .files()
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let model = idecraft_core::read_project(self.workspace.root(), &files);
        let found = match lang {
            Some(lang) => idecraft_languages::jvm::run_markers(lang, &text),
            None if other => idecraft_languages::test_markers::markers(&rel, &text),
            None => idecraft_languages::js_tests::markers(&rel, &text),
        };
        let markers: Vec<serde_json::Value> = found
            .into_iter()
            .map(|m| {
                let config = match (&m.kind, &m.method) {
                    _ if other => idecraft_core::single_test_config(
                        &model,
                        &rel,
                        &text,
                        &m.class,
                        m.method.as_deref(),
                    ),
                    (kind, None) if lang.is_none() => idecraft_core::js_test_config(
                        &model,
                        &rel,
                        &text,
                        &m.class,
                        *kind == MarkerKind::TestClass,
                    ),
                    (MarkerKind::TestMethod, Some(method)) => {
                        idecraft_core::test_method_config(&model, &rel, &text, method)
                    }
                    _ => idecraft_core::context_config(&model, &rel, &text),
                };
                serde_json::json!({
                    "line": m.line + 1,
                    "kind": m.kind,
                    "class": m.class,
                    "method": m.method,
                    "run": config,
                })
            })
            .collect();
        json_result(serde_json::json!({ "path": args.path, "markers": markers }))
    }

    #[tool(
        description = "Optimize Imports. Python file: with `ruff` installed (selected environment in a trusted project, else PATH; never downloaded) runs `ruff check --select F401,I --fix-only` on the file's text in the project root, which removes unused imports and sorts the imports by the project's configuration; without ruff removes the imports the Python language server marks as not accessed — only import statements of the module itself that stand alone on their lines and hold no comment, `import a, b` keeping its used names — sorts nothing and refuses an `__init__.py`. JavaScript, TypeScript, Vue or Svelte file (`.ts .tsx .mts .cts .js .jsx .mjs .cjs .vue .svelte`, SPEC-0123 v4): the file's language server removes the unused imports and sorts and combines the rest with its organize-imports code actions (`source.removeUnusedImports` then `source.sortImports` where it announces both, else `source.organizeImports`); the project's ESLint and Prettier are not run; without the server the error names it and nothing changes. Both return `changed`, `applied`, `removed` (the imported names that went), `left` (unused imports left, with the reason), `by` (`ruff` or `language server`), `sorted`, `summary` and the new `text`. Java or Kotlin file, without a language server: removes unused single-name imports, duplicates, `java.lang` and same-package imports; keeps wildcard imports and (Kotlin) operator/delegate convention imports such as `getValue`; sorts in the reference's default layout (Java: others, blank line, `javax.*`/`java.*`, blank line, static imports; Kotlin: others, `java.*`, `javax.*`, `kotlin.*`, aliases). Refuses when comments sit between imports. dry_run defaults to true and returns the removed imports and the new block; dry_run=false writes the file, refusing if it changed meanwhile."
    )]
    async fn optimize_imports(
        &self,
        Parameters(args): Parameters<JvmFileArgs>,
    ) -> Result<CallToolResult, McpError> {
        // Python: ruff, else the unused imports the language server reports (`SPEC-0329`).
        if LanguageId::detect(std::path::Path::new(&args.path)) == Some(LanguageId::Python) {
            return self
                .python_optimize_imports(&args.path, args.dry_run.unwrap_or(true))
                .await;
        }
        // JavaScript, TypeScript, Vue, Svelte: the language server (`SPEC-0123` v4 behaviour 6).
        if idecraft_languages::js_imports::applies(std::path::Path::new(&args.path)) {
            return self
                .js_optimize_imports(&args.path, args.dry_run.unwrap_or(true))
                .await;
        }
        let lang = idecraft_languages::jvm::Jvm::of(&args.path).ok_or_else(|| {
            McpError::invalid_params(
                "not a Java, Kotlin, Python, JavaScript, TypeScript, Vue or Svelte file",
                None,
            )
        })?;
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let Some(plan) = idecraft_languages::jvm::optimize_imports(lang, &text)
            .map_err(|e| McpError::invalid_params(e, None))?
        else {
            return json_result(serde_json::json!({ "changed": false }));
        };
        let edit = idecraft_languages::jvm::TextEdit {
            range: plan.range.clone(),
            text: plan.replacement.clone(),
        };
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(
                &file,
                &text,
                &idecraft_languages::jvm::apply(&text, &[edit]),
            )
            .await?;
        }
        json_result(serde_json::json!({
            "changed": true,
            "applied": applied,
            "removed": plan.removed,
            "imports": plan.replacement,
        }))
    }

    #[tool(
        description = "What Generate offers in the Java class around a 1-based line (SPEC-0122 v4): for each kind that applies its fields with `checked` (the default selection) and its `templates`, usable as `fields` and `template` of generate_code. Reads only."
    )]
    async fn generate_choices(
        &self,
        Parameters(args): Parameters<GenerateChoicesArgs>,
    ) -> Result<CallToolResult, McpError> {
        use idecraft_languages::jvm::{GenerateTemplate, applicable_kinds, chooser_fields};
        if !args.path.ends_with(".java") {
            return Err(McpError::invalid_params("not a .java file", None));
        }
        let (_, file) = self.source(&args.path)?;
        let text = std::fs::read_to_string(&file)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let offset = text
            .split_inclusive('\n')
            .take(args.line.saturating_sub(1))
            .map(str::len)
            .sum::<usize>();
        let kinds: Vec<_> = applicable_kinds(&text, offset)
            .into_iter()
            .map(|kind| {
                let fields: Vec<_> = chooser_fields(&text, offset, kind)
                    .into_iter()
                    .map(|(f, checked)| {
                        serde_json::json!({"name": f.name, "type": f.ty, "checked": checked})
                    })
                    .collect();
                serde_json::json!({
                    "kind": kind,
                    "label": kind.label(),
                    "fields": fields,
                    "templates": GenerateTemplate::of(kind),
                })
            })
            .collect();
        json_result(serde_json::json!({ "kinds": kinds }))
    }

    #[tool(
        description = "Generate code in the Java class around a line, from its non-static fields, the way the reference's Generate menu does: `constructor`, `getters` (booleans as `isX`), `setters` (non-final fields), `getters_and_setters`, `equals_hash_code` (`java.util.Objects`, `Float/Double.compare`, `Arrays` for arrays) or `to_string`. In Java `fields` narrows the fields and `template` picks one of generate_choices (`fluent` accessors, `instanceof`, `getters`, `instanceof_getters`, `string_builder`); `override_annotation` false leaves @Override off `to_string`. Methods that exist are not made twice; needed imports are added. dry_run defaults to true and returns the edits and the new text; dry_run=false writes the file, refusing if it changed meanwhile. In a Kotlin class (.kt, SPEC-0132): `constructor` (a secondary constructor from the typed body properties, only without primary constructor parameters), `equals_hash_code` and `to_string` over the `val`/`var` properties; data classes are refused."
    )]
    async fn generate_code(
        &self,
        Parameters(args): Parameters<GenerateCodeArgs>,
    ) -> Result<CallToolResult, McpError> {
        let kotlin = args.path.ends_with(".kt");
        if !args.path.ends_with(".java") && !kotlin {
            return Err(McpError::invalid_params("not a .java or .kt file", None));
        }
        let (_, file) = self.source(&args.path)?;
        let text = self.read_document(&file)?;
        let offset = text
            .split_inclusive('\n')
            .take(args.line.saturating_sub(1))
            .map(str::len)
            .sum::<usize>();
        let edits = if kotlin {
            if args.fields.is_some() || args.template.is_some() {
                return Err(McpError::invalid_params(
                    "fields and template work in Java only",
                    None,
                ));
            }
            idecraft_languages::jvm::generate_kotlin(&text, offset, args.kind.into())
        } else {
            let template = match args.template {
                Some(t) => serde_json::from_value(serde_json::json!(t)).map_err(|_| {
                    McpError::invalid_params(format!("unknown template `{t}`"), None)
                })?,
                None => idecraft_languages::jvm::GenerateTemplate::Default,
            };
            let options = idecraft_languages::jvm::GenerateOptions {
                fields: args.fields,
                template,
                override_annotation: args.override_annotation.unwrap_or(true),
            };
            idecraft_languages::jvm::generate_with(&text, offset, args.kind.into(), &options)
        }
        .map_err(|e| McpError::invalid_params(e, None))?;
        let new_text = idecraft_languages::jvm::apply(&text, &edits);
        let applied = !args.dry_run.unwrap_or(true);
        if applied {
            self.require(idecraft_core::Grant::Write).await?;
            self.write_document(&file, &text, &new_text).await?;
        }
        json_result(serde_json::json!({ "applied": applied, "edits": edits, "text": new_text }))
    }

    #[tool(
        description = "SSH hosts configured in `~/.ssh/config` (and its includes) with the user, host name and port `ssh -G` resolves; nothing is connected. Use an alias as `host` in the other remote_* tools, or `[user@]host[:port]`."
    )]
    async fn remote_hosts(&self) -> Result<CallToolResult, McpError> {
        let extra = self.ssh_extra.clone();
        let hosts = tokio::task::spawn_blocking(move || idecraft_remote::host_list(&extra))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        json_result(serde_json::json!({ "hosts": hosts }))
    }

    #[tool(
        description = "List a folder on an SSH host (default: the home folder): resolved absolute path, then folders and files by name with a flag for symbolic links. Uses the system ssh with the user's keys and agent, batch mode and strict host key checking (unknown or changed host keys are refused with what to do). Needs the user-granted `ssh` right."
    )]
    async fn remote_list(
        &self,
        Parameters(args): Parameters<RemoteListArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        let out = tokio::task::spawn_blocking(move || {
            let dir = match args.path {
                Some(p) => r.resolve_dir(&p)?,
                None => r.home()?,
            };
            let entries = r.list(&dir)?;
            Ok::<_, idecraft_remote::RemoteError>((dir, entries))
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?
        .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "path": out.0, "entries": out.1 }))
    }

    #[tool(
        description = "Read a file on an SSH host (at most 10 MiB) as UTF-8 text (invalid bytes replaced) with its `stamp` (POSIX cksum), to pass to `remote_write` so a change made on the host meanwhile is not overwritten. Needs the user-granted `ssh` right."
    )]
    async fn remote_read(
        &self,
        Parameters(args): Parameters<RemoteReadArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        let path = args.path.clone();
        let file = tokio::task::spawn_blocking(move || r.read(&path))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({
            "path": args.path,
            "stamp": file.stamp,
            "content": String::from_utf8_lossy(&file.bytes),
        }))
    }

    #[tool(
        description = "Write a file on an SSH host through a temporary file in the same folder that keeps the old file's mode, renamed into place. With `expected_stamp` (from `remote_read`) a file that changed meanwhile is left alone and the call fails with `changed`; without it the file must not exist yet. dry_run defaults to true and only reports what would be written; dry_run=false needs the user-granted `ssh` right and is logged in `.idecraft/agent-log.jsonl` (path and size, not the content)."
    )]
    async fn remote_write(
        &self,
        Parameters(args): Parameters<RemoteWriteArgs>,
    ) -> Result<CallToolResult, McpError> {
        if !args.path.starts_with('/') {
            return Err(McpError::invalid_params("the path must be absolute", None));
        }
        let size = args.content.len();
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true,
                "would_write": { "host": args.host, "path": args.path, "bytes": size, "new_file": args.expected_stamp.is_none() },
            }));
        }
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        let (path, content, expected) = (args.path.clone(), args.content, args.expected_stamp);
        let result = tokio::task::spawn_blocking(move || {
            r.write(&path, content.as_bytes(), expected.as_deref())
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let root = self.workspace.root().to_path_buf();
        self.log(
            &root,
            serde_json::json!({"time": unix_time(), "tool": "remote_write", "host": args.host, "path": args.path, "bytes": size, "ok": result.is_ok()}),
        )?;
        let stamp = result.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "dry_run": false, "stamp": stamp }))
    }

    #[tool(
        description = "Create an empty file (`kind` file, default) or a folder (`kind` dir) on an SSH host (SPEC-0253); refused when something of that name exists. dry_run defaults to true and only describes it; dry_run=false needs the user-granted `ssh` right and is logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn remote_create(
        &self,
        Parameters(args): Parameters<RemoteCreateArgs>,
    ) -> Result<CallToolResult, McpError> {
        let kind = match args.kind.as_deref().unwrap_or("file") {
            "file" => idecraft_remote::NewEntry::File,
            "dir" => idecraft_remote::NewEntry::Dir,
            other => {
                return Err(McpError::invalid_params(
                    format!("kind must be file or dir, not {other}"),
                    None,
                ));
            }
        };
        idecraft_remote::check_path(&args.path)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true,
                "would_create": { "host": args.host, "path": args.path, "kind": kind },
            }));
        }
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        let path = args.path.clone();
        let result = tokio::task::spawn_blocking(move || r.create(&path, kind))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.remote_log(
            "remote_create",
            &args.host,
            serde_json::json!({"path": args.path, "kind": kind}),
            result.is_ok(),
        )?;
        result.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "dry_run": false, "created": args.path }))
    }

    #[tool(
        description = "Rename or move an entry on an SSH host (SPEC-0253): `to` must not exist yet and its folder must. dry_run defaults to true; dry_run=false needs the user-granted `ssh` right and is logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn remote_rename(
        &self,
        Parameters(args): Parameters<RemoteRenameArgs>,
    ) -> Result<CallToolResult, McpError> {
        for p in [&args.from, &args.to] {
            idecraft_remote::check_path(p)
                .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        }
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true,
                "would_rename": { "host": args.host, "from": args.from, "to": args.to },
            }));
        }
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        let (from, to) = (args.from.clone(), args.to.clone());
        let result = tokio::task::spawn_blocking(move || r.rename(&from, &to))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.remote_log(
            "remote_rename",
            &args.host,
            serde_json::json!({"from": args.from, "to": args.to}),
            result.is_ok(),
        )?;
        result.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "dry_run": false, "renamed": args.to }))
    }

    #[tool(
        description = "Delete a file, link (never followed) or empty folder on an SSH host (SPEC-0253); a non-empty folder only with `recursive: true`. `/`, the home folder and folders that hold it are always refused. dry_run defaults to true and reports how many entries a folder holds (needs `ssh`); dry_run=false needs the user-granted `ssh` right and is logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn remote_delete(
        &self,
        Parameters(args): Parameters<RemoteDeleteArgs>,
    ) -> Result<CallToolResult, McpError> {
        idecraft_remote::check_path(&args.path)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let recursive = args.recursive.unwrap_or(false);
        self.require(idecraft_core::Grant::Ssh).await?;
        let r = self.remote(&args.host);
        if args.dry_run.unwrap_or(true) {
            let path = args.path.clone();
            let entries = tokio::task::spawn_blocking(move || r.count_entries(&path))
                .await
                .map_err(|e| McpError::internal_error(e.to_string(), None))?
                .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
            return json_result(serde_json::json!({
                "dry_run": true,
                "would_delete": { "host": args.host, "path": args.path, "entries_inside": entries, "needs_recursive": entries > 0 },
            }));
        }
        let path = args.path.clone();
        let result = tokio::task::spawn_blocking(move || r.delete(&path, recursive))
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.remote_log(
            "remote_delete",
            &args.host,
            serde_json::json!({"path": args.path, "recursive": recursive}),
            result.is_ok(),
        )?;
        result.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "dry_run": false, "deleted": args.path }))
    }

    #[tool(
        description = "Start IDECraft's backend on an SSH host for a project folder there (SPEC-0158): `idecraft mcp <folder>` runs on the host, so search, inspections, language servers and builds work where the code is. It uses an IDECraft of the same version found on the host (`~/.cache/idecraft/bin/idecraft-<version>` or `idecraft` on PATH), else uploads this IDECraft when the host has the same system and processor, else says what to install. dry_run defaults to true and reports the platforms and the plan; dry_run=false needs the user-granted `ssh` and `run` rights, is logged in `.idecraft/agent-log.jsonl` and returns how it was installed, the backend's version and its tools. Call them with `remote_backend_call`."
    )]
    async fn remote_backend_start(
        &self,
        Parameters(args): Parameters<RemoteBackendArgs>,
    ) -> Result<CallToolResult, McpError> {
        let r = self.remote(&args.host);
        let version = env!("CARGO_PKG_VERSION");
        let binary =
            std::env::current_exe().map_err(|e| McpError::internal_error(e.to_string(), None))?;
        if args.dry_run.unwrap_or(true) {
            return json_result(serde_json::json!({
                "dry_run": true,
                "local_platform": idecraft_remote::local_platform(),
                "version": version,
                "would": format!(
                    "use IDECraft {version} on {} (~/{} or PATH), else upload {} if the host is {}, then run `idecraft mcp {}` there",
                    args.host,
                    idecraft_remote::backend_path(idecraft_remote::BACKEND_DIR, version),
                    binary.display(),
                    idecraft_remote::local_platform(),
                    args.folder
                ),
            }));
        }
        self.require(idecraft_core::Grant::Ssh).await?;
        self.require(idecraft_core::Grant::Run).await?;
        let folder = args.folder.clone();
        let started = tokio::task::spawn_blocking(move || {
            let installed = idecraft_remote::ensure_backend(
                &r,
                idecraft_remote::BACKEND_DIR,
                version,
                &binary,
            )?;
            let backend = idecraft_remote::Backend::start(&r, installed.path(), &folder)?;
            Ok::<_, idecraft_remote::RemoteError>((installed, backend))
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let root = self.workspace.root().to_path_buf();
        self.log(
            &root,
            serde_json::json!({
                "time": unix_time(), "tool": "remote_backend_start",
                "host": args.host, "folder": args.folder, "ok": started.is_ok(),
            }),
        )?;
        let (installed, backend) =
            started.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let tools: Vec<&str> = backend.tools.iter().map(|(n, _)| n.as_str()).collect();
        let answer = serde_json::json!({
            "installed": match &installed {
                idecraft_remote::Installed::Present(_) => "present",
                idecraft_remote::Installed::Uploaded(_) => "uploaded",
            },
            "path": installed.path(),
            "server": backend.server,
            "tools": tools,
        });
        if let Ok(mut map) = self.backends.lock() {
            map.insert(format!("{}|{}", args.host, args.folder), backend);
        }
        json_result(answer)
    }

    #[tool(
        description = "Call a tool of an IDECraft backend started with `remote_backend_start` (SPEC-0158), e.g. `search_in_files`, `inspect_code`, `workspace_info` on the host's project; the backend applies the host project's own agent rights. Needs the user-granted `ssh` right; the call (not its arguments) is logged in `.idecraft/agent-log.jsonl`."
    )]
    async fn remote_backend_call(
        &self,
        Parameters(args): Parameters<RemoteBackendCallArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        // An open remote project runs the tool on its host through its session, with the host
        // project's rights (SPEC-0318 behaviour 29); no second backend is started.
        if self.remote_connection(&args.host, &args.folder).is_some() {
            let arguments = if args.arguments.is_null() {
                serde_json::json!({})
            } else {
                args.arguments.clone()
            };
            let answer = self
                .host_call(
                    &args.host,
                    &args.folder,
                    "mcp.call",
                    serde_json::json!({ "tool": args.tool, "arguments": arguments }),
                )
                .await;
            let root = self.workspace.root().to_path_buf();
            self.log(
                &root,
                serde_json::json!({
                    "time": unix_time(), "tool": "remote_backend_call", "session": true,
                    "host": args.host, "folder": args.folder, "call": args.tool, "ok": answer.is_ok(),
                }),
            )?;
            return json_result(answer?["result"].clone());
        }
        let key = format!("{}|{}", args.host, args.folder);
        let backends = self.backends.clone();
        let (tool, arguments) = (args.tool.clone(), args.arguments.clone());
        let answer = tokio::task::spawn_blocking(move || {
            let mut map = backends
                .lock()
                .map_err(|_| "the backends are not available".to_owned())?;
            let backend = map.get_mut(&key).ok_or_else(|| {
                "no backend for this host and folder; start it with remote_backend_start".to_owned()
            })?;
            let arguments = if arguments.is_null() {
                serde_json::json!({})
            } else {
                arguments
            };
            backend.call(&tool, arguments).map_err(|e| e.to_string())
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let root = self.workspace.root().to_path_buf();
        self.log(
            &root,
            serde_json::json!({
                "time": unix_time(), "tool": "remote_backend_call",
                "host": args.host, "folder": args.folder, "call": args.tool, "ok": answer.is_ok(),
            }),
        )?;
        json_result(answer.map_err(|e| McpError::invalid_params(e, None))?)
    }

    #[tool(
        description = "Stop an IDECraft backend started with `remote_backend_start` (SPEC-0158). Returns whether one was running."
    )]
    async fn remote_backend_stop(
        &self,
        Parameters(args): Parameters<RemoteBackendArgs>,
    ) -> Result<CallToolResult, McpError> {
        // Ending a backend on a host needs the right that reached it (SPEC-0053 v8).
        self.require(idecraft_core::Grant::Ssh).await?;
        let key = format!("{}|{}", args.host, args.folder);
        let stopped = self
            .backends
            .lock()
            .map(|mut m| m.remove(&key).is_some())
            .unwrap_or(false);
        json_result(serde_json::json!({ "stopped": stopped }))
    }

    #[tool(
        description = "Open a folder on an SSH host as a remote project (SPEC-0317, Experimental): IDECraft's backend `idecraft serve --stdio` of this very build runs on the host (found there or uploaded when the host has the same system and processor, an uploaded copy checked by SHA-256 before each start) and owns the documents; the session survives network breaks. dry_run defaults to true and returns the plan without connecting (host as resolved from the SSH configuration, this build's platform and SHA-256, where the backend is looked for). dry_run=false needs the user-granted `ssh` and `run` rights, is logged in `.idecraft/agent-log.jsonl` and keeps the session in this server (no window opens over stdio). See `remote_projects`, `remote_documents`, `remote_project_reconnect`, `remote_project_close`."
    )]
    async fn remote_project_open(
        &self,
        Parameters(args): Parameters<RemoteProjectOpenArgs>,
    ) -> Result<CallToolResult, McpError> {
        let binary =
            std::env::current_exe().map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let version = env!("CARGO_PKG_VERSION");
        if !idecraft_remote::bootstrap::absolute_folder(args.folder.trim()) {
            return Err(McpError::invalid_params(
                "folder must be an absolute path on the host",
                None,
            ));
        }
        let spec = idecraft_remote::HostSpec::parse(&args.host)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        if !spec.is_ssh() {
            return self.open_other_host(spec, args, binary).await;
        }
        if args.dry_run.unwrap_or(true) {
            let (host, extra) = (args.host.clone(), self.ssh_extra.clone());
            let info =
                tokio::task::spawn_blocking(move || idecraft_remote::describe(&host, &extra))
                    .await
                    .map_err(|e| McpError::internal_error(e.to_string(), None))?;
            let sha = idecraft_remote::sha256_file(&binary)
                .map_err(|e| McpError::internal_error(e.to_string(), None))?;
            return json_result(serde_json::json!({
                "dry_run": true,
                "host": {"alias": info.alias, "user": info.user, "hostname": info.hostname, "port": info.port},
                "folder": args.folder,
                "local_platform": idecraft_remote::local_platform(),
                "version": version,
                "sha256": sha,
                "backend": format!(
                    "~/{}-{} on the host or `idecraft` {version} on its PATH; uploaded when missing and the host is {}; an uploaded copy is checked by SHA-256 before each start",
                    idecraft_remote::backend_path(idecraft_remote::BACKEND_DIR, version),
                    idecraft_remote::fingerprint(&binary),
                    idecraft_remote::local_platform()
                ),
                "would": format!("run `idecraft serve --stdio` on {} over ssh and open {} as the session's project", args.host, args.folder),
                "needs": ["ssh", "run"],
            }));
        }
        self.require(idecraft_core::Grant::Ssh).await?;
        self.require(idecraft_core::Grant::Run).await?;
        let root = self.workspace.root().to_path_buf();
        // With a window, the project opens in a project window of its own (SPEC-0317 v3
        // behaviour 20); a window that cannot leaves the session to this server.
        if let Some(window) = &self.window {
            let (tx, rx) = tokio::sync::oneshot::channel();
            window.open_remote_project(args.host.clone(), args.folder.clone(), tx);
            if let Ok(opened) = rx.await {
                self.log(
                    &root,
                    serde_json::json!({
                        "time": unix_time(), "tool": "remote_project_open", "window": true,
                        "host": args.host, "folder": args.folder, "ok": opened.is_ok(),
                    }),
                )?;
                return json_result(opened.map_err(|e| McpError::invalid_params(e, None))?);
            }
        }
        let key = format!("{}|{}", args.host, args.folder);
        let r = self.remote(&args.host);
        let folder = args.folder.clone();
        let recovery = idecraft_core::user_config_dir().map(|d| d.join("remote/recovery"));
        let opened = tokio::task::spawn_blocking(move || {
            let mut p = idecraft_remote::RemoteProject::open(
                r,
                &folder,
                &binary,
                idecraft_remote::ServeOptions::default(),
                recovery,
            )?;
            let described = p.describe();
            Ok::<_, idecraft_remote::RemoteError>((p, described))
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?;
        self.log(
            &root,
            serde_json::json!({
                "time": unix_time(), "tool": "remote_project_open",
                "host": args.host, "folder": args.folder, "ok": opened.is_ok(),
            }),
        )?;
        let (project, described) =
            opened.map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        if let Ok(mut map) = self.remote_projects.lock() {
            map.insert(key, project);
        }
        json_result(described)
    }

    #[tool(
        description = "What opening a host would use, without changing anything (SPEC-0321, Experimental): the transport, the host's system and processor, and the backend build picked for it. SSH, Docker, Podman, Kubernetes and WSL hosts are asked with `uname` or PowerShell; a paired host says only whether it is paired. Never starts or uploads a backend. Needs the user-granted `ssh` right."
    )]
    async fn remote_host_probe(
        &self,
        Parameters(args): Parameters<RemoteHostArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let spec = idecraft_remote::HostSpec::parse(&args.host)
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        let extra = self.ssh_extra.clone();
        let binary =
            std::env::current_exe().map_err(|e| McpError::internal_error(e.to_string(), None))?;
        let label = spec.label();
        let answer = tokio::task::spawn_blocking(move || -> Result<serde_json::Value, String> {
            if let idecraft_remote::HostSpec::Paired { address } = &spec {
                let paired =
                    idecraft_remote::paired::is_paired(address).map_err(|e| e.to_string())?;
                return Ok(serde_json::json!({ "transport": "paired", "paired": paired }));
            }
            let route =
                idecraft_remote::HostRoute::for_spec(&spec, &extra).map_err(|e| e.to_string())?;
            let found = idecraft_remote::bootstrap::detect(&route).map_err(|e| e.to_string())?;
            let build = idecraft_remote::bootstrap::select_build(&found, &binary)
                .map(|p| p.display().to_string());
            Ok(serde_json::json!({
                "platform": found.platform,
                "windows": found.family == idecraft_remote::HostFamily::Windows,
                "target": idecraft_remote::bootstrap::target_triple(&found.platform),
                "build": build.as_ref().ok(),
                "refusal": build.as_ref().err().map(ToString::to_string),
            }))
        })
        .await
        .map_err(|e| McpError::internal_error(e.to_string(), None))?
        .map_err(|e| McpError::invalid_params(e, None))?;
        json_result(serde_json::json!({ "host": label, "answer": answer }))
    }

    #[tool(
        description = "The hosts this window is paired with (SPEC-0321, Experimental): address, key fingerprint and when it was paired. Never a key."
    )]
    async fn remote_hosts_paired(&self) -> Result<CallToolResult, McpError> {
        let hosts = tokio::task::spawn_blocking(idecraft_remote::paired::paired_hosts)
            .await
            .map_err(|e| McpError::internal_error(e.to_string(), None))?
            .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        json_result(serde_json::json!({ "hosts": hosts }))
    }

    #[tool(
        description = "Start pairing this window with a host running `idecraft serve --pair` (SPEC-0321, Experimental): runs the handshake with the host's short code and shows six digits in the window. Only the user can confirm them there; no tool can, and without a window the call is refused. Answers once the user decided. Needs the user-granted `ssh` right; logged without the code."
    )]
    async fn remote_pair_start(
        &self,
        Parameters(args): Parameters<RemotePairArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let refused = || {
            McpError::invalid_params(
                "pairing needs a window: the user compares and confirms six digits there",
                None,
            )
        };
        let Some(window) = &self.window else {
            return Err(refused());
        };
        let (tx, rx) = tokio::sync::oneshot::channel();
        window.pair_remote_host(args.address.clone(), args.code, tx);
        let outcome = rx.await.map_err(|_| refused())?;
        self.log(
            self.workspace.root(),
            serde_json::json!({
                "time": unix_time(), "tool": "remote_pair_start",
                "address": args.address, "ok": outcome.is_ok(),
            }),
        )?;
        let fingerprint = outcome.map_err(|e| McpError::invalid_params(e, None))?;
        json_result(serde_json::json!({ "paired": args.address, "fingerprint": fingerprint }))
    }

    #[tool(
        description = "Forget a paired host (SPEC-0321, Experimental): removes its pinned key from this window; pairing again needs a new code from the host. Needs the user-granted `ssh` right; logged."
    )]
    async fn remote_pair_forget(
        &self,
        Parameters(args): Parameters<RemoteForgetArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let address = args.address.clone();
        let removed =
            tokio::task::spawn_blocking(move || idecraft_remote::paired::forget_paired(&address))
                .await
                .map_err(|e| McpError::internal_error(e.to_string(), None))?
                .map_err(|e| McpError::invalid_params(e.to_string(), None))?;
        self.log(
            self.workspace.root(),
            serde_json::json!({
                "time": unix_time(), "tool": "remote_pair_forget",
                "address": args.address, "removed": removed,
            }),
        )?;
        json_result(serde_json::json!({ "removed": removed }))
    }

    #[tool(
        description = "List the devices paired with this machine (SPEC-0324, Experimental): name, fingerprint, rights, when paired. Never a key. Needs the user-granted `ssh` right; logged."
    )]
    async fn device_list(&self) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let list = paired_task(idecraft_remote::paired::devices).await?;
        self.log_device("device_list", None)?;
        json_result(serde_json::json!({ "devices": list }))
    }

    #[tool(
        description = "Narrow the rights of a paired device (SPEC-0324, Experimental): only a subset of its rights; widening is the user's, with `idecraft serve --rights`. A live session of the device ends so that nothing keeps a right that was taken. Needs the user-granted `ssh` right; logged."
    )]
    async fn device_restrict(
        &self,
        Parameters(args): Parameters<DeviceRestrictArgs>,
    ) -> Result<CallToolResult, McpError> {
        self.require(idecraft_core::Grant::Ssh).await?;
        let (fingerprint, rights) = (args.fingerprint.clone(), args.rights);
        let kept =
            paired_task(move || idecraft_remote::paired::device_restrict(&fingerprint, &rights))
                .await?;
        self.log_device("device_restrict", Some(&args.fingerprint))?;
        json_result(serde_json::json!({ "fingerprint": args.fingerprint, "rights": kept }))
    }

